window.PM3_SETS = window.PM3_SETS || {};
window.PM3_SETS["json-r7-zenki-1"] = [{"id":"01","chapter":"9.資材・在庫管理","question":{"japanese":"量産開始後の調達業務に関する記述として最も不適切なものは、次のうちどれか。","vietnamese":"Trong các mô tả về hoạt động mua sắm sau khi bắt đầu sản xuất hàng loạt, mô tả nào KHÔNG phù hợp nhất?","furigana":"量産[りょうさん]開始後[かいしご]の調達[ちょうたつ]業務[ぎょうむ]に関する[かんする]記述[きじゅつ]として最も[もっとも]不適切[ふてきせつ]なものは、次[つぎ]のうちどれか。"},"options":[{"key":"ア","japanese":"生産に必要な材料の在庫量を適切に維持する活動","vietnamese":"Hoạt động duy trì hợp lý lượng tồn kho vật liệu cần thiết cho sản xuất","furigana":"生産[せいさん]に必要[ひつよう]な材料[ざいりょう]の在庫量[ざいこりょう]を適切[てきせつ]に維持[いじ]する活動[かつどう]"},{"key":"イ","japanese":"材料の受入れと検査を行う活動","vietnamese":"Hoạt động tiếp nhận và kiểm tra vật liệu","furigana":"材料[ざいりょう]の受入れ[うけいれ]と検査[けんさ]を行う[おこなう]活動[かつどう]"},{"key":"ウ","japanese":"部品ごとの内外製区分を決める活動","vietnamese":"Hoạt động quyết định phân loại tự sản xuất hay mua ngoài cho từng linh kiện","furigana":"部品[ぶひん]ごとの内外製[ないがいせい]区分[くぶん]を決める[きめる]活動[かつどう]"},{"key":"エ","japanese":"自社の生産計画に連動した発注を行う活動","vietnamese":"Hoạt động đặt hàng gắn liền với kế hoạch sản xuất của công ty","furigana":"自社[じしゃ]の生産[せいさん]計画[けいかく]に連動[れんどう]した発注[はっちゅう]を行う[おこなう]活動[かつどう]"}],"correct_answer":"ウ","explanation":{"correct_reason":"Đề hỏi mô tả KHÔNG phù hợp. Việc quyết định tự sản xuất hay mua ngoài (内外製区分) thuộc giai đoạn thiết kế và chuẩn bị sản xuất, trước khi bắt đầu sản xuất hàng loạt. Sau khi đã sản xuất hàng loạt, mua sắm chủ yếu là lập kế hoạch vật tư, đặt hàng, nhận hàng, kiểm tra và quản lý tồn kho theo kế hoạch sản xuất.","incorrect_reasons":{"ア":"Sai vì duy trì lượng tồn kho vật liệu phù hợp là chức năng cốt lõi của mua sắm sau khi sản xuất hàng loạt.","イ":"Sai vì tiếp nhận và kiểm tra vật liệu là công việc thường ngày của bộ phận mua sắm/nhận hàng.","ウ":"Đây là đáp án đúng vì phân loại tự sản xuất hay mua ngoài được quyết định trước khi sản xuất hàng loạt.","エ":"Sai vì đặt hàng dựa trên kế hoạch sản xuất là cách làm chuẩn của mua sắm trong sản xuất hàng loạt."}},"key_knowledge":["Nghiệp vụ mua sắm (調達業務) được phân định thành 2 giai đoạn rõ rệt: giai đoạn chuẩn bị sản xuất (生産準備段階) mang tính chiến lược và giai đoạn sau khi bắt đầu sản xuất hàng loạt (量産開始後) mang tính vận hành tác nghiệp thường nhật.","Quyết định phân loại tự sản xuất hay mua ngoài (内外製区分 / Make or Buy) phải được hoàn tất trong giai đoạn thiết kế quy trình và chuẩn bị sản xuất, căn cứ vào năng lực máy móc (設備能力), chi phí gia công, công nghệ độc quyền (コア技術) và dung lượng chuyền.","Trước khi sản xuất hàng loạt (量産前), bộ phận mua sắm tập trung lựa chọn nhà cung cấp (サプライヤー選定), thỏa thuận giá cơ sở (契約締結), làm mẫu thử (試作) và chuẩn bị khuôn gá (金型手配).","Sau khi sản xuất hàng loạt (量産開始後), hoạt động mua sắm chuyển sang chu kỳ lặp lại gồm: nhận kế hoạch sản xuất, phát hành đơn đặt hàng (発注), theo dõi tiến độ giao hàng (納期管理), tiếp nhận (受入れ), kiểm tra (受入検査) và thanh toán (検収).","Đặt hàng trong sản xuất hàng loạt luôn phải liên kết trực tiếp với kế hoạch sản xuất (生産計画) thông qua hệ thống hoạch định nhu cầu vật tư (MRP) hoặc cơ chế kéo (Kanban), đảm bảo cấp đúng loại linh kiện vào đúng thời điểm (Just-in-Time).","Duy trì tồn kho thích hợp (在庫量の適正維持) là chức năng trọng yếu của mua sắm khi đã chạy hàng loạt, cân bằng giữa việc tránh dừng chuyền do thiếu linh kiện (欠品) và hạn chế ứ đọng chi phí lưu kho bằng tồn kho an toàn (安全在庫) hoặc điểm đặt hàng (発注点).","Nghiệp vụ tiếp nhận và kiểm tra (受入れと検査) tại xưởng sau khi sản xuất hàng loạt bao gồm đối chiếu số lượng thực tế với phiếu giao hàng (納品書), kiểm tra quy cách ngoại quan hoặc kiểm tra lấy mẫu (抜取検査) trước khi cho phép nhập kho chính thức."],"exam_traps":["Đánh tráo thời điểm: việc thuộc giai đoạn chuẩn bị sản xuất bị đưa vào giai đoạn sản xuất hàng loạt.","Đánh tráo phạm vi: quyết định tự sản xuất hay mua ngoài bị coi là hoạt động mua sắm thường ngày.","Câu hỏi dạng 最も不適切 yêu cầu chọn phương án sai."],"vocabulary":[{"word":"量産","reading":"りょうさん","meaning":"sản xuất hàng loạt"},{"word":"調達","reading":"ちょうたつ","meaning":"mua sắm, cung ứng"},{"word":"在庫量","reading":"ざいこりょう","meaning":"lượng tồn kho"},{"word":"受入れ","reading":"うけいれ","meaning":"tiếp nhận"},{"word":"検査","reading":"けんさ","meaning":"kiểm tra"},{"word":"内外製区分","reading":"ないがいせいくぶん","meaning":"phân loại tự sản xuất hay mua ngoài"},{"word":"発注","reading":"はっちゅう","meaning":"đặt hàng"},{"word":"連動","reading":"れんどう","meaning":"liên kết, gắn với nhau"},{"word":"不適切","reading":"ふてきせつ","meaning":"không phù hợp"},{"word":"量産開始後","reading":"りょうさんかいしご","meaning":"sau khi bắt đầu sản xuất hàng loạt"},{"word":"調達業務","reading":"ちょうたつぎょうむ","meaning":"nghiệp vụ mua sắm, cung ứng"},{"word":"材料","reading":"ざいりょう","meaning":"vật liệu"},{"word":"部品","reading":"ぶひん","meaning":"linh kiện"},{"word":"区分","reading":"くぶん","meaning":"phân loại, phân chia"},{"word":"自社","reading":"じしゃ","meaning":"công ty mình"},{"word":"活動","reading":"かつどう","meaning":"hoạt động"},{"word":"適切","reading":"てきせつ","meaning":"thích hợp, hợp lý"},{"word":"記述","reading":"きじゅつ","meaning":"mô tả, diễn đạt"},{"word":"最も","reading":"もっとも","meaning":"nhất"},{"word":"維持","reading":"いじ","meaning":"duy trì"},{"word":"決める","reading":"きめる","meaning":"quyết định"},{"word":"事前","reading":"じぜん","meaning":"trước (khi làm)"}]},{"id":"02","chapter":"6.作業管理","question":{"japanese":"作業管理における余裕の種類として最も不適切なものは、次のうちどれか。","vietnamese":"Trong các loại thời gian dư (余裕) trong quản lý công việc, loại nào KHÔNG phù hợp nhất?","furigana":"作業[さぎょう]管理[かんり]における余裕[よゆう]の種類[しゅるい]として最も[もっとも]不適切[ふてきせつ]なものは、次[つぎ]のうちどれか。"},"options":[{"key":"ア","japanese":"準備余裕","vietnamese":"Thời gian dư chuẩn bị","furigana":"準備[じゅんび]余裕[よゆう]"},{"key":"イ","japanese":"用達余裕","vietnamese":"Thời gian dư đi lại/sử dụng (cách gọi không chuẩn)","furigana":"用達[ようたつ]余裕[よゆう]"},{"key":"ウ","japanese":"疲労余裕","vietnamese":"Thời gian dư do mệt mỏi","furigana":"疲労[ひろう]余裕[よゆう]"},{"key":"エ","japanese":"作業余裕","vietnamese":"Thời gian dư trong công việc","furigana":"作業[さぎょう]余裕[よゆう]"}],"correct_answer":"ア","explanation":{"correct_reason":"Đề hỏi loại KHÔNG phù hợp. Trong phân loại 余裕 của quản lý công việc, các loại thường gặp là 疲労余裕, 作業余裕, 用達余裕 (thời gian dư cho nhu cầu cá nhân/đi lại) và 管理余裕. 準備余裕 không thuộc nhóm 余裕 này, mà là thời gian chuẩn bị trong định mức thời gian. Vì vậy ア là phương án không phù hợp.","incorrect_reasons":{"ア":"Đây là đáp án đúng vì 準備余裕 không phải loại 余裕 trong phân loại này.","イ":"Sai vì 用達余裕 là loại thời gian dư hợp lệ cho nhu cầu cá nhân/đi lại.","ウ":"Sai vì 疲労余裕 là loại thời gian dư hợp lệ để bù mệt mỏi.","エ":"Sai vì 作業余裕 là loại thời gian dư hợp lệ do điều kiện làm việc."}},"key_knowledge":["Cấu trúc thời gian tiêu chuẩn (標準時間 - Standard Time): Gồm hai thành phần cốt lõi là thời gian làm việc thuần (正味時間) và thời gian hao phí cho phép/dự phòng (余裕時間), với công thức cơ bản: 標準時間 = 正味時間 + 余裕時間.","Hệ thống phân loại dung sai (余裕の分類): Được chia thành 2 nhóm lớn là dung sai chung (一般余裕) áp dụng rộng rãi cho mọi công việc và dung sai quản lý/nơi làm việc (職場余裕 / 管理余裕) phụ thuộc vào môi trường tổ chức sản xuất.","Dung sai con người (人的余裕): Là một nhánh của 一般余裕, chia thành 2 loại gồm dung sai sinh lý (用達余裕 - uống nước, lau mồ hôi, đi vệ sinh, thông thường chiếm 2-5%) và dung sai mệt mỏi (疲労余裕 - nghỉ ngơi hồi phục thể lực sau thao tác nặng hoặc căng thẳng thần kinh).","Dung sai thao tác (作業余裕): Cũng thuộc 一般余裕, là thời gian dành cho các công việc phát sinh không theo chu kỳ cố định nhưng tất yếu trong quá trình làm việc, ví dụ: gạt phoi vụn kim loại, nhặt linh kiện rơi, hoặc tra dầu đột xuất vào đồ gá.","Dung sai quản lý (管理余裕 / 職場余裕): Phát sinh do sự điều hành của cấp trên hoặc sự gián đoạn của chuỗi cung ứng nội bộ, ví dụ: họp giao ban đầu ca (朝礼), chờ bản vẽ chỉ thị thao tác, chờ xe chở bán thành phẩm đến.","Bản chất của thời gian chuẩn bị: Thời gian chuẩn bị và thu dọn (準備・後始末時間 / 段取時間) được tính như một khoản thời gian định mức riêng biệt theo từng lô sản xuất (ロット), bản thân nó cũng có thời gian thuần và thời gian dự phòng, hoàn toàn không có thuật ngữ chuẩn là '準備余裕'.","Phương pháp tính tỷ lệ dung sai (余裕率): Gồm phương pháp ngoại suy (外掛け法: Tỷ lệ = 余裕時間 / 正味時間) thường dùng nhất trong thực tế, và phương pháp nội suy (内掛け法: Tỷ lệ = 余裕時間 / 標準時間).","Ý nghĩa quản trị thực tế: Việc thiết lập chính xác các loại 余裕 giúp loại bỏ tranh cãi về định mức năng suất (標準出来高) giữa chuyền trưởng và công nhân, đồng thời là cơ sở để cân bằng chuyền (ラインバランシング) chuẩn xác."],"exam_traps":["Đưa 準備余裕 vào nhóm 余裕 để tạo phương án sai.","Câu hỏi 最も不適切 chọn phương án sai.","Các loại 余裕 có tên gần giống nhau, cần nhớ chính xác."],"vocabulary":[{"word":"作業管理","reading":"さぎょうかんり","meaning":"quản lý công việc"},{"word":"余裕","reading":"よゆう","meaning":"thời gian dư"},{"word":"準備余裕","reading":"じゅんびよゆう","meaning":"thời gian dư chuẩn bị"},{"word":"用達余裕","reading":"ようたつよゆう","meaning":"thời gian dư cho nhu cầu cá nhân/đi lại"},{"word":"疲労余裕","reading":"ひろうよゆう","meaning":"thời gian dư do mệt mỏi"},{"word":"作業余裕","reading":"さぎょうよゆう","meaning":"thời gian dư do điều kiện công việc"},{"word":"種類","reading":"しゅるい","meaning":"loại"},{"word":"管理余裕","reading":"かんりよゆう","meaning":"thời gian dư quản lý"},{"word":"一般的","reading":"いっぱんてき","meaning":"mang tính phổ biến"},{"word":"内容","reading":"ないよう","meaning":"nội dung"},{"word":"対象","reading":"たいしょう","meaning":"đối tượng"},{"word":"標準時間","reading":"ひょうじゅんじかん","meaning":"thời gian chuẩn"},{"word":"余裕率","reading":"よゆうりつ","meaning":"tỷ lệ thời gian dư"},{"word":"実測","reading":"じっそく","meaning":"đo thực tế"},{"word":"正常時間","reading":"せいじょうじかん","meaning":"thời gian bình thường"},{"word":"手待ち","reading":"てまち","meaning":"chờ việc"},{"word":"作業者","reading":"さぎょうしゃ","meaning":"người làm việc"},{"word":"作業条件","reading":"さぎょうじょうけん","meaning":"điều kiện làm việc"},{"word":"疲労回復","reading":"ひろうかいふく","meaning":"hồi phục mệt mỏi"},{"word":"生理","reading":"せいり","meaning":"sinh lý"}]},{"id":"03","chapter":"6.作業管理","question":{"japanese":"サーブリッグ分析は、人間が行う作業動作を改善する補助手段として、あらゆる作業に共通と考えられる基本動作を18に分類し、これにサーブリッグという名称を与え、記号化した。サーブリッグ記号は、改善の着眼を考慮して、3種類に大別される。その第一類は、仕事をする上で必要な動作であるが、理想は動作を不必要とすることである。この第一類の動作には、手を伸ばす、つかむ、運ぶ、組み合わす、（ ）、分解する、放す、調べるという8つの基本動作がある。","vietnamese":"Phân tích Therblig chia các động tác cơ bản chung cho mọi công việc thành 18 loại, đặt tên là Therblig và ký hiệu hóa. Ký hiệu Therblig chia thành 3 nhóm. Nhóm thứ nhất là các động tác cần thiết để làm việc, nhưng lý tưởng là làm cho chúng không cần thiết. Nhóm này gồm 8 động tác: vươn tay, nắm, mang, lắp ghép, ( ), tháo rời, thả, kiểm tra. Từ nào phù hợp với chỗ trống?","furigana":"サーブリッグ分析[ぶんせき]は、人間[にんげん]が行う[おこなう]作業[さぎょう]動作[どうさ]を改善[かいぜん]する補助[ほじょ]手段[しゅだん]として、あらゆる作業[さぎょう]に共通[きょうつう]と考え[かんがえ]られる基本[きほん]動作[どうさ]を18に分類[ぶんるい]し、これにサーブリッグという名称[めいしょう]を与え[あたえ]、記号化[きごうか]した。サーブリッグ記号[きごう]は、改善[かいぜん]の着眼[ちゃくがん]を考慮[こうりょ]して、3種類[しゅるい]に大別[たいべつ]される。その第一類[だいいちるい]は、仕事[しごと]をする上[うえ]で必要[ひつよう]な動作[どうさ]であるが、理想[りそう]は動作[どうさ]を不必要[ふひつよう]とすることである。この第一類[だいいちるい]の動作[どうさ]には、手[て]を伸ばす[のばす]、つかむ、運ぶ[はこぶ]、組み合わす[くみあわす]、（ ）、分解[ぶんかい]する、放す[ほかす]、調べる[しらべる]という8つの基本[きほん]動作[どうさ]がある。"},"options":[{"key":"ア","japanese":"探す","vietnamese":"Tìm kiếm","furigana":"探す[さがす]"},{"key":"イ","japanese":"使う","vietnamese":"Sử dụng","furigana":"使う[つかう]"},{"key":"ウ","japanese":"位置決め","vietnamese":"Định vị","furigana":"位置決め[いちぎめ]"},{"key":"エ","japanese":"保持","vietnamese":"Giữ","furigana":"保持[ほじ]"}],"correct_answer":"イ","explanation":{"correct_reason":"Nhóm thứ nhất của Therblig gồm: 手を伸ばす, つかむ, 運ぶ, 組み合わす, 使う, 分解する, 放す, 調べる. Vì vậy chỗ trống là 使う.","incorrect_reasons":{"ア":"Sai vì 探す thuộc nhóm động tác không cần thiết/làm chậm công việc.","イ":"Đây là đáp án đúng, 使う là động tác cơ bản thứ năm của nhóm thứ nhất.","ウ":"Sai vì 位置決め thuộc nhóm thứ hai (động tác hỗ trợ).","エ":"Sai vì 保持 thuộc nhóm thứ hai (động tác hỗ trợ)."}},"key_knowledge":["Phân tích Therblig (サーブリッグ分析) do Gilbreth sáng lập, chia nhỏ mọi cử động cơ thể của con người khi làm việc thành 18 động tác cơ bản (基本動作) được gán ký hiệu để quan sát và cải tiến.","18 động tác Therblig được gom thành 3 nhóm lớn theo phương diện cải tiến: Nhóm 1 (第1類 - trực tiếp xúc tiến công việc), Nhóm 2 (第2類 - động tác phụ trợ làm chậm công việc), và Nhóm 3 (第3類 - động tác hoàn toàn không tạo giá trị).","Nhóm 1 (第1類) gồm đúng 8 động tác cơ bản tác động trực tiếp tạo ra sản phẩm: Vươn tay (手を伸ばす), Nắm (つかむ), Vận chuyển (運ぶ), Lắp ghép (組み合わす), Sử dụng (使う), Tháo rời (分解する), Thả tay (放す), và Kiểm tra (調べる).","Nhóm 2 (第2類) gồm các thao tác hỗ trợ làm kéo dài thời gian chu kỳ: Tìm kiếm (探す), Tìm thấy (見出す), Lựa chọn (選ぶ), Định vị (位置決め), Giữ cố định (保持), Định vị sẵn (前向き/準備位置決め). Nhóm này cần giảm thiểu bằng 5S hoặc trang bị đồ gá (治具).","Nhóm 3 (第3類) gồm các yếu tố lãng phí hoặc trì hoãn hoàn toàn không sinh công: Nghỉ ngơi (休止), Trì hoãn không tránh được (不可避の遅れ), Trì hoãn tránh được (可避の遅れ), Suy nghĩ tính toán (考える). Mục tiêu cải tiến là triệt tiêu hoàn toàn nhóm này.","Phân biệt giữa 'Sử dụng' (使う - Nhóm 1) và 'Giữ' (保持 - Nhóm 2): 'Sử dụng' làm thay đổi hình dáng, trạng thái linh kiện (ví dụ: siết ốc bằng tua vít); còn 'Giữ' chỉ là dùng tay cố định vật thể và có thể thay thế bằng kẹp gá.","Khác với Phân tích quy trình (工程分析) nhìn tổng thể dòng chảy từ gia công đến lưu kho ở cấp độ vĩ mô, Phân tích Therblig tập trung vào cấp độ vi mô cực nhỏ (micro-motion) của mắt, tay và cơ thể người vận hành.","Chiến lược cải tiến thao tác chuẩn trong sản xuất: Triệt tiêu Nhóm 3 trước tiên, sau đó cắt giảm và chuyển đổi Nhóm 2 sang công cụ phụ trợ, cuối cùng là rút ngắn khoảng cách và tinh gọn Nhóm 1."],"exam_traps":["Nhầm 使う với 保持 vì cả hai đều là động tác tay.","Nhầm nhóm 1 với nhóm 2: 位置決め và 保持 thuộc nhóm hỗ trợ.","Đề có thể đánh tráo thứ tự hoặc số lượng động tác trong từng nhóm."],"vocabulary":[{"word":"動作研究","reading":"どうさけんきゅう","meaning":"nghiên cứu động tác"},{"word":"サーブリッグ分析","reading":"サーブリッグぶんせき","meaning":"phân tích Therblig"},{"word":"基本動作","reading":"きほんどうさ","meaning":"động tác cơ bản"},{"word":"分類","reading":"ぶんるい","meaning":"phân loại"},{"word":"記号化","reading":"きごうか","meaning":"ký hiệu hóa"},{"word":"着眼","reading":"ちゃくがん","meaning":"góc nhìn, điểm chú ý"},{"word":"大別","reading":"たいべつ","meaning":"phân chia đại khái"},{"word":"伸ばす","reading":"のばす","meaning":"vươn ra"},{"word":"つかむ","reading":"つかむ","meaning":"nắm"},{"word":"運ぶ","reading":"はこぶ","meaning":"mang, vận chuyển"},{"word":"組み合わす","reading":"くみあわす","meaning":"lắp ghép"},{"word":"分解する","reading":"ぶんかいする","meaning":"tháo rời"},{"word":"放す","reading":"はなす","meaning":"thả ra"},{"word":"調べる","reading":"しらべる","meaning":"kiểm tra"},{"word":"位置決め","reading":"いちぎめ","meaning":"định vị"},{"word":"保持","reading":"ほじ","meaning":"giữ"},{"word":"探す","reading":"さがす","meaning":"tìm kiếm"},{"word":"サーブリッグ記号","reading":"サーブリッグきごう","meaning":"ký hiệu Therblig"},{"word":"第一類","reading":"だいいちるい","meaning":"nhóm thứ nhất"},{"word":"第二類","reading":"だいにるい","meaning":"nhóm thứ hai"},{"word":"第三類","reading":"だいさんるい","meaning":"nhóm thứ ba"},{"word":"補助手段","reading":"ほじょしゅだん","meaning":"phương tiện hỗ trợ"},{"word":"人間","reading":"にんげん","meaning":"con người"},{"word":"作業動作","reading":"さぎょうどうさ","meaning":"động tác làm việc"},{"word":"与える","reading":"あたえる","meaning":"đặt cho, ban cho"},{"word":"名称","reading":"めいしょう","meaning":"tên gọi"},{"word":"考慮","reading":"こうりょ","meaning":"cân nhắc, xem xét"},{"word":"理想","reading":"りそう","meaning":"lý tưởng"},{"word":"不必要","reading":"ふひつよう","meaning":"không cần thiết"},{"word":"手を伸ばす","reading":"てをのばす","meaning":"vươn tay"},{"word":"共通","reading":"きょうつう","meaning":"chung"},{"word":"改善の着眼","reading":"かいぜんのちゃくがん","meaning":"góc nhìn cải tiến"}]},{"id":"04","chapter":"6.作業管理","question":{"japanese":"時間研究に関する記述として最も適切なものは、次のうちどれか。なお、DMはDecimal Minuteである。","vietnamese":"Trong các mô tả về nghiên cứu thời gian, mô tả nào phù hợp nhất? Biết rằng DM là Decimal Minute.","furigana":"時間[じかん]研究[けんきゅう]に関する[かんする]記述[きじゅつ]として最も[もっとも]適切[てきせつ]なものは、次[つぎ]のうちどれか。なお、DMはDecimal Minuteである。"},"options":[{"key":"ア","japanese":"ストップウォッチ法の測定単位であるDM単位は、秒単位での測定よりも集計の計算が複雑となる。","vietnamese":"Đơn vị DM dùng trong phương pháp đồng hồ bấm giây có cách tính tổng hợp phức tạp hơn so với đơn vị giây.","furigana":"ストップウォッチ法[ほう]の測定[そくてい]単位[たんい]であるDM単位[たんい]は、秒[びょう]単位[たんい]での測定[そくてい]よりも集計[しゅうけい]の計算[けいさん]が複雑[ふくざつ]となる。"},{"key":"イ","japanese":"ストップウォッチ法の測定方法である継続法は、ステップごとにストップウォッチを0に戻して、各ステップの時間を直接求める方法である。","vietnamese":"Phương pháp liên tục trong phương pháp đồng hồ bấm giây là cách đưa đồng hồ về 0 sau mỗi bước để tìm trực tiếp thời gian từng bước.","furigana":"ストップウォッチ法[ほう]の測定[そくてい]方法[ほうほう]である継続法[けいぞくほう]は、ステップごとにストップウォッチを0に戻し[もどし]て、各[かく]ステップの時間[じかん]を直接[ちょくせつ]求める[もとめる]方法[ほうほう]である。"},{"key":"ウ","japanese":"観測した作業が標準的な作業ペースより速い場合におけるレイティング係数は、100よりも小さな値となる。","vietnamese":"Khi công việc quan sát nhanh hơn tốc độ chuẩn, hệ số đánh giá sẽ nhỏ hơn 100.","furigana":"観測[かんそく]した作業[さぎょう]が標準的[ひょうじゅんてき]な作業[さぎょう]ペースより速い[はやい]場合[ばあい]におけるレイティング係数[けいすう]は、100よりも小さな[ちいさな]値[ね]となる。"},{"key":"エ","japanese":"時間研究による改善において、バラツキが大きい要素作業に着目し、なぜバラツキが大きいのかを検討するためには、動作分析を行うと効果的である。","vietnamese":"Trong cải tiến bằng nghiên cứu thời gian, để tập trung vào nguyên công có độ biến thiên lớn và xem xét nguyên nhân, phân tích động tác là có hiệu quả.","furigana":"時間[じかん]研究[けんきゅう]による改善[かいぜん]において、バラツキが大きい[おおきい]要素[ようそ]作業[さぎょう]に着目[ちゃくもく]し、なぜバラツキが大きい[おおきい]のかを検討[けんとう]するためには、動作[どうさ]分析[ぶんせき]を行う[おこなう]と効果的[こうかてき]である。"}],"correct_answer":"エ","explanation":{"correct_reason":"Khi thời gian của một nguyên công biến thiên lớn, nguyên nhân thường nằm ở động tác, cách thao tác hoặc điều kiện làm việc. Phân tích động tác giúp loại bỏ động tác thừa, sắp xếp lại thao tác và giảm biến thiên.","incorrect_reasons":{"ア":"Sai vì DM chia 1 phút thành 100 đơn vị, thuận tiện cho tính toán thập phân hơn đơn vị giây.","イ":"Sai vì 継続法 bấm liên tục, không đưa về 0 sau mỗi bước; đưa về 0 là 戻し法.","ウ":"Sai vì công việc nhanh hơn chuẩn thì hệ số đánh giá lớn hơn 100.","エ":"Đây là đáp án đúng."}},"key_knowledge":["Nghiên cứu thời gian (時間研究) và phân tích động tác (動作分析) là hai công cụ cốt lõi của IE; phân tích động tác tìm ra cách làm tối ưu, còn nghiên cứu thời gian đo lường và định lượng thời gian chuẩn cho cách làm đó.","Đơn vị DM (Decimal Minute) quy định 1 phút = 100 DM (1 DM = 0,01 phút = 0,6 giây); do sử dụng hệ thập phân nên việc tính toán cộng trừ và tính bình quân trên máy tính thuận tiện hơn rất nhiều so với hệ 60 giây.","Phương pháp đo liên tục (継続法): Đồng hồ bấm giây chạy liên tục không dừng trong suốt chu kỳ làm việc, người bấm giờ ghi lại mốc thời gian tại điểm kết thúc mỗi nguyên công rồi trừ dần để ra thời gian từng bước.","Phương pháp trả về 0 (戻し法 / フライバック法): Sau mỗi nguyên công, người đo bấm nút đưa kim đồng hồ về vị trí 0 để đọc trực tiếp thời gian của bước tiếp theo, tuy nhiên dễ sinh sai số thao tác tay nếu bước công việc quá ngắn.","Hệ số đánh giá tốc độ (レイティング係数): Dùng để hiệu chỉnh tốc độ của người thao tác về tốc độ chuẩn (100); nếu thao tác nhanh hơn chuẩn thì hệ số > 100 (ví dụ 110), nếu thao tác chậm hơn chuẩn thì hệ số < 100 (ví dụ 90).","Công thức tính thời gian thực (正味時間): Thời gian thực = Thời gian quan sát thực tế × (Hệ số Rating / 100).","Xử lý độ biến thiên thời gian (バラツキ): Khi thời gian của một nguyên công (要素作業) chênh lệch quá nhiều giữa các lần đo, nguyên nhân gốc rễ thường nằm ở động tác chưa đồng nhất, tư thế lấy chi tiết bị đổi hoặc gặp sự cố bất thường.","Giải pháp cải tiến: Khi phát hiện nguyên công có độ biến thiên cao, cần áp dụng phân tích động tác (動作分析) để loại bỏ động tác thừa (ムダ), cố định vị trí đặt chi tiết và chuẩn hóa quy trình thao tác nhằm kéo thời gian về mức ổn định."],"exam_traps":["Đảo ngược 継続法 và 戻し法.","Đảo chiều hệ số đánh giá.","Nói DM phức tạp hơn giây trong khi DM thuận tiện hơn cho tính toán."],"vocabulary":[{"word":"時間研究","reading":"じかんけんきゅう","meaning":"nghiên cứu thời gian"},{"word":"測定単位","reading":"そくていたんい","meaning":"đơn vị đo"},{"word":"集計","reading":"しゅうけい","meaning":"tổng hợp, tính tổng"},{"word":"継続法","reading":"けいぞくほう","meaning":"phương pháp liên tục"},{"word":"戻し法","reading":"もどしほう","meaning":"phương pháp đưa về 0 sau mỗi bước"},{"word":"作業ペース","reading":"さぎょうペース","meaning":"tốc độ công việc"},{"word":"レイティング係数","reading":"レイティングけいすう","meaning":"hệ số đánh giá tốc độ"},{"word":"バラツキ","reading":"ばらつき","meaning":"độ biến thiên"},{"word":"要素作業","reading":"ようそさぎょう","meaning":"nguyên công thành phần"},{"word":"動作分析","reading":"どうさぶんせき","meaning":"phân tích động tác"},{"word":"ストップウォッチ法","reading":"ストップウォッチほう","meaning":"phương pháp đồng hồ bấm giây"},{"word":"DM単位","reading":"ディーエムたんい","meaning":"đơn vị DM (phút thập phân)"},{"word":"秒単位","reading":"びょうたんい","meaning":"đơn vị giây"},{"word":"ステップ","reading":"ステップ","meaning":"bước"},{"word":"観測","reading":"かんそく","meaning":"quan sát, đo"},{"word":"標準的","reading":"ひょうじゅんてき","meaning":"mang tính chuẩn"},{"word":"速い","reading":"はやい","meaning":"nhanh"},{"word":"遅い","reading":"おそい","meaning":"chậm"},{"word":"複雑","reading":"ふくざつ","meaning":"phức tạp"},{"word":"直接","reading":"ちょくせつ","meaning":"trực tiếp"},{"word":"求める","reading":"もとめる","meaning":"tìm ra, yêu cầu"},{"word":"検討","reading":"けんとう","meaning":"xem xét, nghiên cứu"},{"word":"標準作業","reading":"ひょうじゅんさぎょう","meaning":"công việc chuẩn"},{"word":"有効","reading":"ゆうこう","meaning":"hữu hiệu"}]},{"id":"05","chapter":"6.作業管理","question":{"japanese":"作業改善の進め方に関する記述として最も適切なものは、次のうちどれか。","vietnamese":"Trong các mô tả về cách tiến hành cải tiến công việc, mô tả nào phù hợp nhất?","furigana":"作業[さぎょう]改善[かいぜん]の進め方[すすめかた]に関する[かんする]記述[きじゅつ]として最も[もっとも]適切[てきせつ]なものは、次[つぎ]のうちどれか。"},"options":[{"key":"ア","japanese":"合理化の原則は、標準化、単純化、専門化の総称であり、企業活動を効率的に行うための考え方を意味している。","vietnamese":"Nguyên tắc hợp lý hóa là tên gọi chung của tiêu chuẩn hóa, đơn giản hóa và chuyên môn hóa, chỉ cách suy nghĩ để thực hiện hoạt động doanh nghiệp hiệu quả.","furigana":"合理化[ごうりか]の原則[げんそく]は、標準化[ひょうじゅんか]、単純化[たんじゅんか]、専門化[せんもんか]の総称[そうしょう]であり、企業[きぎょう]活動[かつどう]を効率的[こうりつてき]に行う[おこなう]ための考え方[かんがえかた]を意味[いみ]している。"},{"key":"イ","japanese":"動作経済の原則は、必要な動作に関する原則、不必要な動作に関する原則、必要性が不明な動作に関する原則の3つに分類整理されている。","vietnamese":"Nguyên tắc kinh tế động tác được phân thành 3 nhóm: động tác cần thiết, động tác không cần thiết và động tác chưa rõ tính cần thiết.","furigana":"動作[どうさ]経済[けいざい]の原則[げんそく]は、必要[ひつよう]な動作[どうさ]に関する[かんする]原則[げんそく]、不必要[ふひつよう]な動作[どうさ]に関する[かんする]原則[げんそく]、必要性[ひつようせい]が不明[ふめい]な動作[どうさ]に関する[かんする]原則[げんそく]の3つに分類[ぶんるい]整理[せいり]されている。"},{"key":"ウ","japanese":"作業の改善では、作業順序を入れ替えてしまうような方策は好ましくない。","vietnamese":"Trong cải tiến công việc, biện pháp làm thay đổi thứ tự công việc là không được ưa chuộng.","furigana":"作業[さぎょう]の改善[かいぜん]では、作業[さぎょう]順序[じゅんじょ]を入れ替え[いれかえ]てしまうような方策[ほうさく]は好ましく[このましく]ない。"},{"key":"エ","japanese":"5W1HにおけるHは、改善方策の水平展開、horizontal expansionのHである。","vietnamese":"H trong 5W1H là H của horizontal expansion, tức triển khai ngang các biện pháp cải tiến.","furigana":"5W1HにおけるHは、改善[かいぜん]方策[ほうさく]の水平[すいへい]展開[てんかい]、horizontal expansionのHである。"}],"correct_answer":"ア","explanation":{"correct_reason":"合理化の原則 thường được hiểu là tổng hợp của 標準化 (tiêu chuẩn hóa), 単純化 (đơn giản hóa) và 専門化 (chuyên môn hóa), nhằm nâng cao hiệu quả hoạt động doanh nghiệp.","incorrect_reasons":{"ア":"Đây là đáp án đúng.","イ":"Sai vì 動作経済の原則 được phân theo nhóm liên quan đến thân thể, bố trí nơi làm việc, dụng cụ/thiết bị, không phải 3 nhóm theo mức độ cần thiết.","ウ":"Sai vì thay đổi thứ tự công việc là biện pháp cải tiến hợp lệ để giảm di chuyển và chờ đợi.","エ":"Sai vì H trong 5W1H là How (làm thế nào), không phải horizontal expansion."}},"key_knowledge":["Nguyên tắc hợp lý hóa (合理化の原則 - còn gọi là nguyên tắc 3S): Bao gồm Tiêu chuẩn hóa (標準化 - Standardization), Đơn giản hóa (単純化 - Simplification), và Chuyên môn hóa (専門化 - Specialization) để nâng cao hiệu quả sản xuất.","Bản chất của 3S trong nhà máy: Đơn giản hóa (単純化) nhằm giảm chủng loại sản phẩm và chi tiết; Tiêu chuẩn hóa (標準化) nhằm thống nhất quy trình và kích thước; Chuyên môn hóa (専門化) nhằm tập trung thiết bị và nhân lực vào công đoạn chuyên biệt.","Nguyên tắc kinh tế động tác (動作経済の原則): Được Gilbreth hệ thống hóa và phân loại thành 3 nhóm cơ bản: (1) Sử dụng cơ thể con người (身体の使用), (2) Bố trí nơi làm việc (作業場の配置), và (3) Thiết kế dụng cụ và máy móc (工具・機械の設計).","Ứng dụng kinh tế động tác (動作経済): Hướng đến mục tiêu giảm mệt mỏi và tăng tốc độ thao tác, ví dụ: chuyển động đối xứng hai tay cùng lúc, để dụng cụ trong tầm với tự nhiên thay vì phải với cao hoặc cúi người.","Nguyên tắc ECRS (ECRSの原則): Khung tư duy cải tiến thao tác theo thứ tự ưu tiên gồm Loại bỏ (Eliminate - 排除), Kết hợp (Combine - 結合), Thay đổi thứ tự (Rearrange - 順序の変更), và Đơn giản hóa (Simplify - 簡素化).","Hoán đổi thứ tự công việc (順序の変更 - Rearrange): Là biện pháp cải tiến quan trọng và phổ biến trong ECRS, giúp triệt tiêu quãng đường di chuyển và thời gian chờ đợi lãng phí (手待ち).","Phương pháp 5W1H trong phân tích thao tác: Bao gồm What (Làm gì), Why (Tại sao làm), Where (Làm ở đâu), When (Làm khi nào), Who (Ai làm), và How (Làm bằng phương pháp nào); chữ H hoàn toàn không phải là Horizontal.","Phân biệt 5W1H và Triển khai ngang (水平展開): 5W1H là công cụ đặt câu hỏi để tìm nguyên nhân và cách làm; trong khi Triển khai ngang (水平展開 - Yokoten) là việc nhân rộng biện pháp cải tiến đã thành công từ một dây chuyền sang các dây chuyền khác."],"exam_traps":["Đánh tráo H của 5W1H thành horizontal expansion.","Nói thay đổi thứ tự công việc là không tốt.","Phân loại sai 動作経済の原則 thành 3 nhóm theo mức độ cần thiết."],"vocabulary":[{"word":"作業改善","reading":"さぎょうかいぜん","meaning":"cải tiến công việc"},{"word":"合理化","reading":"ごうりか","meaning":"hợp lý hóa"},{"word":"標準化","reading":"ひょうじゅんか","meaning":"tiêu chuẩn hóa"},{"word":"単純化","reading":"たんじゅんか","meaning":"đơn giản hóa"},{"word":"専門化","reading":"せんもんか","meaning":"chuyên môn hóa"},{"word":"動作経済の原則","reading":"どうさけいざいのげんそく","meaning":"nguyên tắc kinh tế động tác"},{"word":"作業順序","reading":"さぎょうじゅんじょ","meaning":"thứ tự công việc"},{"word":"方策","reading":"ほうさく","meaning":"biện pháp"},{"word":"水平展開","reading":"すいへいてんかい","meaning":"triển khai ngang"},{"word":"合理化の原則","reading":"ごうりかのげんそく","meaning":"nguyên tắc hợp lý hóa"},{"word":"総称","reading":"そうしょう","meaning":"tên gọi chung"},{"word":"企業活動","reading":"きぎょうかつどう","meaning":"hoạt động doanh nghiệp"},{"word":"効率的","reading":"こうりつてき","meaning":"mang tính hiệu quả"},{"word":"動作経済","reading":"どうさけいざい","meaning":"kinh tế động tác"},{"word":"入れ替える","reading":"いれかえる","meaning":"đổi chỗ, thay đổi thứ tự"},{"word":"好ましくない","reading":"このましくない","meaning":"không được ưa chuộng"},{"word":"必要","reading":"ひつよう","meaning":"cần thiết"},{"word":"不明","reading":"ふめい","meaning":"không rõ"},{"word":"分類整理","reading":"ぶんるいせいり","meaning":"phân loại, sắp xếp"},{"word":"5W1H","reading":"ごダブリューいちエイチ","meaning":"5W1H (câu hỏi cải tiến)"}]},{"id":"06","chapter":"6.作業管理","question":{"japanese":"作業改善の対象となるミスに関する記述として最も不適切なものは、次のうちどれか。","vietnamese":"Trong các mô tả về sai sót thuộc đối tượng cải tiến công việc, mô tả nào KHÔNG phù hợp nhất?","furigana":"作業[さぎょう]改善[かいぜん]の対象[たいしょう]となるミスに関する[かんする]記述[きじゅつ]として最も[もっとも]不適切[ふてきせつ]なものは、次[つぎ]のうちどれか。"},"options":[{"key":"ア","japanese":"加工作業中のミスを防ぐ1つの方法には、フールプルーフと呼ばれるポカよけの方法がある。","vietnamese":"Một cách phòng ngừa sai sót trong gia công là phương pháp chống nhầm lẫn gọi là foolproof.","furigana":"加工[かこう]作業中[さぎょうちゅう]のミスを防ぐ[ふせぐ]1つの方法[ほうほう]には、フールプルーフと呼ば[よば]れるポカよけの方法[ほうほう]がある。"},{"key":"イ","japanese":"検査作業における第二種の誤りとは、適合品であるにも関わらず不適合品としてしまう誤りである。","vietnamese":"Lỗi loại 2 trong kiểm tra là lỗi coi sản phẩm phù hợp là sản phẩm không phù hợp.","furigana":"検査[けんさ]作業[さぎょう]における第二種[だいにしゅ]の誤り[あやまり]とは、適合品[てきごうひん]であるにも関わら[かかわら]ず不適合品[ふてきごうひん]としてしまう誤り[あやまり]である。"},{"key":"ウ","japanese":"運搬作業における取る作業でのミスには、取る対象物の間違え、取る個数の間違え、取るときの落下などが考えられる。","vietnamese":"Sai sót khi lấy hàng trong vận chuyển gồm lấy nhầm đối tượng, lấy nhầm số lượng, làm rơi khi lấy.","furigana":"運搬[うんぱん]作業[さぎょう]における取る[とる]作業[さぎょう]でのミスには、取る[とる]対象物[たいしょうぶつ]の間違え[まちがえ]、取る[とる]個数[こすう]の間違え[まちがえ]、取る[とる]ときの落下[らっか]などが考え[かんがえ]られる。"},{"key":"エ","japanese":"運搬作業における運ぶ作業でのミスには、対象物への振動や落下による破損、他との接触による汚れの付着、振動などによる搬送容器での定位置からのずれなどがある。","vietnamese":"Sai sót khi mang hàng gồm hư hỏng do rung động/rơi, bám bẩn do tiếp xúc, lệch khỏi vị trí cố định trong thùng do rung động.","furigana":"運搬[うんぱん]作業[さぎょう]における運ぶ[はこぶ]作業[さぎょう]でのミスには、対象物[たいしょうぶつ]への振動[しんどう]や落下[らっか]による破損[はそん]、他[た]との接触[せっしょく]による汚れ[よごれ]の付着[ふちゃく]、振動[しんどう]などによる搬送[はんそう]容器[ようき]での定[てい]位置[いち]からのずれなどがある。"}],"correct_answer":"イ","explanation":{"correct_reason":"Đề hỏi mô tả KHÔNG phù hợp. Lỗi loại 2 (第二種の誤り) là bỏ sót, tức coi sản phẩm KHÔNG phù hợp là phù hợp (consumer risk). Phương án イ lại mô tả việc coi sản phẩm phù hợp là không phù hợp, đó là lỗi loại 1 (producer risk). Vì vậy イ đã đảo loại lỗi.","incorrect_reasons":{"ア":"Sai vì foolproof là biện pháp hợp lệ để ngăn sai sót trong gia công.","イ":"Đây là đáp án đúng vì mô tả lỗi loại 1 nhưng gọi là lỗi loại 2.","ウ":"Sai vì các sai sót nêu ra đều là ví dụ hợp lệ trong thao tác lấy hàng.","エ":"Sai vì các sai sót nêu ra đều là ví dụ hợp lệ trong thao tác mang hàng."}},"key_knowledge":["Khái niệm cải tiến thao tác (作業改善): Nhằm phát hiện và triệt tiêu các sai sót phát sinh từ con người (ヒューマンエラー - human error) trong suốt các khâu gia công, vận chuyển và kiểm tra.","Cơ chế Foolproof (フールプルーフ / ポカよけ): Là thiết kế máy móc, đồ gá (治具) hoặc hệ thống cảm biến sao cho người thao tác dù có sơ suất, bất cẩn cũng không thể thao tác sai hoặc máy sẽ tự dừng ngay khi có lỗi (ví dụ chi tiết chỉ lắp vừa theo một chiều duy nhất).","Lỗi loại 1 trong kiểm tra (第一種の誤り - Type I error): Là lỗi phán đoán sản phẩm phù hợp tiêu chuẩn (適合品/良品) thành sản phẩm không phù hợp (不適合品/不良品), gây lãng phí chi phí do loại bỏ nhầm nên gọi là rủi ro của nhà sản xuất (生産者危険 - Producer's Risk, ký hiệu α).","Lỗi loại 2 trong kiểm tra (第二種の誤り - Type II error): Là lỗi bỏ sót phán đoán sản phẩm không phù hợp (不適合品/不良品) thành sản phẩm phù hợp (適合品/良品) rồi xuất xưởng, gây nguy cơ mất uy tín và phát sinh khiếu nại nên gọi là rủi ro của người tiêu dùng (消費者危険 - Consumer's Risk, ký hiệu β).","So sánh mức độ rủi ro giữa hai loại lỗi: Trong quản trị chất lượng, lỗi loại 2 (lọt hàng lỗi đến tay khách) được coi là nghiêm trọng hơn rất nhiều so với lỗi loại 1 (vứt nhầm hàng đạt chuẩn).","Phân loại sai sót khi bốc dỡ/lấy hàng (取る作業でのミス): Công đoạn này thường phát sinh các lỗi thao tác như lấy sai mã linh kiện (対象物の間違え), đếm sai số lượng (個数の間違え), hoặc trượt tay làm rơi khi nhấc hàng (取るときの落下).","Phân loại sai sót khi di chuyển/chở hàng (運ぶ作業でのミス): Quá trình vận chuyển trên xe đẩy hay băng chuyền dễ gặp sự cố va chạm gây bẩn (汚れの付着), rung lắc làm xô lệch khỏi vị trí quy định trong thùng chứa (定位置からのずれ), hoặc chấn động dẫn đến nứt vỡ, rơi hỏng (振動や落下による破損).","Biện pháp chuẩn hóa công việc (作業標準化): Để hạn chế sai sót trong vận chuyển và gia công, doanh nghiệp cần thiết lập bảng chỉ dẫn thao tác chuẩn (作業手順書) kết hợp quy định 5S định vị, định lượng rõ ràng."],"exam_traps":["Đảo định nghĩa lỗi loại 1 và loại 2.","Câu hỏi 最も不適切 dễ bị chọn nhầm phương án mô tả đúng.","Các sai sót vận chuyển được liệt kê đúng nhưng bị gán sai thao tác."],"vocabulary":[{"word":"ミス","reading":"ミス","meaning":"sai sót"},{"word":"加工作業","reading":"かこうさぎょう","meaning":"công việc gia công"},{"word":"フールプルーフ","reading":"フールプルーフ","meaning":"chống nhầm lẫn, foolproof"},{"word":"ポカよけ","reading":"ポカよけ","meaning":"chống sai sót"},{"word":"第二種の誤り","reading":"だいにしゅのあやまり","meaning":"lỗi loại 2"},{"word":"適合品","reading":"てきごうひん","meaning":"sản phẩm phù hợp"},{"word":"不適合品","reading":"ふてきごうひん","meaning":"sản phẩm không phù hợp"},{"word":"運搬作業","reading":"うんぱんさぎょう","meaning":"công việc vận chuyển"},{"word":"振動","reading":"しんどう","meaning":"rung động"},{"word":"破損","reading":"はそん","meaning":"hư hỏng"},{"word":"汚れの付着","reading":"よごれのふちゃく","meaning":"bám bẩn"},{"word":"定位置","reading":"ていいち","meaning":"vị trí cố định"},{"word":"第一種の誤り","reading":"だいいちしゅのあやまり","meaning":"lỗi loại 1"},{"word":"検査作業","reading":"けんささぎょう","meaning":"công việc kiểm tra"},{"word":"取る作業","reading":"とるさぎょう","meaning":"thao tác lấy hàng"},{"word":"運ぶ作業","reading":"はこぶさぎょう","meaning":"thao tác mang hàng"},{"word":"対象物","reading":"たいしょうぶつ","meaning":"đối tượng, vật thể"},{"word":"個数","reading":"こすう","meaning":"số lượng cái"},{"word":"間違え","reading":"まちがえ","meaning":"sự nhầm lẫn"},{"word":"落下","reading":"らっか","meaning":"rơi xuống"},{"word":"接触","reading":"せっしょく","meaning":"tiếp xúc"},{"word":"搬送容器","reading":"はんそうようき","meaning":"thùng vận chuyển"},{"word":"ずれ","reading":"ずれ","meaning":"sự lệch"},{"word":"防ぐ","reading":"ふせぐ","meaning":"ngăn chặn"}]},{"id":"07","chapter":"6.作業管理","question":{"japanese":"5S活動に関する記述として最も不適切なものは、次のうちどれか。","vietnamese":"Trong các mô tả về hoạt động 5S, mô tả nào KHÔNG phù hợp nhất?","furigana":"5S活動[かつどう]に関する[かんする]記述[きじゅつ]として最も[もっとも]不適切[ふてきせつ]なものは、次[つぎ]のうちどれか。"},"options":[{"key":"ア","japanese":"不要品は、ルールを定めて廃棄する。","vietnamese":"Đồ không cần thiết phải được quy định quy tắc và loại bỏ.","furigana":"不要品[ふようひん]は、ルールを定め[さだめ]て廃棄[はいき]する。"},{"key":"イ","japanese":"守るべきルールは、見える化して、その内容を周知する。","vietnamese":"Các quy tắc cần tuân thủ phải được trực quan hóa và phổ biến nội dung.","furigana":"守る[まもる]べきルールは、見える[みえる]化[か]して、その内容[ないよう]を周知[しゅうち]する。"},{"key":"ウ","japanese":"整理・整頓・躾を行うことで結果として清潔な職場が実現できる。","vietnamese":"Thực hiện sàng lọc, sắp xếp và kỷ luật sẽ mang lại kết quả là nơi làm việc sạch sẽ.","furigana":"整理[せいり]・整頓[せいとん]・躾[しつけ]を行う[おこなう]ことで結果[けっか]として清潔[せいけつ]な職場[しょくば]が実現[じつげん]できる。"},{"key":"エ","japanese":"部品棚での保管は、置きやすく、取りやすくしておく。","vietnamese":"Bảo quản trên giá linh kiện phải bố trí sao cho dễ đặt và dễ lấy.","furigana":"部品[ぶひん]棚[たな]での保管[ほかん]は、置き[おき]やすく、取り[とり]やすくしておく。"}],"correct_answer":"ウ","explanation":{"correct_reason":"5S gồm 整理, 整頓, 清掃, 清潔, 躾. Phương án ウ bỏ sót 清掃 và nói chỉ cần 整理・整頓・躾 là tự nhiên có nơi làm việc sạch sẽ. Thực tế phải thực hiện đủ 5S, đặc biệt 清掃 và duy trì 清潔.","incorrect_reasons":{"ア":"Sai vì loại bỏ đồ không cần thiết theo quy tắc là nội dung đúng của 整理.","イ":"Sai vì trực quan hóa và phổ biến quy tắc là cách duy trì 5S hiệu quả.","ウ":"Đây là đáp án đúng vì thiếu 清掃 và giải thích sai mối quan hệ giữa các yếu tố 5S.","エ":"Sai vì bố trí giá dễ đặt, dễ lấy là ví dụ đúng của 整頓."}},"key_knowledge":["Khái niệm 5S: Là hoạt động cải tiến hiện trường cơ bản nhất gồm 5 yếu tố bắt đầu bằng chữ S: Sàng lọc (整理 - Seiri), Sắp xếp (整頓 - Seiton), Sạch sẽ (清掃 - Seisou), Săn sóc (清潔 - Seiketsu), và Kỷ luật (躾 - Shitsuke).","Sàng lọc (整理 - Seiri): Xác định rõ tiêu chuẩn phân chia vật phẩm thành 'cần thiết' (要) và 'không cần thiết' (不要), sau đó kiên quyết xử lý hoặc vứt bỏ đồ không cần thiết (thường sử dụng thẻ đỏ - 赤札作戦).","Sắp xếp (整頓 - Seiton): Bố trí các vật phẩm cần thiết ở vị trí cố định sao cho dễ tìm, dễ lấy, dễ trả về (置きやすく、取りやすく、戻しやすい), áp dụng quy tắc 3 Định (三定: 定位置 - vị trí cố định, 定品 - đúng đồ, 定量 - đúng số lượng).","Sạch sẽ (清掃 - Seisou): Không chỉ đơn thuần là quét dọn bụi bẩn, rác thải mà bản chất là 'vừa dọn vừa kiểm tra' (清掃点検) để sớm phát hiện các bất thường, rò rỉ dầu mỡ hay lỏng ốc bu lông của máy móc.","Săn sóc (清潔 - Seiketsu): Là trạng thái tiêu chuẩn hóa và duy trì liên tục, triệt để kết quả của 3S đầu tiên (整理・整頓・清掃の維持), chứ không phải chỉ là kết hợp giữa sàng lọc, sắp xếp với kỷ luật.","Kỷ luật (躾 - Shitsuke): Đào tạo, huấn luyện và tạo môi trường để công nhân viên tự giác hình thành thói quen tuân thủ đúng các quy tắc, quy chuẩn đã đề ra tại nơi làm việc.","Trực quan hóa (見える化) trong 5S: Mọi quy tắc và vị trí lưu trữ cần được thể hiện bằng biển tên, vạch sơn phân định khu vực (区画線) giúp mọi người dễ nhận biết sai lệch ngay khi nhìn vào.","Trật tự logic của 5S: 3 bước đầu (整理・整頓・清掃) là các hành động thể chất trực tiếp; 清潔 là việc duy trì và chuẩn hóa 3 bước đó; 躾 là yếu tố con người giúp cả hệ thống vận hành bền vững."],"exam_traps":["Bỏ sót một trong 5S, thường là 清掃.","Nói kết quả tự nhiên có được chỉ từ 3 yếu tố.","Đánh tráo 整理 và 整頓."],"vocabulary":[{"word":"5S活動","reading":"ごエスかつどう","meaning":"hoạt động 5S"},{"word":"整理","reading":"せいり","meaning":"sàng lọc, loại bỏ đồ không cần"},{"word":"整頓","reading":"せいとん","meaning":"sắp xếp"},{"word":"清掃","reading":"せいそう","meaning":"quét dọn"},{"word":"清潔","reading":"せいけつ","meaning":"sạch sẽ"},{"word":"躾","reading":"しつけ","meaning":"kỷ luật, rèn nếp"},{"word":"不要品","reading":"ふようひん","meaning":"đồ không cần thiết"},{"word":"廃棄","reading":"はいき","meaning":"loại bỏ, vứt bỏ"},{"word":"見える化","reading":"みえるか","meaning":"trực quan hóa"},{"word":"周知","reading":"しゅうち","meaning":"phổ biến rộng rãi"},{"word":"部品棚","reading":"ぶひんだな","meaning":"giá linh kiện"},{"word":"保管","reading":"ほかん","meaning":"bảo quản"},{"word":"5S","reading":"ごエス","meaning":"5S"},{"word":"職場","reading":"しょくば","meaning":"nơi làm việc"},{"word":"ルール","reading":"ルール","meaning":"quy tắc"},{"word":"守る","reading":"まもる","meaning":"tuân thủ, giữ"},{"word":"実現","reading":"じつげん","meaning":"thực hiện được"},{"word":"置きやすい","reading":"おきやすい","meaning":"dễ đặt"},{"word":"取りやすい","reading":"とりやすい","meaning":"dễ lấy"},{"word":"定める","reading":"さだめる","meaning":"quy định"}]},{"id":"08","chapter":"7.工程管理","question":{"japanese":"モノによる緩衝（バッファ）の役割に関する記述として最も不適切なものは、次のうちどれか。","vietnamese":"Trong các mô tả về vai trò của bộ đệm bằng hàng hóa (buffer), mô tả nào KHÔNG phù hợp nhất?","furigana":"モノによる緩衝[かんしょう]（バッファ）の役割[やくわり]に関する[かんする]記述[きじゅつ]として最も[もっとも]不適切[ふてきせつ]なものは、次[つぎ]のうちどれか。"},"options":[{"key":"ア","japanese":"製品在庫には、販売における需要の変動の影響を、生産計画や生産工程に直接受けることを避ける役割がある。","vietnamese":"Tồn kho thành phẩm có vai trò tránh để ảnh hưởng biến động nhu cầu bán hàng tác động trực tiếp đến kế hoạch và quy trình sản xuất.","furigana":"製品[せいひん]在庫[ざいこ]には、販売[はんばい]における需要[じゅよう]の変動[へんどう]の影響[えいきょう]を、生産[せいさん]計画[けいかく]や生産[せいさん]工程[こうてい]に直接[ちょくせつ]受ける[うける]ことを避ける[さける]役割[やくわり]がある。"},{"key":"イ","japanese":"全工程の適合品率向上を図るためには、ボトルネック工程の前にバッファを置くことが有効である。","vietnamese":"Để nâng cao tỷ lệ sản phẩm phù hợp của toàn bộ quy trình, đặt buffer trước công đoạn nút cổ chai là hữu hiệu.","furigana":"全工程[ぜんこうてい]の適合品率[てきごうひんりつ]向上[こうじょう]を図る[はかる]ためには、ボトルネック工程[こうてい]の前[まえ]にバッファを置く[おく]ことが有効[ゆうこう]である。"},{"key":"ウ","japanese":"部品の安全在庫としての役割には、生産計画どおりに部品が納入されない場合に、品切れの防止がある。","vietnamese":"Vai trò tồn kho an toàn linh kiện là phòng ngừa thiếu hàng khi linh kiện không được giao đúng kế hoạch.","furigana":"部品[ぶひん]の安全[あんぜん]在庫[ざいこ]としての役割[やくわり]には、生産[せいさん]計画[けいかく]どおりに部品[ぶひん]が納入[のうにゅう]されない場合[ばあい]に、品切れ[しなぎれ]の防止[ぼうし]がある。"},{"key":"エ","japanese":"仕掛品在庫の役割には、生産設備が故障した場合に、工程内で発生する生産時間ロスの防止がある。","vietnamese":"Vai trò tồn kho bán thành phẩm là phòng ngừa tổn thất thời gian sản xuất khi thiết bị bị hỏng.","furigana":"仕掛品[しかかりひん]在庫[ざいこ]の役割[やくわり]には、生産[せいさん]設備[せつび]が故障[こしょう]した場合[ばあい]に、工程内[こうていない]で発生[はっせい]する生産[せいさん]時間[じかん]ロスの防止[ぼうし]がある。"}],"correct_answer":"イ","explanation":{"correct_reason":"Buffer trước công đoạn nút cổ chai giúp công đoạn sau không bị dừng khi công đoạn trước gặp sự cố, nhưng không trực tiếp nâng cao tỷ lệ sản phẩm phù hợp (適合品率). 適合品率 được cải thiện bằng kiểm soát chất lượng, giảm lỗi, cải tiến công đoạn.","incorrect_reasons":{"ア":"Sai vì tồn kho thành phẩm đúng là tấm đệm giữa biến động nhu cầu và kế hoạch sản xuất.","イ":"Đây là đáp án đúng vì buffer trước bottleneck giúp giảm chờ đợi, không phải công cụ nâng cao trực tiếp 適合品率.","ウ":"Sai vì tồn kho an toàn linh kiện đúng là để tránh thiếu hàng khi giao chậm.","エ":"Sai vì tồn kho bán thành phẩm giúp giảm gián đoạn khi thiết bị hỏng."}},"key_knowledge":["Bộ đệm bằng hàng hóa (モノによる緩衝 / バッファ) là lượng tồn kho được cố tình duy trì để hấp thu sự chênh lệch nhịp độ hoặc biến động bất ngờ giữa các công đoạn, hay giữa nhà máy và thị trường bên ngoài.","Tồn kho thành phẩm (製品在庫) có vai trò hấp thu biến động nhu cầu thị trường (需要の変動), giúp kế hoạch sản xuất nội bộ được duy trì ổn định mà không phải liên tục thay đổi đột ngột.","Tồn kho bán thành phẩm (仕掛品在庫) đặt giữa các công đoạn nhằm ngăn ngừa tổn thất thời gian chờ đợi (手待ちの防止) khi công đoạn trước xảy ra sự cố hỏng hóc thiết bị (設備故障) hoặc chuyển đổi mẫu mã.","Tồn kho an toàn linh kiện (部品の安全在庫) có chức năng phòng ngừa rủi ro đứt gãy sản xuất do nhà cung cấp chậm giao hàng hoặc phát sinh lỗi linh kiện nhập về đột biến.","Buffer trước công đoạn nút thắt (ボトルネック工程前のバッファ) có mục tiêu duy trì dòng việc liên tục cho bottleneck, ngăn việc nút thắt bị thiếu hàng để tối đa hóa sản lượng của toàn bộ dây chuyền.","Buffer chỉ điều tiết về số lượng và thời gian, hoàn toàn không có khả năng trực tiếp làm tăng tỷ lệ thành phẩm đạt chuẩn (適合品率); để nâng cao tỷ lệ này phải dùng các biện pháp quản lý chất lượng (品質管理) và nâng cao năng lực công đoạn (工程能力).","Phân loại 3 dạng buffer trong sản xuất bao gồm: Buffer hàng hóa (モノのバッファ - tồn kho), Buffer thời gian (時間のバッファ - dự phòng thời hạn giao hàng) và Buffer năng lực (能力のバッファ - dự phòng công suất máy hoặc nhân lực tăng ca)."],"exam_traps":["Gán vai trò cải thiện chất lượng cho buffer, trong khi buffer chủ yếu giảm gián đoạn thời gian.","Nhầm 適合品率 với 稼働率.","Đánh tráo vị trí đặt buffer trước/sau bottleneck."],"vocabulary":[{"word":"緩衝","reading":"かんしょう","meaning":"đệm, giảm xóc"},{"word":"バッファ","reading":"バッファ","meaning":"bộ đệm"},{"word":"製品在庫","reading":"せいひんざいこ","meaning":"tồn kho thành phẩm"},{"word":"需要の変動","reading":"じゅようのへんどう","meaning":"biến động nhu cầu"},{"word":"適合品率","reading":"てきごうひんりつ","meaning":"tỷ lệ sản phẩm phù hợp"},{"word":"ボトルネック工程","reading":"ボトルネックこうてい","meaning":"công đoạn nút cổ chai"},{"word":"安全在庫","reading":"あんぜんざいこ","meaning":"tồn kho an toàn"},{"word":"納入","reading":"のうにゅう","meaning":"giao hàng, cung cấp"},{"word":"品切れ","reading":"しなぎれ","meaning":"hết hàng"},{"word":"仕掛品在庫","reading":"しかかりひんざいこ","meaning":"tồn kho bán thành phẩm"},{"word":"故障","reading":"こしょう","meaning":"hỏng hóc"},{"word":"ロス","reading":"ロス","meaning":"tổn thất"},{"word":"ボトルネック","reading":"ボトルネック","meaning":"nút cổ chai"},{"word":"仕掛品","reading":"しかかりひん","meaning":"bán thành phẩm"},{"word":"需要","reading":"じゅよう","meaning":"nhu cầu"},{"word":"変動","reading":"へんどう","meaning":"biến động"},{"word":"影響","reading":"えいきょう","meaning":"ảnh hưởng"},{"word":"避ける","reading":"さける","meaning":"tránh"},{"word":"全工程","reading":"ぜんこうてい","meaning":"toàn bộ công đoạn"},{"word":"向上","reading":"こうじょう","meaning":"nâng cao"},{"word":"防止","reading":"ぼうし","meaning":"phòng ngừa"},{"word":"生産設備","reading":"せいさんせつび","meaning":"thiết bị sản xuất"},{"word":"工程内","reading":"こうていない","meaning":"trong công đoạn"},{"word":"生産時間","reading":"せいさんじかん","meaning":"thời gian sản xuất"}]},{"id":"09","chapter":"7.工程管理","question":{"japanese":"製品の流し方による分類の記述として最も不適切なものは、次のうちどれか。","vietnamese":"Trong các mô tả về phân loại theo cách cho sản phẩm chảy qua quy trình, mô tả nào KHÔNG phù hợp nhất?","furigana":"製品[せいひん]の流し[ながし]方[かた]による分類[ぶんるい]の記述[きじゅつ]として最も[もっとも]不適切[ふてきせつ]なものは、次[つぎ]のうちどれか。"},"options":[{"key":"ア","japanese":"ロット生産において、ロットサイズが大きくなるにつれて、生産期間は短くなる傾向がある。","vietnamese":"Trong sản xuất theo lô, khi kích thước lô lớn hơn thì thời gian sản xuất có xu hướng ngắn lại.","furigana":"ロット生産[せいさん]において、ロットサイズが大きく[おおきく]なるにつれて、生産[せいさん]期間[きかん]は短く[みじかく]なる傾向[けいこう]がある。"},{"key":"イ","japanese":"ロット生産は、個別生産と連続生産の中間的な生産形態である。","vietnamese":"Sản xuất theo lô là hình thức trung gian giữa sản xuất đơn chiếc và sản xuất liên tục.","furigana":"ロット生産[せいさん]は、個別[こべつ]生産[せいさん]と連続[れんぞく]生産[せいさん]の中間的[ちゅうかんてき]な生産[せいさん]形態[けいたい]である。"},{"key":"ウ","japanese":"個別生産の生産工程に、専用設備ラインを組み入れることは、経済的ではない。","vietnamese":"Đưa dây chuyền thiết bị chuyên dụng vào quy trình sản xuất đơn chiếc là không kinh tế.","furigana":"個別[こべつ]生産[せいさん]の生産[せいさん]工程[こうてい]に、専用[せんよう]設備[せつび]ラインを組み入れる[くみいれる]ことは、経済的[けいざいてき]ではない。"},{"key":"エ","japanese":"連続生産は、製品別配置の観点からみると、一般にフローショップ型になる。","vietnamese":"Sản xuất liên tục, xét từ góc độ bố trí theo sản phẩm, thường có dạng flow shop.","furigana":"連続[れんぞく]生産[せいさん]は、製品別[せいひんべつ]配置[はいち]の観点[かんてん]からみると、一般[いっぱん]にフローショップ型[がた]になる。"}],"correct_answer":"ア","explanation":{"correct_reason":"Trong sản xuất theo lô, khi kích thước lô tăng thì thời gian sản xuất thường dài hơn do phải xử lý nhiều sản phẩm trong một lô. Vì vậy nói 'lô lớn hơn thì thời gian sản xuất ngắn lại' là không phù hợp.","incorrect_reasons":{"ア":"Đây là đáp án đúng vì quan hệ thực tế thường ngược lại: lô càng lớn, thời gian sản xuất càng dài.","イ":"Sai vì ロット生産 đúng là hình thức trung gian giữa 個別生産 và 連続生産.","ウ":"Sai vì sản xuất đơn chiếc khó dùng dây chuyền chuyên dụng do sản lượng thấp, nên không kinh tế.","エ":"Sai vì sản xuất liên tục thường bố trí theo sản phẩm và có dạng flow shop."}},"key_knowledge":["Phân loại theo cách thức luân chuyển dòng sản phẩm (製品の流し方による分類) gồm 3 hình thức cơ bản: Sản xuất đơn chiếc (個別生産 - Job shop), Sản xuất theo lô (ロット生産 - Batch production), và Sản xuất liên tục (連続生産 - Flow shop/Continuous production).","Sản xuất đơn chiếc (個別生産): Sản xuất từng sản phẩm riêng lẻ theo đơn đặt hàng đặc thù, thường sử dụng máy móc vạn năng (汎用設備) và bố trí mặt bằng theo công đoạn/chức năng (機能別配置/ジョブショップ型).","Sản xuất theo lô (ロット生産): Sản xuất hàng hóa theo từng cụm hoặc lô sản phẩm cùng loại, là hình thức trung gian kết hợp giữa tính linh hoạt của sản xuất đơn chiếc và tính hiệu quả của sản xuất liên tục.","Quan hệ giữa quy mô lô (ロットサイズ) và chu kỳ sản xuất (生産期間/リードタイム): Khi kích thước lô tăng lên, thời gian gia công toàn lô dài ra, thời gian chờ đợi (停滞時間) và lượng hàng dở dang (仕掛品 - WIP) đều tăng, dẫn đến tổng chu kỳ sản xuất kéo dài chứ không thể ngắn lại.","Kinh tế theo quy mô lô: Tăng lô sản xuất chỉ giúp giảm chi phí chuẩn bị sản xuất trên một đơn vị (1個当たりの段取り費用), nhưng lại làm tăng chi phí lưu kho (保管費用) và làm chậm tốc độ phản ứng với đơn hàng.","Sản xuất liên tục (連続生産): Sản xuất số lượng rất lớn một chủng loại sản phẩm cố định, máy móc chuyên dụng (専用設備) được sắp xếp tuần tự theo trình tự chế tạo sản phẩm tạo thành dạng dòng chảy (フローショップ型/製品別配置).","Tính kinh tế của thiết bị chuyên dụng (専用設備): Chỉ phát huy hiệu quả kinh tế khi quy mô sản lượng cực lớn (như trong 連続生産) để khấu hao chi phí đầu tư ban đầu; nếu áp dụng vào sản xuất đơn chiếc (個別生産) sẽ gây lãng phí nghiêm trọng do tần suất dùng thấp."],"exam_traps":["Đảo quan hệ giữa kích thước lô và thời gian sản xuất.","Nhầm 個別生産 với ロット生産 khi xét tính kinh tế của thiết bị chuyên dụng.","Nhầm bố trí theo sản phẩm với bố trí theo công đoạn."],"vocabulary":[{"word":"流し方","reading":"ながしかた","meaning":"cách cho sản phẩm chảy qua quy trình"},{"word":"ロット生産","reading":"ロットせいさん","meaning":"sản xuất theo lô"},{"word":"ロットサイズ","reading":"ロットサイズ","meaning":"kích thước lô"},{"word":"生産期間","reading":"せいさんきかん","meaning":"thời gian sản xuất"},{"word":"個別生産","reading":"こべつせいさん","meaning":"sản xuất đơn chiếc"},{"word":"連続生産","reading":"れんぞくせいさん","meaning":"sản xuất liên tục"},{"word":"中間的","reading":"ちゅうかんてき","meaning":"trung gian"},{"word":"専用設備ライン","reading":"せんようせつびライン","meaning":"dây chuyền thiết bị chuyên dụng"},{"word":"経済的","reading":"けいざいてき","meaning":"mang tính kinh tế"},{"word":"製品別配置","reading":"せいひんべつはいち","meaning":"bố trí theo sản phẩm"},{"word":"フローショップ型","reading":"フローショップがた","meaning":"kiểu flow shop"},{"word":"傾向","reading":"けいこう","meaning":"xu hướng"},{"word":"生産形態","reading":"せいさんけいたい","meaning":"hình thức sản xuất"},{"word":"専用設備","reading":"せんようせつび","meaning":"thiết bị chuyên dụng"},{"word":"組み入れる","reading":"くみいれる","meaning":"đưa vào, lắp vào"},{"word":"観点","reading":"かんてん","meaning":"góc độ, quan điểm"},{"word":"長くなる","reading":"ながくなる","meaning":"trở nên dài hơn"},{"word":"短くなる","reading":"みじかくなる","meaning":"trở nên ngắn hơn"},{"word":"中間","reading":"ちゅうかん","meaning":"trung gian"},{"word":"設備","reading":"せつび","meaning":"thiết bị"}]},{"id":"10","chapter":"7.工程管理","question":{"japanese":"＜工数と日程に関する記述＞と＜語句＞の組合せとして最も適切なものは、次のうちどれか。\n＜工数と日程に関する記述＞\nA. 生産統制の段階で、能力と負荷の調整を行う管理業務\nB. 納期を基準にしてスケジュールを作成する方法\nC. 作業ごとの負荷工数のリストに基づいて、ワークステーションの能力を考慮して割り振っていく方法\nD. ある作業ステーションで1つの作業が終わったときに、次にどの仕事を行うかを決める個別生産の日程計画の方法\n＜語句＞\n1.余力管理 2.工数計画 3.フォワード法 4.バックワード法 5.有限山積法 6.無限山積法 7.ディスパッチング法 8.順序づけ法","vietnamese":"Tổ hợp nào phù hợp nhất giữa <mô tả về công và lịch> và <thuật ngữ>?\nA. Nghiệp vụ điều chỉnh năng lực và phụ tải ở giai đoạn kiểm soát sản xuất\nB. Phương pháp lập lịch dựa trên ngày giao hàng\nC. Phương pháp phân bổ dựa trên danh sách công theo phụ tải từng công việc, có xét năng lực workstation\nD. Phương pháp lập lịch sản xuất đơn chiếc, quyết định công việc tiếp theo khi một công việc tại workstation kết thúc\n<Thuật ngữ>\n1. Quản lý năng lực dư 2. Kế hoạch công 3. Phương pháp forward 4. Phương pháp backward 5. Phương pháp xếp hữu hạn 6. Phương pháp xếp vô hạn 7. Phương pháp dispatch 8. Phương pháp sắp thứ tự","furigana":"＜工数[こうすう]と日程[にってい]に関する[かんする]記述[きじゅつ]＞と＜語句[ごく]＞の組合せ[くみあわせ]として最も[もっとも]適切[てきせつ]なものは、次[つぎ]のうちどれか。\n＜工数[こうすう]と日程[にってい]に関する[かんする]記述[きじゅつ]＞\nA. 生産[せいさん]統制[とうせい]の段階[だんかい]で、能力[のうりょく]と負荷[ふか]の調整[ちょうせい]を行う[おこなう]管理[かんり]業務[ぎょうむ]\nB. 納期[のうき]を基準[きじゅん]にしてスケジュールを作成[さくせい]する方法[ほうほう]\nC. 作業[さぎょう]ごとの負荷[ふか]工数[こうすう]のリストに基づい[もとづい]て、ワークステーションの能力[のうりょく]を考慮[こうりょ]して割り振っ[わりふっ]ていく方法[ほうほう]\nD. ある作業[さぎょう]ステーションで1つの作業[さぎょう]が終わっ[おわっ]たときに、次に[つぎに]どの仕事[しごと]を行う[おこなう]かを決める[きめる]個別[こべつ]生産[せいさん]の日程[にってい]計画[けいかく]の方法[ほうほう]\n＜語句[ごく]＞\n1.余力[よりょく]管理[かんり] 2.工数[こうすう]計画[けいかく] 3.フォワード法[ほう] 4.バックワード法[ほう] 5.有限[ゆうげん]山積法[さんせきほう] 6.無限[むげん]山積法[さんせきほう] 7.ディスパッチング法[ほう] 8.順序づけ[じゅんじょづけ]法[ほう]"},"options":[{"key":"ア","japanese":"A:2 B:3 C:5 D:8","vietnamese":"A:2 B:3 C:5 D:8","furigana":"A:2 B:3 C:5 D:8"},{"key":"イ","japanese":"A:2 B:3 C:6 D:7","vietnamese":"A:2 B:3 C:6 D:7","furigana":"A:2 B:3 C:6 D:7"},{"key":"ウ","japanese":"A:1 B:4 C:5 D:7","vietnamese":"A:1 B:4 C:5 D:7","furigana":"A:1 B:4 C:5 D:7"},{"key":"エ","japanese":"A:1 B:4 C:6 D:8","vietnamese":"A:1 B:4 C:6 D:8","furigana":"A:1 B:4 C:6 D:8"}],"correct_answer":"ウ","explanation":{"correct_reason":"A là 余力管理 (điều chỉnh năng lực và phụ tải). B là バックワード法 (lập lịch ngược từ ngày giao hàng). C là 有限山積法 (phân bổ có xét giới hạn năng lực workstation). D là ディスパッチング法 (quyết định công việc tiếp theo khi một công việc kết thúc). Tổ hợp đúng: A:1, B:4, C:5, D:7.","incorrect_reasons":{"ア":"Sai vì A không phải 工数計画, B không phải フォワード法, D không phải 順序づけ法.","イ":"Sai vì A không phải 工数計画, B không phải フォワード法, C không phải 無限山積法.","ウ":"Đây là đáp án đúng.","エ":"Sai vì C là 有限山積法 chứ không phải 無限山積法; D là ディスパッチング法 chứ không phải 順序づけ法."}},"key_knowledge":["余力管理 (Quản lý năng lực dư): Là nghiệp vụ thuộc giai đoạn kiểm soát sản xuất (生産統制), nhằm so sánh và điều chỉnh sự chênh lệch giữa năng lực (能力) và phụ tải thực tế (負荷) của con người/thiết bị bằng cách tăng ca, chuyển đổi công việc hoặc thuê ngoài.","工数計画 (Kế hoạch công số): Thuộc giai đoạn lập kế hoạch sản xuất (生産計画), tính toán tổng số giờ công cần thiết và đối chiếu với năng lực sẵn có từ trước khi sản xuất, khác với 余力管理 là hoạt động theo dõi và ứng biến khi đang sản xuất.","バックワード法 (Phương pháp lập lịch ngược / Backward): Lấy ngày giao hàng (納期) làm mốc xuất phát rồi tính lùi về quá khứ để xác định thời điểm muộn nhất phải khởi công từng công đoạn, giúp giảm thiểu tối đa tồn kho dở dang (仕掛品).","フォワード法 (Phương pháp lập lịch xuôi / Forward): Lấy thời điểm có thể bắt đầu làm việc (着手可能日) làm mốc rồi tính tiến dần về tương lai để xác định ngày hoàn thành sớm nhất, thường dùng khi muốn giao hàng càng sớm càng tốt.","有限山積法 (Phương pháp xếp tải hữu hạn / Finite loading): Phân bổ công việc vào các trạm làm việc (ワークステーション) có tính đến mức trần năng lực tối đa; nếu tải vượt quá năng lực thì công việc sẽ bị dời sang khung giờ hoặc ngày tiếp theo.","無限山積法 (Phương pháp xếp tải vô hạn / Infinite loading): Xếp dồn tất cả công việc vào các khung thời gian theo đúng lịch mà giả định năng lực của trạm là vô hạn; sau đó người quản lý mới can thiệp san phẳng tải (山崩し) ở những chỗ bị vượt quá năng lực.","ディスパッチング法 (Quy tắc điều độ / Dispatching): Phương pháp lập lịch trong sản xuất đơn chiếc (個別生産), đưa ra quyết định chọn công việc tiếp theo ngay tại thời điểm một công việc vừa hoàn tất ở trạm máy móc dựa trên các quy tắc ưu tiên (như thời gian gia công ngắn nhất SPT, hạn giao hàng sớm nhất EDD).","順序づけ法 (Phương pháp xếp thứ tự gia công / Sequencing): Xác định thứ tự thực hiện cho trước của một loạt công việc trên các máy móc trước khi bắt đầu sản xuất nhằm tối ưu hóa tổng thời gian (makespan) theo thuật toán định sẵn (như thuật toán Johnson)."],"exam_traps":["Nhầm 有限山積法 với 無限山積法.","Nhầm バックワード法 với フォワード法.","Nhầm ディスパッチング法 với 順序づけ法."],"vocabulary":[{"word":"工数","reading":"こうすう","meaning":"công (số người × thời gian)"},{"word":"日程","reading":"にってい","meaning":"lịch, tiến độ"},{"word":"生産統制","reading":"せいさんとうせい","meaning":"kiểm soát sản xuất"},{"word":"能力","reading":"のうりょく","meaning":"năng lực"},{"word":"負荷","reading":"ふか","meaning":"phụ tải"},{"word":"余力管理","reading":"よりょくかんり","meaning":"quản lý năng lực dư"},{"word":"工数計画","reading":"こうすうけいかく","meaning":"kế hoạch công"},{"word":"フォワード法","reading":"フォワードほう","meaning":"phương pháp lập lịch xuôi"},{"word":"バックワード法","reading":"バックワードほう","meaning":"phương pháp lập lịch ngược"},{"word":"有限山積法","reading":"ゆうげんさんせきほう","meaning":"phương pháp xếp hữu hạn"},{"word":"無限山積法","reading":"むげんさんせきほう","meaning":"phương pháp xếp vô hạn"},{"word":"ディスパッチング法","reading":"ディスパッチングほう","meaning":"phương pháp dispatch"},{"word":"順序づけ法","reading":"じゅんじょづけほう","meaning":"phương pháp sắp thứ tự"},{"word":"山積法","reading":"さんせきほう","meaning":"phương pháp xếp tải công việc"},{"word":"有限","reading":"ゆうげん","meaning":"hữu hạn"},{"word":"無限","reading":"むげん","meaning":"vô hạn"},{"word":"ディスパッチング","reading":"ディスパッチング","meaning":"dispatch (chọn việc kế tiếp)"},{"word":"順序づけ","reading":"じゅんじょづけ","meaning":"sắp xếp thứ tự"},{"word":"割り振る","reading":"わりふる","meaning":"phân bổ, chia việc"},{"word":"ワークステーション","reading":"ワークステーション","meaning":"trạm làm việc"},{"word":"スケジュール","reading":"スケジュール","meaning":"lịch trình"},{"word":"基準","reading":"きじゅん","meaning":"tiêu chuẩn, căn cứ"},{"word":"作成","reading":"さくせい","meaning":"tạo, lập"},{"word":"個別","reading":"こべつ","meaning":"cá biệt, từng cái"},{"word":"段階","reading":"だんかい","meaning":"giai đoạn"},{"word":"調整","reading":"ちょうせい","meaning":"điều chỉnh"}]},{"id":"11","chapter":"7.工程管理","question":{"japanese":"製作手配に関する記述として最も不適切なものは、次のうちどれか。","vietnamese":"Trong các mô tả về bố trí chế tạo (製作手配), mô tả nào KHÔNG phù hợp nhất?","furigana":"製作[せいさく]手配[てはい]に関する[かんする]記述[きじゅつ]として最も[もっとも]不適切[ふてきせつ]なものは、次[つぎ]のうちどれか。"},"options":[{"key":"ア","japanese":"製作手配は、管理部門から各担当部門へ該当する伝票を発行及び配布することにより、各担当部門に事前準備をさせる活動である。","vietnamese":"製作手配 là hoạt động phát hành và phân phối phiếu liên quan từ bộ phận quản lý đến từng bộ phận phụ trách để các bộ phận chuẩn bị trước.","furigana":"製作[せいさく]手配[てはい]は、管理[かんり]部門[ぶもん]から各担当[かくたんとう]部門[ぶもん]へ該当[がいとう]する伝票[でんぴょう]を発行[はっこう]及び[および]配布[はいふ]することにより、各担当[かくたんとう]部門[ぶもん]に事前[じぜん]準備[じゅんび]をさせる活動[かつどう]である。"},{"key":"イ","japanese":"作業予定表は、部門別あるいは工程別のスケジュールを指示するために用いる帳票である。","vietnamese":"Bảng kế hoạch công việc là chứng từ dùng để chỉ thị lịch theo bộ phận hoặc theo công đoạn.","furigana":"作業[さぎょう]予定[よてい]表[ひょう]は、部門別[ぶもんべつ]あるいは工程別[こうていべつ]のスケジュールを指示[しじ]するために用いる[もちいる]帳票[ちょうひょう]である。"},{"key":"ウ","japanese":"製作手配以降の業務は、現場作業に密着した処理が必要なために、工程管理の中心業務は製造現場に移る。","vietnamese":"Công việc sau 製作手配 cần xử lý sát với công việc hiện trường, nên trọng tâm quản lý công đoạn chuyển sang hiện trường sản xuất.","furigana":"製作[せいさく]手配[てはい]以降[いこう]の業務[ぎょうむ]は、現場[げんば]作業[さぎょう]に密着[みっちゃく]した処理[しょり]が必要[ひつよう]なために、工程[こうてい]管理[かんり]の中心[ちゅうしん]業務[ぎょうむ]は製造[せいぞう]現場[げんば]に移る[うつる]。"},{"key":"エ","japanese":"倉庫から資材を払い出すときには、在庫票を用いて指示する。","vietnamese":"Khi xuất vật tư từ kho, dùng phiếu tồn kho để chỉ thị.","furigana":"倉庫[そうこ]から資材[しざい]を払い出す[はらいだす]ときには、在庫[ざいこ]票[ひょう]を用い[もちい]て指示[しじ]する。"}],"correct_answer":"エ","explanation":{"correct_reason":"Khi xuất vật tư từ kho, cần dùng phiếu xuất kho (出庫票/払出票), không phải 在庫票 (phiếu tồn kho). 在庫票 dùng để ghi nhận và quản lý tồn kho, không phải chứng từ chỉ thị xuất kho.","incorrect_reasons":{"ア":"Sai vì 製作手配 đúng là phát hành, phân phối phiếu để các bộ phận chuẩn bị.","イ":"Sai vì 作業予定表 đúng là dùng để chỉ thị lịch theo bộ phận/công đoạn.","ウ":"Sai vì sau 製作手配, trọng tâm quản lý chuyển sang hiện trường là đúng.","エ":"Đây là đáp án đúng vì xuất kho phải dùng 出庫票/払出票, không dùng 在庫票."}},"key_knowledge":["Khái niệm bố trí chế tạo (製作手配): Là khâu chuyển giao từ giai đoạn lập kế hoạch tiến độ (日程計画) sang thực thi, được thực hiện bằng việc phát hành và phân phối các biểu mẫu, chứng từ (伝票の発行・配布) từ bộ phận quản lý đến các bộ phận phụ trách để chuẩn bị nguồn lực trước khi sản xuất.","Sự dịch chuyển trọng tâm quản lý: Trước khi thực hiện (製作手配), trọng tâm quản lý công đoạn nằm ở phòng kế hoạch/quản lý sản xuất; sau khi phân phối chứng từ chỉ thị, trọng tâm chuyển hẳn về hiện trường chế tạo (製造現場) để bám sát thao tác thực tế.","Bảng kế hoạch công việc (作業予定表): Là chứng từ dùng để chỉ thị tiến độ, thời gian bắt đầu và kết thúc theo từng bộ phận hoặc từng công đoạn (部門別・工程別スケジュール), giúp các tổ sản xuất nắm được thứ tự ưu tiên.","Chứng từ xuất kho (出庫票 / 払出票): Là chứng từ mang tính mệnh lệnh dùng để chỉ thị nhân viên kho xuất nguyên vật liệu, linh kiện cấp phát cho xưởng sản xuất theo đúng định mức và thời điểm yêu cầu.","Phân biệt với phiếu tồn kho (在庫票): (在庫票) là thẻ kho hoặc biểu mẫu ghi chép dùng để theo dõi, kiểm soát số lượng hàng hóa/vật tư đang lưu giữ trong kho, không có chức năng làm căn cứ hay chỉ thị xuất kho vật tư.","Phiếu chỉ thị thao tác (作業指示票 / 作業手配票): Được gửi trực tiếp đến tổ sản xuất, từng máy hoặc từng người thao tác, chỉ rõ chi tiết số lượng sản phẩm, bản vẽ kỹ thuật và quy trình tiêu chuẩn cần thực hiện.","Phiếu luân chuyển hiện vật (現品票 / 移動票): Đi kèm với lô bán thành phẩm (仕掛品) trong suốt hành trình qua các công đoạn chế tạo để nhận diện chủng loại, số lượng và xác nhận công đoạn đã hoàn thành.","Yêu cầu chuẩn bị 4M trong (製作手配): Thông qua việc phát hành phiếu, các bộ phận phụ trách phải hoàn tất chuẩn bị trước về vật tư (Material), đồ gá/khuôn mẫu (Machine/Tool), bản vẽ/quy trình (Method) và bố trí nhân công (Man) trước khi bắt đầu gia công."],"exam_traps":["Đánh tráo 在庫票 với 出庫票/払出票.","Đánh tráo thời điểm chuyển trọng tâm quản lý sang hiện trường.","Nhầm chức năng của 作業予定表."],"vocabulary":[{"word":"製作手配","reading":"せいさくてはい","meaning":"bố trí chế tạo"},{"word":"管理部門","reading":"かんりぶもん","meaning":"bộ phận quản lý"},{"word":"伝票","reading":"でんぴょう","meaning":"phiếu, chứng từ"},{"word":"発行","reading":"はっこう","meaning":"phát hành"},{"word":"配布","reading":"はいふ","meaning":"phân phối"},{"word":"事前準備","reading":"じぜんじゅんび","meaning":"chuẩn bị trước"},{"word":"作業予定表","reading":"さぎょうよていひょう","meaning":"bảng kế hoạch công việc"},{"word":"帳票","reading":"ちょうひょう","meaning":"chứng từ, biểu mẫu"},{"word":"現場作業","reading":"げんばさぎょう","meaning":"công việc hiện trường"},{"word":"工程管理","reading":"こうていかんり","meaning":"quản lý công đoạn"},{"word":"倉庫","reading":"そうこ","meaning":"kho"},{"word":"払い出す","reading":"はらいだす","meaning":"xuất ra"},{"word":"在庫票","reading":"ざいこひょう","meaning":"phiếu tồn kho"},{"word":"出庫票","reading":"しゅっこひょう","meaning":"phiếu xuất kho"},{"word":"担当部門","reading":"たんとうぶもん","meaning":"bộ phận phụ trách"},{"word":"該当","reading":"がいとう","meaning":"tương ứng, liên quan"},{"word":"部門別","reading":"ぶもんべつ","meaning":"theo bộ phận"},{"word":"工程別","reading":"こうていべつ","meaning":"theo công đoạn"},{"word":"以降","reading":"いこう","meaning":"sau đó, trở đi"},{"word":"密着","reading":"みっちゃく","meaning":"sát với, gắn chặt"},{"word":"移る","reading":"うつる","meaning":"chuyển sang"},{"word":"拠り所","reading":"よりどころ","meaning":"cơ sở"},{"word":"指示","reading":"しじ","meaning":"chỉ thị"}]},{"id":"12","chapter":"7.工程管理","question":{"japanese":"進捗管理の手順として最も適切なものは、次のうちどれか。","vietnamese":"Trình tự nào phù hợp nhất với quy trình quản lý tiến độ?","furigana":"進捗[しんちょく]管理[かんり]の手順[てじゅん]として最も[もっとも]適切[てきせつ]なものは、次[つぎ]のうちどれか。"},"options":[{"key":"ア","japanese":"進度分析→進度判定→進度対策→効果確認","vietnamese":"Phân tích tiến độ → Đánh giá tiến độ → Biện pháp tiến độ → Xác nhận hiệu quả","furigana":"進度[しんど]分析[ぶんせき]→進度[しんど]判定[はんてい]→進度[しんど]対策[たいさく]→効果[こうか]確認[かくにん]"},{"key":"イ","japanese":"効果確認→進度分析→進度判定→進度対策","vietnamese":"Xác nhận hiệu quả → Phân tích tiến độ → Đánh giá tiến độ → Biện pháp tiến độ","furigana":"効果[こうか]確認[かくにん]→進度[しんど]分析[ぶんせき]→進度[しんど]判定[はんてい]→進度[しんど]対策[たいさく]"},{"key":"ウ","japanese":"進度判定→進度対策→進度分析→効果確認","vietnamese":"Đánh giá tiến độ → Biện pháp tiến độ → Phân tích tiến độ → Xác nhận hiệu quả","furigana":"進度[しんど]判定[はんてい]→進度[しんど]対策[たいさく]→進度[しんど]分析[ぶんせき]→効果[こうか]確認[かくにん]"},{"key":"エ","japanese":"進度分析→効果確認→進度判定→進度対策","vietnamese":"Phân tích tiến độ → Xác nhận hiệu quả → Đánh giá tiến độ → Biện pháp tiến độ","furigana":"進度[しんど]分析[ぶんせき]→効果[こうか]確認[かくにん]→進度[しんど]判定[はんてい]→進度[しんど]対策[たいさく]"}],"correct_answer":"ア","explanation":{"correct_reason":"Quản lý tiến độ chuẩn gồm: phân tích tiến độ (so sánh kế hoạch và thực tế) → đánh giá tiến độ (nhanh/chậm) → biện pháp tiến độ (xử lý) → xác nhận hiệu quả. Vì vậy ア là trình tự đúng.","incorrect_reasons":{"ア":"Đây là đáp án đúng.","イ":"Sai vì không thể xác nhận hiệu quả trước khi phân tích và đánh giá.","ウ":"Sai vì không thể đánh giá tiến độ trước khi phân tích.","エ":"Sai vì xác nhận hiệu quả phải sau khi thực hiện biện pháp."}},"key_knowledge":["Khái niệm quản lý tiến độ (進捗管理 / しんちょくかんり): Là hoạt động theo dõi, nắm bắt tình hình sản xuất thực tế tại hiện trường so với kế hoạch đã định nhằm đảm bảo đúng thời hạn giao hàng (納期) và đủ số lượng sản phẩm.","Bước 1 - Phân tích tiến độ (進度分析): Thu thập dữ liệu kết quả thực tế (実績) từ hiện trường và so sánh trực tiếp với kế hoạch tác nghiệp (計画) để định lượng chính xác độ sai lệch (đã làm được bao nhiêu, thiếu bao nhiêu).","Bước 2 - Đánh giá tiến độ (進度判定): Dựa trên độ lệch đã phân tích để phán đoán tình trạng công việc đang bị trễ (遅れ) hay vượt trước (進み), đồng thời nhận định mức độ ảnh hưởng của sự trễ đó đối với ngày xuất hàng cuối cùng.","Bước 3 - Biện pháp xử lý tiến độ (進度対策): Đưa ra hành động cụ thể để khắc phục tình trạng chậm trễ, chẳng hạn như bố trí tăng ca (残業), điều động nhân lực hỗ trợ (応援), hoặc thay đổi trình tự gia công.","Bước 4 - Xác nhận hiệu quả (効果確認): Kiểm tra lại xem biện pháp xử lý tiến độ đã áp dụng có mang lại hiệu quả thực tế và giúp dây chuyền bắt kịp tiến độ kế hoạch ban đầu hay chưa.","Bản chất theo vòng lặp PDCA: Trình tự 4 bước này chính là việc vận dụng chu trình PDCA vào kiểm soát công đoạn, trong đó Phân tích & Đánh giá là Check, Biện pháp là Action, và Xác nhận hiệu quả khép lại chu trình.","Phân biệt với Quản lý năng lực dư thừa (余力管理): Quản lý tiến độ (進捗管理) tập trung vào thời gian và kỳ hạn giao hàng (納期), trong khi quản lý tải trọng/dư lực tập trung vào việc cân đối giữa tải trọng công việc (負荷) và năng lực máy móc/con người (能力).","Công cụ trực quan hóa tiến độ thường gặp: Để thực hiện tốt 4 bước này, nhà máy thường dùng biểu đồ Gantt (ガントチャート) hoặc bảng quản lý tiến độ (進度管理板) hiển thị trực quan ngay tại nơi sản xuất."],"exam_traps":["Đảo thứ tự các bước.","Đặt 効果確認 lên trước 進度対策.","Bỏ qua bước 進度分析."],"vocabulary":[{"word":"進捗管理","reading":"しんちょくかんり","meaning":"quản lý tiến độ"},{"word":"手順","reading":"てじゅん","meaning":"trình tự, thủ tục"},{"word":"進度分析","reading":"しんどぶんせき","meaning":"phân tích tiến độ"},{"word":"進度判定","reading":"しんどはんてい","meaning":"đánh giá tiến độ"},{"word":"進度対策","reading":"しんどたいさく","meaning":"biện pháp tiến độ"},{"word":"効果確認","reading":"こうかかくにん","meaning":"xác nhận hiệu quả"},{"word":"進捗管理の手順","reading":"しんちょくかんりのてじゅん","meaning":"trình tự quản lý tiến độ"},{"word":"進度","reading":"しんど","meaning":"tiến độ"},{"word":"判定","reading":"はんてい","meaning":"đánh giá, phán định"},{"word":"対策","reading":"たいさく","meaning":"biện pháp"},{"word":"確認","reading":"かくにん","meaning":"xác nhận"},{"word":"順番","reading":"じゅんばん","meaning":"thứ tự"},{"word":"計画","reading":"けいかく","meaning":"kế hoạch"},{"word":"実績","reading":"じっせき","meaning":"kết quả thực tế"},{"word":"遅れ","reading":"おくれ","meaning":"sự chậm trễ"},{"word":"遅延","reading":"ちえん","meaning":"chậm trễ"},{"word":"回復","reading":"かいふく","meaning":"phục hồi"},{"word":"報告","reading":"ほうこく","meaning":"báo cáo"},{"word":"是正","reading":"ぜせい","meaning":"khắc phục, sửa chữa"},{"word":"フォロー","reading":"フォロー","meaning":"theo dõi, đôn đốc"}]},{"id":"13","chapter":"9.資材・在庫管理","question":{"japanese":"現品管理に関する記述として最も不適切なものは、次のうちどれか。","vietnamese":"Trong các mô tả về quản lý hàng thực tế (現品管理), mô tả nào KHÔNG phù hợp nhất?","furigana":"現品[げんぴん]管理[かんり]に関する[かんする]記述[きじゅつ]として最も[もっとも]不適切[ふてきせつ]なものは、次[つぎ]のうちどれか。"},"options":[{"key":"ア","japanese":"バーコード管理システムや自動マテリアルハンドリングシステムは、現品の運搬や保管作業の簡易化に貢献する。","vietnamese":"Hệ thống quản lý mã vạch và hệ thống xử lý vật liệu tự động góp phần đơn giản hóa vận chuyển và bảo quản hàng thực tế.","furigana":"バーコード管理[かんり]システムや自動[じどう]マテリアルハンドリングシステムは、現品[げんぴん]の運搬[うんぱん]や保管[ほかん]作業[さぎょう]の簡易化[かんいか]に貢献[こうけん]する。"},{"key":"イ","japanese":"現品管理の目的には、所在と数量を常時把握することがある。","vietnamese":"Mục đích của quản lý hàng thực tế là nắm bắt thường xuyên vị trí và số lượng.","furigana":"現品[げんぴん]管理[かんり]の目的[もくてき]には、所在[しょざい]と数量[すうりょう]を常時[じょうじ]把握[はあく]することがある。"},{"key":"ウ","japanese":"棚卸における循環棚卸は、一斉棚卸に含まれる。","vietnamese":"Kiểm kê luân phiên trong kiểm kê hàng tồn được bao gồm trong kiểm kê đồng loạt.","furigana":"棚卸[たなおろし]における循環[じゅんかん]棚卸[たなおろし]は、一斉[いっせい]棚卸[たなおろし]に含ま[ふくま]れる。"},{"key":"エ","japanese":"標準容器の使用及び標準荷姿を設定することは、現品の数量チェックや保管の容易化に貢献する。","vietnamese":"Dùng thùng chuẩn và thiết lập kiện hàng chuẩn góp phần kiểm tra số lượng và bảo quản dễ dàng.","furigana":"標準[ひょうじゅん]容器[ようき]の使用[しよう]及び[および]標準[ひょうじゅん]荷[に]姿[すがた]を設定[せってい]することは、現品[げんぴん]の数量[すうりょう]チェックや保管[ほかん]の容易化[よういか]に貢献[こうけん]する。"}],"correct_answer":"ウ","explanation":{"correct_reason":"循環棚卸 (kiểm kê luân phiên) và 一斉棚卸 (kiểm kê đồng loạt) là hai phương pháp khác nhau. 循環棚卸 thực hiện lần lượt theo khu vực/loại hàng trong năm, không nằm trong 一斉棚卸. Vì vậy mô tả ウ không phù hợp.","incorrect_reasons":{"ア":"Sai vì mã vạch và tự động hóa đúng là góp phần đơn giản hóa vận chuyển, bảo quản.","イ":"Sai vì nắm vị trí và số lượng thường xuyên là mục đích đúng của 現品管理.","ウ":"Đây là đáp án đúng vì 循環棚卸 không thuộc 一斉棚卸.","エ":"Sai vì thùng chuẩn và kiện hàng chuẩn đúng là giúp kiểm tra số lượng và bảo quản."}},"key_knowledge":["Quản lý hàng thực tế (現品管理 - Genpin Kanri) là hoạt động quản lý vật tư, bán thành phẩm và thành phẩm tại hiện trường nhằm nắm bắt chính xác vị trí (所在), số lượng (数量), trạng thái chất lượng, đảm bảo khớp với số liệu sổ sách (帳簿在庫).","Kiểm kê thực tế (実地棚卸) được chia thành 2 phương pháp độc lập dựa trên cách thức tổ chức: Kiểm kê đồng loạt (一斉棚卸) và Kiểm kê luân phiên (循環棚卸). Hai phương pháp này song song và loại trừ nhau, không có quan hệ bao hàm.","Kiểm kê đồng loạt (一斉棚卸 - Issei Tanaoroshi) là phương pháp dừng toàn bộ hoạt động xuất nhập kho và sản xuất trong một khoảng thời gian nhất định (thường vào cuối kỳ kế toán hoặc cuối tháng) để tổng kiểm đếm toàn bộ hàng tồn kho cùng một lúc.","Kiểm kê luân phiên (循環棚卸 - Junkan Tanaoroshi / Cycle counting) là phương pháp chia nhỏ danh mục theo nhóm sản phẩm, khu vực kho hoặc phân tích ABC để kiểm tra lần lượt, liên tục từng phần trong năm mà không làm gián đoạn sản xuất.","Sử dụng thùng chứa tiêu chuẩn (標準容器) và quy cách đóng gói tiêu chuẩn (標準荷姿) giúp người kiểm kê chỉ cần đếm số thùng hoặc khối pallet (ví dụ: 1 khay cố định 50 chi tiết) thay vì đếm lẻ từng sản phẩm, vừa tăng tốc độ vừa giảm nhầm lẫn.","Hệ thống mã vạch (バーコード) và hệ thống xử lý vật liệu tự động (自動マテリアルハンドリングシステム) như kho tự động (AS/RS), xe tự hành (AGV) giúp dữ liệu hiện vật được cập nhật theo thời gian thực (Real-time), giảm tải thao tác thủ công.","Mục tiêu cốt lõi của quản lý hiện vật tại xưởng sản xuất là triệt tiêu lãng phí tìm kiếm (探すムダ), ngăn chặn tình trạng thất thoát, nhầm lẫn linh kiện và duy trì nguyên tắc nhập trước xuất trước (先入れ先出し - FIFO)."],"exam_traps":["Gộp 循環棚卸 vào 一斉棚卸.","Đánh tráo mục đích của 現品管理.","Nhầm lợi ích của thùng chuẩn với quản lý sổ sách."],"vocabulary":[{"word":"現品管理","reading":"げんぴんかんり","meaning":"quản lý hàng thực tế"},{"word":"バーコード","reading":"バーコード","meaning":"mã vạch"},{"word":"自動マテリアルハンドリングシステム","reading":"じどうマテリアルハンドリングシステム","meaning":"hệ thống xử lý vật liệu tự động"},{"word":"運搬","reading":"うんぱん","meaning":"vận chuyển"},{"word":"保管作業","reading":"ほかんさぎょう","meaning":"công việc bảo quản"},{"word":"所在","reading":"しょざい","meaning":"vị trí hiện diện"},{"word":"常時把握","reading":"じょうじはあく","meaning":"nắm bắt thường xuyên"},{"word":"棚卸","reading":"たなおろし","meaning":"kiểm kê hàng tồn"},{"word":"循環棚卸","reading":"じゅんかんたなおろし","meaning":"kiểm kê luân phiên"},{"word":"一斉棚卸","reading":"いっせいたなおろし","meaning":"kiểm kê đồng loạt"},{"word":"標準容器","reading":"ひょうじゅんようき","meaning":"thùng chứa chuẩn"},{"word":"標準荷姿","reading":"ひょうじゅんにすがた","meaning":"kiện hàng chuẩn"},{"word":"数量チェック","reading":"すうりょうチェック","meaning":"kiểm tra số lượng"},{"word":"荷姿","reading":"にすがた","meaning":"kiện hàng, dạng đóng gói"},{"word":"簡易化","reading":"かんいか","meaning":"đơn giản hóa"},{"word":"容易化","reading":"よういか","meaning":"làm cho dễ dàng"},{"word":"貢献","reading":"こうけん","meaning":"đóng góp"},{"word":"自動","reading":"じどう","meaning":"tự động"},{"word":"一斉","reading":"いっせい","meaning":"đồng loạt"},{"word":"循環","reading":"じゅんかん","meaning":"luân phiên, tuần hoàn"}]},{"id":"14","chapter":"6.作業管理","question":{"japanese":"以下の数式に関する生産性測定指標として最も適切なものは、次のうちどれか。\n有効作業時間／総労働時間","vietnamese":"Chỉ số đo năng suất nào phù hợp nhất với công thức sau?\nThời gian làm việc hữu ích / Tổng thời gian lao động","furigana":"以下[いか]の数式[すうしき]に関する[かんする]生産性[せいさんせい]測定[そくてい]指標[しひょう]として最も[もっとも]適切[てきせつ]なものは、次[つぎ]のうちどれか。\n有効[ゆうこう]作業[さぎょう]時間[じかん]／総[そう]労働[ろうどう]時間[じかん]"},"options":[{"key":"ア","japanese":"歩留率","vietnamese":"Tỷ lệ thu hồi (tỷ lệ sản phẩm đạt)","furigana":"歩留率[ぶどまりりつ]"},{"key":"イ","japanese":"作業能率","vietnamese":"Hiệu suất công việc","furigana":"作業[さぎょう]能率[のうりつ]"},{"key":"ウ","japanese":"稼働率","vietnamese":"Tỷ lệ vận hành","furigana":"稼働率[かどうりつ]"},{"key":"エ","japanese":"操業度","vietnamese":"Mức độ hoạt động","furigana":"操業度[そうぎょうど]"}],"correct_answer":"ウ","explanation":{"correct_reason":"稼働率 (tỷ lệ vận hành) = thời gian làm việc hữu ích / tổng thời gian lao động. Công thức này đo tỷ lệ thời gian thực sự tạo ra giá trị so với tổng thời gian được huy động.","incorrect_reasons":{"ア":"Sai vì 歩留率 là tỷ lệ sản phẩm đạt trên tổng nguyên liệu hoặc tổng sản phẩm đầu vào.","イ":"Sai vì 作業能率 thường so sánh thời gian tiêu chuẩn với thời gian thực tế, không phải tỷ lệ thời gian hữu ích trên tổng thời gian.","ウ":"Đây là đáp án đúng.","エ":"Sai vì 操業度 phản ánh mức huy động năng lực sản xuất so với năng lực tối đa."}},"key_knowledge":["Định nghĩa Tỷ lệ vận hành (稼働率 - kadouritsu): Là chỉ số đo lường mức độ sử dụng thời gian, tính bằng tỷ lệ giữa Thời gian làm việc hữu ích (有効作業時間) chia cho Tổng thời gian lao động (総労働時間 hoặc 就業時間).","Phân biệt với Hiệu suất làm việc (作業能率 - sagyou nouritsu): 作業能率 đo tốc độ thao tác của người lao động, tính bằng Thời gian tiêu chuẩn (標準時間 × sản lượng) chia cho Thời gian làm việc thực tế (実際作業時間).","Công thức Hiệu suất tổng hợp (総合能率): Trong quản lý thao tác, 総合能率 = 稼働率 (Tỷ lệ vận hành) × 作業能率 (Hiệu suất làm việc), phản ánh toàn diện năng suất lao động.","Bản chất của Thời gian làm việc hữu ích (有効作業時間): Là thời gian thực tế người lao động trực tiếp tạo ra sản phẩm, sau khi đã trừ đi các thời gian chết như chờ linh kiện, máy hỏng hoặc họp giao ban.","Phân biệt với Tỷ lệ thu hồi (歩留率 - budomariritsu): 歩留率 là chỉ số đo lường vật liệu (đầu ra đạt chuẩn / đầu vào nguyên liệu), không dùng để đo lường phân bổ thời gian làm việc.","Phân biệt với Mức độ hoạt động (操業度 - sougyoudo): 操業度 đo mức độ huy động công suất nhà xưởng so với năng lực sản xuất tối đa (生産能力), mang tính vĩ mô về năng lực thiết bị chứ không đơn thuần là thời gian một ca.","Nguyên nhân làm giảm 稼働率 trong nhà xưởng: Thường do tổn thất dừng chờ (手待ち), thời gian chuyển đổi mã hàng (段取り替え) kéo dài hoặc trục trặc thiết bị.","Biện pháp nâng cao 稼働率: Tập trung rút ngắn thời gian chuẩn bị (chuẩn bị trước vật tư, dụng cụ ngoài chuyền) và loại bỏ thời gian lãng phí thay vì bắt công nhân thao tác vội vã."],"exam_traps":["Nhầm 稼働率 với 操業度.","Nhầm 稼働率 với 作業能率.","Đổi tử số và mẫu số của công thức."],"vocabulary":[{"word":"数式","reading":"すうしき","meaning":"công thức"},{"word":"生産性","reading":"せいさんせい","meaning":"năng suất"},{"word":"測定指標","reading":"そくていしひょう","meaning":"chỉ số đo"},{"word":"有効作業時間","reading":"ゆうこうさぎょうじかん","meaning":"thời gian làm việc hữu ích"},{"word":"総労働時間","reading":"そうろうどうじかん","meaning":"tổng thời gian lao động"},{"word":"歩留率","reading":"ぶどまりりつ","meaning":"tỷ lệ thu hồi"},{"word":"作業能率","reading":"さぎょうのうりつ","meaning":"hiệu suất công việc"},{"word":"稼働率","reading":"かどうりつ","meaning":"tỷ lệ vận hành"},{"word":"操業度","reading":"そうぎょうど","meaning":"mức độ hoạt động"},{"word":"指標","reading":"しひょう","meaning":"chỉ số"},{"word":"分子","reading":"ぶんし","meaning":"tử số"},{"word":"分母","reading":"ぶんぼ","meaning":"mẫu số"},{"word":"能率","reading":"のうりつ","meaning":"hiệu suất"},{"word":"比率","reading":"ひりつ","meaning":"tỷ lệ"},{"word":"測る","reading":"はかる","meaning":"đo"},{"word":"稼働時間","reading":"かどうじかん","meaning":"thời gian vận hành"},{"word":"労働時間","reading":"ろうどうじかん","meaning":"thời gian lao động"},{"word":"生産量","reading":"せいさんりょう","meaning":"sản lượng"},{"word":"投入","reading":"とうにゅう","meaning":"đầu vào"},{"word":"産出","reading":"さんしゅつ","meaning":"đầu ra"}]},{"id":"15","chapter":"8.設備管理","question":{"japanese":"設備管理の機能に関する記述として最も不適切なものは、次のうちどれか。","vietnamese":"Trong các mô tả về chức năng quản lý thiết bị, mô tả nào KHÔNG phù hợp nhất?","furigana":"設備[せつび]管理[かんり]の機能[きのう]に関する[かんする]記述[きじゅつ]として最も[もっとも]不適切[ふてきせつ]なものは、次[つぎ]のうちどれか。"},"options":[{"key":"ア","japanese":"保全過程の経済的側面においては、保全経済計画→保全費統制→保全予算編成→保全効果測定の流れで業務が遂行される。","vietnamese":"Ở khía cạnh kinh tế của quá trình bảo trì, công việc được thực hiện theo trình tự: kế hoạch kinh tế bảo trì → kiểm soát chi phí bảo trì → lập ngân sách bảo trì → đo hiệu quả bảo trì.","furigana":"保全[ほぜん]過程[かてい]の経済的[けいざいてき]側面[そくめん]においては、保全[ほぜん]経済[けいざい]計画[けいかく]→保全費[ほぜんひ]統制[とうせい]→保全[ほぜん]予算[よさん]編成[へんせい]→保全[ほぜん]効果[こうか]測定[そくてい]の流れ[ながれ]で業務[ぎょうむ]が遂行[すいこう]される。"},{"key":"イ","japanese":"保全過程の技術的側面においては、設備改善・研究→保全標準設定→保全計画→保全資材管理→保全実施・統制→保全記録報告の流れで業務が遂行される。","vietnamese":"Ở khía cạnh kỹ thuật của quá trình bảo trì, công việc được thực hiện theo trình tự: cải tiến/nghiên cứu thiết bị → thiết lập tiêu chuẩn bảo trì → kế hoạch bảo trì → quản lý vật tư bảo trì → thực hiện/kiểm soát bảo trì → báo cáo ghi chép bảo trì.","furigana":"保全[ほぜん]過程[かてい]の技術的[ぎじゅつてき]側面[そくめん]においては、設備[せつび]改善[かいぜん]・研究[けんきゅう]→保全[ほぜん]標準[ひょうじゅん]設定[せってい]→保全[ほぜん]計画[けいかく]→保全[ほぜん]資材[しざい]管理[かんり]→保全[ほぜん]実施[じっし]・統制[とうせい]→保全[ほぜん]記録[きろく]報告[ほうこく]の流れ[ながれ]で業務[ぎょうむ]が遂行[すいこう]される。"},{"key":"ウ","japanese":"建設過程の経済的側面においては、設備経済計画→設備予算編成→設備予算統制→設備予算監査の流れで業務が遂行される。","vietnamese":"Ở khía cạnh kinh tế của quá trình xây dựng thiết bị, công việc được thực hiện theo trình tự: kế hoạch kinh tế thiết bị → lập ngân sách thiết bị → kiểm soát ngân sách thiết bị → kiểm toán ngân sách thiết bị.","furigana":"建設[けんせつ]過程[かてい]の経済的[けいざいてき]側面[そくめん]においては、設備[せつび]経済[けいざい]計画[けいかく]→設備[せつび]予算[よさん]編成[へんせい]→設備[せつび]予算[よさん]統制[とうせい]→設備[せつび]予算[よさん]監査[かんさ]の流れ[ながれ]で業務[ぎょうむ]が遂行[すいこう]される。"},{"key":"エ","japanese":"建設過程の技術的側面においては、設備調査・研究→設備計画→設備設計→建築工事・管理→設備監査の流れで業務が遂行される。","vietnamese":"Ở khía cạnh kỹ thuật của quá trình xây dựng thiết bị, công việc được thực hiện theo trình tự: điều tra/nghiên cứu thiết bị → kế hoạch thiết bị → thiết kế thiết bị → thi công/quản lý xây dựng → kiểm toán thiết bị.","furigana":"建設[けんせつ]過程[かてい]の技術的[ぎじゅつてき]側面[そくめん]においては、設備[せつび]調査[ちょうさ]・研究[けんきゅう]→設備[せつび]計画[けいかく]→設備[せつび]設計[せっけい]→建築[けんちく]工事[こうじ]・管理[かんり]→設備[せつび]監査[かんさ]の流れ[ながれ]で業務[ぎょうむ]が遂行[すいこう]される。"}],"correct_answer":"ア","explanation":{"correct_reason":"Trình tự kinh tế của bảo trì phải là 保全経済計画 → 保全予算編成 → 保全費統制 → 保全効果測定. Phương án ア đặt 保全費統制 trước 保全予算編成, tức kiểm soát chi phí trước khi lập ngân sách, nên sai logic.","incorrect_reasons":{"ア":"Đây là đáp án đúng vì thứ tự 保全費統制 và 保全予算編成 bị đảo.","イ":"Sai vì trình tự kỹ thuật của bảo trì được mô tả đúng.","ウ":"Sai vì trình tự kinh tế của xây dựng thiết bị được mô tả đúng.","エ":"Sai vì trình tự kỹ thuật của xây dựng thiết bị được mô tả đúng."}},"key_knowledge":["Khung quản trị thiết bị (設備管理の機能体系) được phân định theo ma trận 2x2: hai quá trình vòng đời gồm quá trình đầu tư/xây dựng (建設過程) và quá trình bảo trì (保全過程), kết hợp với hai khía cạnh là mặt kỹ thuật (技術的側面) và mặt kinh tế (経済的側面).","Trình tự kinh tế trong quá trình bảo trì (保全過程の経済的側面) gồm 4 bước chuẩn: Kế hoạch kinh tế bảo trì (保全経済計画) → Lập dự toán ngân sách (保全予算編成) → Kiểm soát chi phí thực tế (保全費統制) → Đo lường hiệu quả bảo trì (保全効果測定).","Nguyên tắc quản trị tài chính cơ bản: Bao giờ cũng phải 'Lập ngân sách' (予算編成) trước để duyệt hạn mức tiền, sau đó mới tiến hành 'Kiểm soát chi phí' (費統制/予算統制) trong quá trình thực chi để không vượt hạn mức.","Trình tự kỹ thuật trong quá trình bảo trì (保全過程の技術的側面) gồm 6 bước: Cải tiến/nghiên cứu thiết bị (設備改善・研究) → Thiết lập tiêu chuẩn bảo dưỡng (保全標準設定) → Lập kế hoạch bảo trì (保全計画) → Quản lý vật tư phụ tùng (保全資材管理) → Thực hiện và kiểm soát sửa chữa (保全実施・統制) → Báo cáo và lưu hồ sơ (保全記録報告).","Trình tự kinh tế trong xây dựng thiết bị (建設過程の経済的側面): Bắt đầu từ kế hoạch kinh tế đầu tư (設備経済計画) → Lập ngân sách đầu tư (設備予算編成) → Kiểm soát giải ngân (設備予算統制) → Kiểm toán tài chính sau đầu tư (設備予算監査).","Trình tự kỹ thuật trong xây dựng thiết bị (建設過程の技術的側面): Điều tra nghiên cứu công nghệ (設備調査・研究) → Lập phương án thiết bị (設備計画) → Thiết kế chi tiết (設備設計) → Thi công lắp đặt và chạy thử (建設工事・管理) → Nghiệm thu đánh giá kỹ thuật (設備監査).","Liên kết chu trình PDCA trong quản lý bảo trì: Bước báo cáo lưu trữ hồ sơ (保全記録) ở cuối chu trình kỹ thuật chính là dữ liệu đầu vào cốt lõi để quay lại bước cải tiến thiết bị (設備改善) và điều chỉnh tiêu chuẩn bảo dưỡng định kỳ.","Mối quan hệ chi phí vòng đời (ライフサイクルコスト - LCC): Giai đoạn xây dựng (建設過程) quyết định chi phí mua sắm ban đầu (Initial Cost), trong khi giai đoạn bảo trì (保全過程) quyết định chi phí vận hành và bảo dưỡng (Running Cost) trong suốt tuổi thọ thiết bị."],"exam_traps":["Đảo 保全予算編成 và 保全費統制.","Nhầm trình tự kỹ thuật với trình tự kinh tế.","Đánh tráo giai đoạn xây dựng với giai đoạn bảo trì."],"vocabulary":[{"word":"設備管理","reading":"せつびかんり","meaning":"quản lý thiết bị"},{"word":"保全過程","reading":"ほぜんかてい","meaning":"quá trình bảo trì"},{"word":"経済的側面","reading":"けいざいてきそくめん","meaning":"khía cạnh kinh tế"},{"word":"保全経済計画","reading":"ほぜんけいざいけいかく","meaning":"kế hoạch kinh tế bảo trì"},{"word":"保全費統制","reading":"ほぜんひとうせい","meaning":"kiểm soát chi phí bảo trì"},{"word":"保全予算編成","reading":"ほぜんよさんへんせい","meaning":"lập ngân sách bảo trì"},{"word":"保全効果測定","reading":"ほぜんこうかそくてい","meaning":"đo hiệu quả bảo trì"},{"word":"技術的側面","reading":"ぎじゅつてきそくめん","meaning":"khía cạnh kỹ thuật"},{"word":"保全標準設定","reading":"ほぜんひょうじゅんせってい","meaning":"thiết lập tiêu chuẩn bảo trì"},{"word":"保全資材管理","reading":"ほぜんしざいかんり","meaning":"quản lý vật tư bảo trì"},{"word":"建設過程","reading":"けんせつかてい","meaning":"quá trình xây dựng"},{"word":"設備予算監査","reading":"せつびよさんかんさ","meaning":"kiểm toán ngân sách thiết bị"},{"word":"設備調査","reading":"せつびちょうさ","meaning":"điều tra thiết bị"},{"word":"建築工事","reading":"けんちくこうじ","meaning":"thi công xây dựng"},{"word":"流れ","reading":"ながれ","meaning":"dòng, trình tự"},{"word":"遂行","reading":"すいこう","meaning":"thực hiện, tiến hành"},{"word":"統制","reading":"とうせい","meaning":"kiểm soát"},{"word":"監査","reading":"かんさ","meaning":"kiểm toán"},{"word":"編成","reading":"へんせい","meaning":"lập, tổ chức"},{"word":"測定","reading":"そくてい","meaning":"đo lường"},{"word":"改善","reading":"かいぜん","meaning":"cải tiến"},{"word":"維持","reading":"いじ","meaning":"duy trì"},{"word":"保全","reading":"ほぜん","meaning":"bảo trì"},{"word":"設備","reading":"せつび","meaning":"thiết bị"}]},{"id":"16","chapter":"8.設備管理","question":{"japanese":"以下に示す設備保全の＜種類＞と＜内容＞の組合せとして適切なものは、次のうちどれか。\n＜種類＞ A.予防保全 B.保全予防 C.事後保全 D.改良保全\n＜内容＞\n1. 設備自体の体質改善をする。\n2. 故障してから修理した方が、経済的な設備に適用する。\n3. 設備の設計段階から、保全が不要又は少なくて済むように設計する。\n4. 定期的な点検と劣化部位の事前取替を行う方が、経済的な設備に適用する。","vietnamese":"Tổ hợp nào phù hợp giữa <loại> và <nội dung> của bảo trì thiết bị?\n<Loại> A. Bảo trì phòng ngừa B. Phòng ngừa bảo trì C. Bảo trì sau sự cố D. Bảo trì cải tiến\n<Nội dung>\n1. Cải thiện bản chất của thiết bị.\n2. Áp dụng cho thiết bị mà sửa sau khi hỏng kinh tế hơn.\n3. Thiết kế từ giai đoạn thiết kế sao cho không cần hoặc ít cần bảo trì.\n4. Áp dụng cho thiết bị mà kiểm tra định kỳ và thay thế bộ phận xuống cấp trước khi hỏng kinh tế hơn.","furigana":"以下[いか]に示す[しめす]設備[せつび]保全[ほぜん]の＜種類[しゅるい]＞と＜内容[ないよう]＞の組合せ[くみあわせ]として適切[てきせつ]なものは、次[つぎ]のうちどれか。\n＜種類[しゅるい]＞ A.予防[よぼう]保全[ほぜん] B.保全[ほぜん]予防[よぼう] C.事後[じご]保全[ほぜん] D.改良[かいりょう]保全[ほぜん]\n＜内容[ないよう]＞\n1. 設備[せつび]自体[じたい]の体質[たいしつ]改善[かいぜん]をする。\n2. 故障[こしょう]してから修理[しゅうり]した方[ほう]が、経済的[けいざいてき]な設備[せつび]に適用[てきよう]する。\n3. 設備[せつび]の設計[せっけい]段階[だんかい]から、保全[ほぜん]が不要[ふよう]又は[または]少なく[すくなく]て済む[すむ]ように設計[せっけい]する。\n4. 定期的[ていきてき]な点検[てんけん]と劣化[れっか]部位[ぶい]の事前[じぜん]取替[とりかえ]を行う[おこなう]方[ほう]が、経済的[けいざいてき]な設備[せつび]に適用[てきよう]する。"},"options":[{"key":"ア","japanese":"A:1","vietnamese":"A:1","furigana":"A:1"},{"key":"イ","japanese":"B:3","vietnamese":"B:3","furigana":"B:3"},{"key":"ウ","japanese":"C:4","vietnamese":"C:4","furigana":"C:4"},{"key":"エ","japanese":"D:2","vietnamese":"D:2","furigana":"D:2"}],"correct_answer":"イ","explanation":{"correct_reason":"保全予防 (phòng ngừa bảo trì) là thiết kế ngay từ giai đoạn đầu để giảm hoặc loại bỏ nhu cầu bảo trì, tương ứng nội dung 3. Vì vậy B:3 là tổ hợp đúng.","incorrect_reasons":{"ア":"Sai vì 予防保全 (A) là kiểm tra định kỳ và thay thế trước khi hỏng, tương ứng 4, không phải 1.","イ":"Đây là đáp án đúng.","ウ":"Sai vì 事後保全 (C) là sửa sau khi hỏng, tương ứng 2, không phải 4.","エ":"Sai vì 改良保全 (D) là cải tiến thiết bị, tương ứng 1, không phải 2."}},"key_knowledge":["Khái niệm Bảo trì thiết bị (設備保全): Là toàn bộ các hoạt động nhằm duy trì tính năng, độ chính xác và tuổi thọ của máy móc, hạn chế thời gian dừng máy (チョコ停/ドカ停) với chi phí kinh tế nhất.","Bảo trì phòng ngừa (予防保全 - Preventive Maintenance): Tiến hành kiểm tra định kỳ, tra dầu mỡ hoặc thay thế linh kiện trước khi hỏng hóc xảy ra, phù hợp với thiết bị cốt lõi mà việc dừng máy gây tổn thất lớn.","Phòng ngừa bảo trì (保全予防 - Maintenance Prevention): Tiếp cận ngay từ khâu thiết kế hoặc chọn mua thiết bị, nhằm tạo ra máy móc bền bỉ, 'bảo trì bằng không' (メンテナンスフリー) hoặc ít phải bảo trì nhất.","Phân biệt dễ nhầm giữa 予防保全 và 保全予防: '予防保全' là hành động bảo trì để phòng ngừa sự cố trong vận hành; còn '保全予防' là thiết kế từ trước để loại trừ chính nhu cầu phải đi làm bảo trì.","Bảo trì sau sự cố (事後保全 - Breakdown Maintenance): Thiết bị gặp sự cố hoặc hư hỏng hoàn toàn rồi mới tiến hành sửa chữa; áp dụng hợp lý cho các thiết bị phụ trợ, giá rẻ, thay thế nhanh và việc hỏng không ảnh hưởng dây chuyền.","Bảo trì cải tiến (改良保全 - Corrective Maintenance): Cải thiện bản chất máy móc (設備自体の体質改善) bằng cách gia cố kết cấu, đổi vật liệu chịu lực tốt hơn nhằm khắc phục triệt để các lỗi hỏng hóc lặp đi lặp lại.","Bảo trì dự đoán (予知保全 - Predictive Maintenance): Đo đạc độ rung, nhiệt độ hoặc dầu nhờn bằng cảm biến (状態監視保全 - CBM) để dự đoán chính xác thời điểm hỏng trước khi quyết định can thiệp thay thế.","Tính kinh tế trong bảo dưỡng (保全の経済性): Việc lựa chọn giữa 事後保全 hay 予防保全 phải dựa trên tổng chi phí (chi phí sửa chữa + tổn thất do dừng máy), phương án nào có tổng chi phí thấp hơn sẽ được ưu tiên."],"exam_traps":["Nhầm 予防保全 với 保全予防.","Nhầm 事後保全 với 改良保全.","Đề chỉ cho một cặp đúng trong mỗi phương án, dễ bị đánh lừa bởi các cặp sai khác."],"vocabulary":[{"word":"設備保全","reading":"せつびほぜん","meaning":"bảo trì thiết bị"},{"word":"予防保全","reading":"よぼうほぜん","meaning":"bảo trì phòng ngừa"},{"word":"保全予防","reading":"ほぜんよぼう","meaning":"phòng ngừa bảo trì"},{"word":"事後保全","reading":"じごほぜん","meaning":"bảo trì sau sự cố"},{"word":"改良保全","reading":"かいりょうほぜん","meaning":"bảo trì cải tiến"},{"word":"体質改善","reading":"たいしつかいぜん","meaning":"cải thiện bản chất"},{"word":"設計段階","reading":"せっけいだんかい","meaning":"giai đoạn thiết kế"},{"word":"点検","reading":"てんけん","meaning":"kiểm tra"},{"word":"劣化部位","reading":"れっかぶい","meaning":"bộ phận xuống cấp"},{"word":"事前取替","reading":"じぜんとりかえ","meaning":"thay thế trước"},{"word":"経済的","reading":"けいざいてき","meaning":"mang tính kinh tế"},{"word":"種類","reading":"しゅるい","meaning":"loại"},{"word":"適用","reading":"てきよう","meaning":"áp dụng"},{"word":"定期","reading":"ていき","meaning":"định kỳ"},{"word":"事前","reading":"じぜん","meaning":"trước (khi xảy ra)"},{"word":"取替","reading":"とりかえ","meaning":"thay thế"},{"word":"修理","reading":"しゅうり","meaning":"sửa chữa"},{"word":"設計","reading":"せっけい","meaning":"thiết kế"},{"word":"不要","reading":"ふよう","meaning":"không cần"},{"word":"体質","reading":"たいしつ","meaning":"bản chất, thể chất"},{"word":"劣化","reading":"れっか","meaning":"xuống cấp, lão hóa"}]},{"id":"17","chapter":"8.設備管理","question":{"japanese":"設備総合効率の算出式に関する項目として最も不適切なものは、次のうちどれか。","vietnamese":"Trong các hạng mục liên quan đến công thức tính hiệu suất tổng hợp thiết bị, hạng mục nào KHÔNG phù hợp nhất?","furigana":"設備[せつび]総合[そうごう]効率[こうりつ]の算出式[さんしゅつしき]に関する[かんする]項目[こうもく]として最も[もっとも]不適切[ふてきせつ]なものは、次[つぎ]のうちどれか。"},"options":[{"key":"ア","japanese":"時間稼働率","vietnamese":"Tỷ lệ vận hành theo thời gian","furigana":"時間[じかん]稼働率[かどうりつ]"},{"key":"イ","japanese":"性能稼働率","vietnamese":"Tỷ lệ vận hành theo hiệu suất","furigana":"性能[せいのう]稼働率[かどうりつ]"},{"key":"ウ","japanese":"適合品率","vietnamese":"Tỷ lệ sản phẩm phù hợp","furigana":"適合品率[てきごうひんりつ]"},{"key":"エ","japanese":"生産率","vietnamese":"Tỷ lệ sản xuất","furigana":"生産率[せいさんりつ]"}],"correct_answer":"エ","explanation":{"correct_reason":"設備総合効率 (OEE) = 時間稼働率 × 性能稼働率 × 適合品率. 生産率 không phải là thành phần của công thức này.","incorrect_reasons":{"ア":"Sai vì 時間稼働率 là thành phần thứ nhất của OEE.","イ":"Sai vì 性能稼働率 là thành phần thứ hai của OEE.","ウ":"Sai vì 適合品率 là thành phần thứ ba của OEE.","エ":"Đây là đáp án đúng vì 生産率 không nằm trong công thức OEE."}},"key_knowledge":["Hiệu suất tổng hợp thiết bị (設備総合効率 - OEE) là chỉ số cốt lõi trong bảo trì năng suất toàn diện (TPM), dùng để đo lường mức độ khai thác thực tế của máy móc so với tiềm năng tối đa.","Công thức chuẩn xác của OEE là phép nhân của 3 yếu tố: 設備総合効率 = 時間稼働率 (Tỷ lệ vận hành thời gian) × 性能稼働率 (Tỷ lệ vận hành hiệu suất) × 適合品率 hoặc 良品率 (Tỷ lệ sản phẩm phù hợp/hàng tốt).","Tỷ lệ vận hành thời gian (時間稼働率) đo lường tổn thất do máy dừng (停止ロス), bao gồm sự cố hỏng hóc (故障) và thời gian chuẩn bị/chuyển đổi mã hàng (段取り・調整).","Tỷ lệ vận hành hiệu suất (性能稼働率) đo lường tổn thất về tốc độ và nhịp độ, bao gồm dừng vặt/chạy không tải (チョコ停・空転) và giảm tốc độ vận hành so với thiết kế (速度低下).","Tỷ lệ sản phẩm phù hợp (適合品率 / 良品率) đo lường tổn thất chất lượng (不良ロス), bao gồm phế phẩm gia công (不良・手直し) và hao hụt khi khởi động máy (立ち上がりロス).","Thuật ngữ 'Tỷ lệ sản xuất' (生産率) hoàn toàn không có trong công thức OEE chuẩn, đây là từ bẫy thí sinh do mang cảm giác quen thuộc trong quản lý sản xuất.","OEE gắn liền trực tiếp với việc loại bỏ '6 tổn thất lớn của thiết bị' (設備の6大ロス), mỗi thành phần trong OEE chịu trách nhiệm kiểm soát 2 tổn thất tương ứng.","Ví dụ thực tế: Một máy dập có 時間稼働率 90%, 性能稼働率 85%, 適合品率 98% thì OEE = 0.9 × 0.85 × 0.98 ≈ 74.97% (mức lý tưởng theo tiêu chuẩn thế giới thường là trên 85%)."],"exam_traps":["Thêm 生産率 vào công thức OEE.","Nhầm 性能稼働率 với 生産率.","Đảo thứ tự các thành phần."],"vocabulary":[{"word":"設備総合効率","reading":"せつびそうごうこうりつ","meaning":"hiệu suất tổng hợp thiết bị"},{"word":"算出式","reading":"さんしゅつしき","meaning":"công thức tính"},{"word":"項目","reading":"こうもく","meaning":"hạng mục"},{"word":"時間稼働率","reading":"じかんかどうりつ","meaning":"tỷ lệ vận hành theo thời gian"},{"word":"性能稼働率","reading":"せいのうかどうりつ","meaning":"tỷ lệ vận hành theo hiệu suất"},{"word":"適合品率","reading":"てきごうひんりつ","meaning":"tỷ lệ sản phẩm phù hợp"},{"word":"生産率","reading":"せいさんりつ","meaning":"tỷ lệ sản xuất"},{"word":"総合効率","reading":"そうごうこうりつ","meaning":"hiệu suất tổng hợp"},{"word":"稼働率","reading":"かどうりつ","meaning":"tỷ lệ vận hành"},{"word":"性能","reading":"せいのう","meaning":"hiệu năng"},{"word":"算出","reading":"さんしゅつ","meaning":"tính ra"},{"word":"式","reading":"しき","meaning":"công thức"},{"word":"積","reading":"せき","meaning":"tích (phép nhân)"},{"word":"OEE","reading":"オーイーイー","meaning":"OEE (hiệu suất tổng hợp thiết bị)"},{"word":"停止時間","reading":"ていしじかん","meaning":"thời gian dừng máy"},{"word":"段取り","reading":"だんどり","meaning":"chuẩn bị, thay đổi sản phẩm"},{"word":"不良","reading":"ふりょう","meaning":"hàng lỗi"},{"word":"速度低下","reading":"そくどていか","meaning":"giảm tốc độ"},{"word":"設備","reading":"せつび","meaning":"thiết bị"},{"word":"効率","reading":"こうりつ","meaning":"hiệu suất"}]},{"id":"18","chapter":"8.設備管理","question":{"japanese":"設備の劣化により生じる損失として最も不適切なものは、次のうちどれか。","vietnamese":"Trong các tổn thất phát sinh do thiết bị xuống cấp, tổn thất nào KHÔNG phù hợp nhất?","furigana":"設備[せつび]の劣化[れっか]により生じる[しょうじる]損失[そんしつ]として最も[もっとも]不適切[ふてきせつ]なものは、次[つぎ]のうちどれか。"},"options":[{"key":"ア","japanese":"安全性が低下する。","vietnamese":"Độ an toàn giảm.","furigana":"安全性[あんぜんせい]が低下[ていか]する。"},{"key":"イ","japanese":"製造コストが低下する。","vietnamese":"Chi phí sản xuất giảm.","furigana":"製造[せいぞう]コストが低下[ていか]する。"},{"key":"ウ","japanese":"企業の信頼が低下する。","vietnamese":"Niềm tin của doanh nghiệp giảm.","furigana":"企業[きぎょう]の信頼[しんらい]が低下[ていか]する。"},{"key":"エ","japanese":"生産量が低下する。","vietnamese":"Sản lượng giảm.","furigana":"生産量[せいさんりょう]が低下[ていか]する。"}],"correct_answer":"イ","explanation":{"correct_reason":"Thiết bị xuống cấp thường làm tăng chi phí sửa chữa, chi phí năng lượng, chi phí lỗi và chi phí dừng máy, không làm giảm 製造コスト. Vì vậy イ không phù hợp.","incorrect_reasons":{"ア":"Sai vì xuống cấp làm giảm độ an toàn, đây là tổn thất thực tế.","イ":"Đây là đáp án đúng vì chi phí sản xuất thường tăng, không giảm.","ウ":"Sai vì chất lượng và giao hàng kém có thể làm giảm niềm tin.","エ":"Sai vì dừng máy và hiệu suất giảm làm sản lượng giảm."}},"key_knowledge":["Xuống cấp của thiết bị (設備の劣化) là hiện tượng máy móc bị suy giảm về tính năng, độ chính xác hoặc cấu trúc vật lý do tác động của ma sát, mài mòn, nhiệt độ hoặc thời gian vận hành.","Phân loại xuống cấp thiết bị gồm hai dạng chính: Xuống cấp tự nhiên (自然劣化 - diễn ra tất yếu do hao mòn theo thời gian) và Xuống cấp cưỡng bức (強制劣化 - do con người không tra dầu mỡ, không vệ sinh hoặc vận hành sai thông số).","Tác động đến chi phí: Thiết bị xuống cấp làm tiêu hao nhiều điện năng hơn, sinh ra nhiều phế phẩm và phát sinh chi phí phụ tùng thay thế, khiến chi phí sản xuất (製造コスト) luôn luôn tăng lên chứ không thể giảm.","Tác động đến sản lượng và tiến độ: Máy móc hoạt động chập chờn dẫn đến dừng máy do sự cố (故障停止) và ngừng tạm thời (チョコ停), làm giảm hiệu suất vận hành và hụt sản lượng (生産量低下), gây trễ hạn giao hàng (納期遅延).","Tác động đến chất lượng: Độ rơ lỏng cơ khí hoặc cảm biến sai lệch tạo ra nhiều sản phẩm lỗi trong công đoạn (工程不良), làm tăng tỷ lệ tái chế và tỷ lệ phế phẩm.","Tác động đến an toàn lao động: Thiết bị mất kiểm soát, quá nhiệt hoặc rò rỉ nhiên liệu/điện dễ dẫn đến tai nạn lao động nghiêm trọng, làm suy giảm an toàn (安全性低下) tại nơi làm việc.","Tác động đến uy tín doanh nghiệp (企業の信頼): Việc giao hàng trễ hẹn cùng chất lượng sản phẩm không đồng đều sẽ trực tiếp phá hủy niềm tin của khách hàng đối với công ty.","Biện pháp phòng ngừa: Nhà máy áp dụng bảo trì dự phòng (予防保全) theo định kỳ và hoạt động bảo trì tự quản (自主保全) của công nhân nhằm phục hồi hiện trạng thiết bị trước khi xảy ra tổn thất."],"exam_traps":["Đảo chiều tác động: nói chi phí giảm thay vì tăng.","Nhầm tổn thất hữu hình với vô hình.","Câu hỏi 最も不適切 chọn phương án sai."],"vocabulary":[{"word":"設備の劣化","reading":"せつびのれっか","meaning":"thiết bị xuống cấp"},{"word":"損失","reading":"そんしつ","meaning":"tổn thất"},{"word":"安全性","reading":"あんぜんせい","meaning":"độ an toàn"},{"word":"製造コスト","reading":"せいぞうコスト","meaning":"chi phí sản xuất"},{"word":"企業の信頼","reading":"きぎょうのしんらい","meaning":"niềm tin của doanh nghiệp"},{"word":"生産量","reading":"せいさんりょう","meaning":"sản lượng"},{"word":"劣化","reading":"れっか","meaning":"xuống cấp"},{"word":"低下","reading":"ていか","meaning":"giảm, hạ"},{"word":"信頼","reading":"しんらい","meaning":"niềm tin, sự tín nhiệm"},{"word":"生じる","reading":"しょうじる","meaning":"phát sinh"},{"word":"不安定","reading":"ふあんてい","meaning":"không ổn định"},{"word":"品質","reading":"ひんしつ","meaning":"chất lượng"},{"word":"納期","reading":"のうき","meaning":"thời hạn giao hàng"},{"word":"増加","reading":"ぞうか","meaning":"tăng lên"},{"word":"部品交換","reading":"ぶひんこうかん","meaning":"thay linh kiện"},{"word":"重大","reading":"じゅうだい","meaning":"nghiêm trọng"},{"word":"故障率","reading":"こしょうりつ","meaning":"tỷ lệ hư hỏng"},{"word":"修理費","reading":"しゅうりひ","meaning":"chi phí sửa chữa"},{"word":"停止","reading":"ていし","meaning":"dừng lại"},{"word":"安全","reading":"あんぜん","meaning":"an toàn"}]},{"id":"19","chapter":"8.設備管理","question":{"japanese":"設備保全システムや設備保全の実施に関する記述として最も不適切なものは、次のうちどれか。","vietnamese":"Trong các mô tả về hệ thống bảo trì thiết bị và thực hiện bảo trì, mô tả nào KHÔNG phù hợp nhất?","furigana":"設備[せつび]保全[ほぜん]システムや設備[せつび]保全[ほぜん]の実施[じっし]に関する[かんする]記述[きじゅつ]として最も[もっとも]不適切[ふてきせつ]なものは、次[つぎ]のうちどれか。"},"options":[{"key":"ア","japanese":"保全活動では、重点設備や重点箇所を選定して保全を実施する。","vietnamese":"Trong hoạt động bảo trì, cần chọn thiết bị trọng điểm và vị trí trọng điểm để thực hiện bảo trì.","furigana":"保全[ほぜん]活動[かつどう]では、重点[じゅうてん]設備[せつび]や重点[じゅうてん]箇所[かしょ]を選定[せんてい]して保全[ほぜん]を実施[じっし]する。"},{"key":"イ","japanese":"設備の整備活動では、定期点検基準表を作成し、それに基づいた保全を実施する。","vietnamese":"Trong hoạt động bảo dưỡng thiết bị, lập bảng tiêu chuẩn kiểm tra định kỳ và thực hiện bảo trì dựa trên đó.","furigana":"設備[せつび]の整備[せいび]活動[かつどう]では、定期[ていき]点検[てんけん]基準[きじゅん]表[ひょう]を作成[さくせい]し、それに基づい[もとづい]た保全[ほぜん]を実施[じっし]する。"},{"key":"ウ","japanese":"設備保全の点検や検査の結果は、1ヵ月に1度、まとめて記録する。","vietnamese":"Kết quả kiểm tra, kiểm định bảo trì thiết bị được ghi chép tổng hợp mỗi tháng một lần.","furigana":"設備[せつび]保全[ほぜん]の点検[てんけん]や検査[けんさ]の結果[けっか]は、1ヵ月[かげつ]に1度[ど]、まとめて記録[きろく]する。"},{"key":"エ","japanese":"保全効果の評価項目の1つには、故障度数率がある。","vietnamese":"Một trong các hạng mục đánh giá hiệu quả bảo trì là tần suất hư hỏng.","furigana":"保全[ほぜん]効果[こうか]の評価[ひょうか]項目[こうもく]の1つには、故障[こしょう]度数率[どすうりつ]がある。"}],"correct_answer":"ウ","explanation":{"correct_reason":"Kết quả kiểm tra, kiểm định phải được ghi chép kịp thời ngay khi thực hiện, không chờ đến một tháng mới ghi tổng hợp. Ghi chép muộn làm mất thông tin và không phát hiện được bất thường sớm.","incorrect_reasons":{"ア":"Sai vì chọn trọng điểm để bảo trì là cách làm đúng.","イ":"Sai vì lập bảng tiêu chuẩn kiểm tra định kỳ và bảo trì theo đó là đúng.","ウ":"Đây là đáp án đúng vì ghi chép phải thực hiện kịp thời, không gom mỗi tháng.","エ":"Sai vì 故障度数率 là chỉ số đánh giá hiệu quả bảo trì hợp lệ."}},"key_knowledge":["Nguyên tắc ghi chép bảo trì (保全記録の原則): Kết quả kiểm tra, kiểm định thiết bị phải được ghi lại ngay lập tức tại thời điểm thực hiện (その都度記録), tuyệt đối không để dồn định kỳ theo tháng nhằm tránh quên sót và giúp phát hiện xử lý bất thường kịp thời.","Lựa chọn thiết bị trọng điểm (重点設備・重点箇所の選定): Nguồn lực bảo trì có hạn nên doanh nghiệp phải phân loại thiết bị (thường dùng phân tích ABC) để ưu tiên máy móc ảnh hưởng sống còn đến an toàn, chất lượng, và tiến độ giao hàng (dây chuyền nút thắt cổ chai - ボトルネック).","Bảng tiêu chuẩn kiểm tra định kỳ (定期点検基準表): Là tài liệu quy định rõ 5 yếu tố cốt lõi gồm vị trí kiểm tra (点検箇所), chu kỳ (周期), phương pháp đo/nhìn (点検方法), tiêu chuẩn đánh giá đạt/không đạt (判定基準), và biện pháp xử lý khi có bất thường.","Tần suất hư hỏng (故障度数率 - Failure frequency rate): Là chỉ số đo lường số lần dừng máy do hư hỏng trên một đơn vị thời gian vận hành (thường tính trên 1 triệu giờ vận hành), thể hiện độ tin cậy và sự ổn định của thiết bị.","Cường độ hư hỏng (故障強度率 - Failure severity rate): Phân biệt với tần suất hư hỏng, cường độ hư hỏng đo lường tổng thời gian dừng máy do hư hỏng trên tổng thời gian vận hành, phản ánh mức độ nghiêm trọng và khả năng khắc phục sự cố nhanh hay chậm.","Chỉ số MTBF và MTTR: Hiệu quả bảo trì còn được đo lường qua MTBF (平均故障間隔 - Thời gian trung bình giữa các lần hỏng, càng dài càng tốt) và MTTR (平均修復時間 - Thời gian trung bình để sửa chữa, càng ngắn càng tốt).","Bảo trì định kỳ dựa trên thời gian (TBM - Time Based Maintenance) và theo tình trạng (CBM - Condition Based Maintenance): TBM kiểm tra/thay thế linh kiện theo khoảng thời gian cố định, trong khi CBM giám sát độ rung, nhiệt độ để chỉ bảo trì khi có dấu hiệu xuống cấp.","Bảo trì tự quản (自主保全): Hoạt động do chính công nhân vận hành máy thực hiện hàng ngày (vệ sinh, tra dầu mỡ, siết chặt ốc vít, kiểm tra trực quan), là nền tảng bổ trợ cho bảo trì chuyên trách (専門保全) của đội ngũ kỹ thuật."],"exam_traps":["Nói ghi chép gom mỗi tháng thay vì ghi ngay.","Nhầm 故障度数率 với chỉ số khác.","Đánh tráo vai trò của 定期点検基準表."],"vocabulary":[{"word":"設備保全システム","reading":"せつびほぜんシステム","meaning":"hệ thống bảo trì thiết bị"},{"word":"重点設備","reading":"じゅうてんせつび","meaning":"thiết bị trọng điểm"},{"word":"重点箇所","reading":"じゅうてんかしょ","meaning":"vị trí trọng điểm"},{"word":"整備活動","reading":"せいびかつどう","meaning":"hoạt động bảo dưỡng"},{"word":"定期点検基準表","reading":"ていきてんけんきじゅんひょう","meaning":"bảng tiêu chuẩn kiểm tra định kỳ"},{"word":"点検","reading":"てんけん","meaning":"kiểm tra"},{"word":"検査","reading":"けんさ","meaning":"kiểm định"},{"word":"記録","reading":"きろく","meaning":"ghi chép"},{"word":"保全効果","reading":"ほぜんこうか","meaning":"hiệu quả bảo trì"},{"word":"故障度数率","reading":"こしょうどすうりつ","meaning":"tần suất hư hỏng"},{"word":"点検基準","reading":"てんけんきじゅん","meaning":"tiêu chuẩn kiểm tra"},{"word":"基準表","reading":"きじゅんひょう","meaning":"bảng tiêu chuẩn"},{"word":"選定","reading":"せんてい","meaning":"chọn lựa"},{"word":"重点","reading":"じゅうてん","meaning":"trọng điểm"},{"word":"評価","reading":"ひょうか","meaning":"đánh giá"},{"word":"度","reading":"ど","meaning":"mức độ, tần số"},{"word":"発生","reading":"はっせい","meaning":"phát sinh"},{"word":"早期","reading":"そうき","meaning":"sớm"},{"word":"発見","reading":"はっけん","meaning":"phát hiện"}]},{"id":"20","chapter":"9.資材・在庫管理","question":{"japanese":"外注に関する記述として最も不適切なものは、次のうちどれか。","vietnamese":"Trong các mô tả về gia công ngoài (外注), mô tả nào KHÔNG phù hợp nhất?","furigana":"外注[がいちゅう]に関する[かんする]記述[きじゅつ]として最も[もっとも]不適切[ふてきせつ]なものは、次[つぎ]のうちどれか。"},"options":[{"key":"ア","japanese":"外注は、自社の業務の一部を他社に委託することである。","vietnamese":"Gia công ngoài là việc ủy thác một phần công việc của công ty cho công ty khác.","furigana":"外注[がいちゅう]は、自社[じしゃ]の業務[ぎょうむ]の一部[いちぶ]を他社[たしゃ]に委託[いたく]することである。"},{"key":"イ","japanese":"外注するためには、外注する目的を明確にし、要求する品質・価格・納期を満足するための管理活動が必要となる。","vietnamese":"Để gia công ngoài, cần làm rõ mục đích và có hoạt động quản lý để thỏa mãn chất lượng, giá cả, thời hạn giao hàng yêu cầu.","furigana":"外注[がいちゅう]するためには、外注[がいちゅう]する目的[もくてき]を明確[めいかく]にし、要求[ようきゅう]する品質[ひんしつ]・価格[かかく]・納期[のうき]を満足[まんぞく]するための管理[かんり]活動[かつどう]が必要[ひつよう]となる。"},{"key":"ウ","japanese":"外注の形態としては、発注企業の設計仕様により外注先に製造を委託する場合が多い。","vietnamese":"Hình thức gia công ngoài thường là bên đặt hàng ủy thác sản xuất theo thiết kế của mình.","furigana":"外注[がいちゅう]の形態[けいたい]としては、発注[はっちゅう]企業[きぎょう]の設計[せっけい]仕様[しよう]により外注[がいちゅう]先[さき]に製造[せいぞう]を委託[いたく]する場合[ばあい]が多い[おおい]。"},{"key":"エ","japanese":"外注は、外部との連携からサプライチェーンとも呼ばれる。","vietnamese":"Gia công ngoài, do liên kết với bên ngoài, còn được gọi là chuỗi cung ứng.","furigana":"外注[がいちゅう]は、外部[がいぶ]との連携[れんけい]からサプライチェーンとも呼ば[よば]れる。"}],"correct_answer":"エ","explanation":{"correct_reason":"外注 là gia công ngoài, không đồng nghĩa với サプライチェーン. Chuỗi cung ứng là khái niệm rộng hơn, bao gồm toàn bộ mạng lưới từ nguyên liệu, sản xuất, phân phối đến khách hàng.","incorrect_reasons":{"ア":"Sai vì ủy thác một phần công việc cho bên ngoài là định nghĩa đúng của 外注.","イ":"Sai vì quản lý chất lượng, giá, giao hàng khi gia công ngoài là cần thiết.","ウ":"Sai vì gia công theo thiết kế của bên đặt hàng là hình thức phổ biến.","エ":"Đây là đáp án đúng vì 外注 không phải là サプライチェーン."}},"key_knowledge":["Khái niệm gia công ngoài (外注 - Gaichū): Là việc doanh nghiệp ủy thác một phần hoặc toàn bộ công đoạn chế tạo, gia công chi tiết cho đơn vị bên ngoài thực hiện theo hợp đồng.","Phân định tự làm hay thuê ngoài (内外製区分): Doanh nghiệp căn cứ vào năng lực máy móc, bí mật công nghệ (ノウハウ), thời hạn giao hàng và bài toán so sánh chi phí (コスト比較) để quyết định tự sản xuất (内作) hay thuê ngoài.","Mục tiêu quản lý gia công ngoài (外注管理): Trọng tâm là kiểm soát chặt chẽ 3 yếu tố QCD gồm chất lượng sản phẩm (品質), chi phí tối ưu (価格/コスト) và thời hạn giao hàng nghiêm ngặt (納期).","Hình thức gia công chủ yếu: Thường là gia công chế tạo theo đúng bản vẽ thiết kế (図面) hoặc thông số kỹ thuật (仕様) do chính bên đặt hàng cung cấp.","Phân biệt với mua hàng thông thường (購買): Mua hàng (購買) thường mua các linh kiện, chi tiết tiêu chuẩn bán sẵn trên thị trường, trong khi gia công ngoài (外注) là đặt chế tạo riêng theo yêu cầu cụ thể.","Phân biệt với chuỗi cung ứng (サプライチェーン): Chuỗi cung ứng là toàn bộ mạng lưới dòng chảy vật chất và thông tin từ khai thác nguyên liệu thô, sản xuất, phân phối đến tay người tiêu dùng cuối cùng; 外注 chỉ là một mắt xích nhỏ bên trong.","Ưu điểm của gia công ngoài: Giúp doanh nghiệp nhanh chóng giải quyết tình trạng thiếu hụt công suất trong thời kỳ cao điểm (繁忙期) và tận dụng được máy móc chuyên dụng, công nghệ cao của đối tác mà không cần tự đầu tư.","Rủi ro cần phòng tránh khi gia công ngoài: Nguy cơ rò rỉ bí quyết công nghệ sản xuất độc quyền, khó kiểm soát chất lượng triệt để tại hiện trường và nguy cơ trễ tiến độ dẫn đến đình trệ chuyền lắp ráp chính."],"exam_traps":["Đồng nhất 外注 với サプライチェーン.","Thu hẹp chuỗi cung ứng thành gia công ngoài.","Nhầm 外注 với 購買 (mua hàng)."],"vocabulary":[{"word":"外注","reading":"がいちゅう","meaning":"gia công ngoài"},{"word":"委託","reading":"いたく","meaning":"ủy thác"},{"word":"目的","reading":"もくてき","meaning":"mục đích"},{"word":"品質","reading":"ひんしつ","meaning":"chất lượng"},{"word":"価格","reading":"かかく","meaning":"giá cả"},{"word":"納期","reading":"のうき","meaning":"thời hạn giao hàng"},{"word":"発注企業","reading":"はっちゅうきぎょう","meaning":"doanh nghiệp đặt hàng"},{"word":"設計仕様","reading":"せっけいしよう","meaning":"thông số thiết kế"},{"word":"製造","reading":"せいぞう","meaning":"sản xuất"},{"word":"外部","reading":"がいぶ","meaning":"bên ngoài"},{"word":"連携","reading":"れんけい","meaning":"liên kết"},{"word":"サプライチェーン","reading":"サプライチェーン","meaning":"chuỗi cung ứng"},{"word":"自社","reading":"じしゃ","meaning":"công ty mình"},{"word":"他社","reading":"たしゃ","meaning":"công ty khác"},{"word":"一部","reading":"いちぶ","meaning":"một phần"},{"word":"形態","reading":"けいたい","meaning":"hình thức"},{"word":"仕様","reading":"しよう","meaning":"thông số kỹ thuật"},{"word":"要求","reading":"ようきゅう","meaning":"yêu cầu"},{"word":"満足","reading":"まんぞく","meaning":"thỏa mãn"},{"word":"購買","reading":"こうばい","meaning":"mua hàng"},{"word":"取引先","reading":"とりひきさき","meaning":"đối tác giao dịch"}]},{"id":"21","chapter":"9.資材・在庫管理","question":{"japanese":"発注企業が外注先に、資材・金型・治工具・製造設備・試験設備などを支給又は貸与する目的のうち優先度が高い項目として最も不適切なものは、次のうちどれか。","vietnamese":"Trong các mục đích ưu tiên cao khi doanh nghiệp đặt hàng cấp phát hoặc cho mượn vật tư, khuôn, dụng cụ, thiết bị sản xuất, thiết bị thử nghiệm cho nhà gia công, mục đích nào KHÔNG phù hợp nhất?","furigana":"発注[はっちゅう]企業[きぎょう]が外注[がいちゅう]先[さき]に、資材[しざい]・金[きん]型[がた]・治[ち]工具[こうぐ]・製造[せいぞう]設備[せつび]・試験[しけん]設備[せつび]などを支給[しきゅう]又は[または]貸与[たいよ]する目的[もくてき]のうち優先度[ゆうせんど]が高い[たかい]項目[こうもく]として最も[もっとも]不適切[ふてきせつ]なものは、次[つぎ]のうちどれか。"},"options":[{"key":"ア","japanese":"品質の維持","vietnamese":"Duy trì chất lượng","furigana":"品質[ひんしつ]の維持[いじ]"},{"key":"イ","japanese":"資産の圧縮","vietnamese":"Nén tài sản, giảm tài sản","furigana":"資産[しさん]の圧縮[あっしゅく]"},{"key":"ウ","japanese":"コストの引き下げ","vietnamese":"Hạ chi phí","furigana":"コストの引き下げ[ひきさげ]"},{"key":"エ","japanese":"納期遅延の防止","vietnamese":"Phòng ngừa chậm giao hàng","furigana":"納期[のうき]遅延[ちえん]の防止[ぼうし]"}],"correct_answer":"イ","explanation":{"correct_reason":"Cấp phát/cho mượn vật tư, khuôn, dụng cụ, thiết bị nhằm duy trì chất lượng, giảm chi phí và tránh chậm giao hàng. 資産の圧縮 (giảm tài sản) không phải mục đích ưu tiên, vì việc cấp phát thiết bị thường làm tăng gánh nặng tài sản của bên đặt hàng.","incorrect_reasons":{"ア":"Sai vì duy trì chất lượng là mục đích ưu tiên cao.","イ":"Đây là đáp án đúng vì 資産の圧縮 không phải mục đích chính, thậm chí ngược lại.","ウ":"Sai vì giảm chi phí là mục đích hợp lệ.","エ":"Sai vì tránh chậm giao hàng là mục đích hợp lệ."}},"key_knowledge":["Khái niệm cấp phát và cho mượn (支給・貸与): Doanh nghiệp đặt hàng (発注企業) cung cấp nguyên vật liệu (資材), khuôn mẫu (金型), đồ gá (治工具), thiết bị sản xuất hoặc kiểm tra cho đối tác gia công (外注先) nhằm đảm bảo quá trình gia công diễn ra đúng chuẩn.","Mục đích duy trì chất lượng (品質の維持): Giúp linh kiện gia công bên ngoài đạt chuẩn chất lượng đồng nhất như sản xuất nội bộ, nhờ sử dụng đúng vật liệu chỉ định và thiết bị/đồ gá chuyên dùng do công ty mẹ kiểm soát.","Mục đích hạ chi phí (コストの引き下げ): Công ty mẹ mua nguyên vật liệu số lượng lớn (集中購買) sẽ có đơn giá rẻ hơn để cấp phát cho đối tác, hoặc cho mượn sẵn khuôn/máy móc đắt tiền để đối tác không tính chi phí khấu hao đầu tư vào đơn giá gia công.","Mục đích chống chậm tiến độ (納期遅延の防止): Cấp phát sẵn vật tư khó tìm hoặc khuôn gá chuyên dụng giúp xưởng gia công bắt tay vào làm ngay mà không mất thời gian chờ tự tìm nguồn cung ứng, giảm rủi ro đứt gãy tiến độ giao hàng.","Phân loại cấp phát nguyên vật liệu (支給): Gồm cấp phát có thu tiền (有償支給 - bán vật tư cho đối tác rồi khấu trừ khi mua lại thành phẩm) và cấp phát miễn phí (無償支給 - giao vật tư không thu tiền, đối tác chỉ tính tiền công gia công).","Bản chất của việc cho mượn thiết bị/khuôn (貸与): Tài sản cho mượn vẫn thuộc quyền sở hữu của bên đặt hàng, nằm trên bảng cân đối kế toán của bên đặt hàng, do đó không thể coi là hành vi giảm/nén tài sản.","Phân biệt với nén tài sản (資産の圧縮): Giảm tài sản chỉ đạt được khi doanh nghiệp chuyển sang hình thức thuê ngoài trọn gói (đối tác tự đầu tư máy móc, tự mua vật tư) hoặc thuê tài sản (リーシング), chứ không phải tự mua rồi cấp phát/cho mượn."],"exam_traps":["Đưa mục đích tài chính không liên quan vào.","Nhầm 資産の圧縮 với コストの引き下げ.","Câu hỏi 最も不適切 chọn mục đích sai."],"vocabulary":[{"word":"発注企業","reading":"はっちゅうきぎょう","meaning":"doanh nghiệp đặt hàng"},{"word":"外注先","reading":"がいちゅうさき","meaning":"nhà gia công"},{"word":"資材","reading":"しざい","meaning":"vật tư"},{"word":"金型","reading":"かながた","meaning":"khuôn"},{"word":"治工具","reading":"じこうぐ","meaning":"dụng cụ gá, jig"},{"word":"製造設備","reading":"せいぞうせつび","meaning":"thiết bị sản xuất"},{"word":"試験設備","reading":"しけんせつび","meaning":"thiết bị thử nghiệm"},{"word":"支給","reading":"しきゅう","meaning":"cấp phát"},{"word":"貸与","reading":"たいよ","meaning":"cho mượn"},{"word":"優先度","reading":"ゆうせんど","meaning":"mức ưu tiên"},{"word":"品質の維持","reading":"ひんしつのいじ","meaning":"duy trì chất lượng"},{"word":"資産の圧縮","reading":"しさんのあっしゅく","meaning":"giảm tài sản"},{"word":"コストの引き下げ","reading":"コストのひきさげ","meaning":"hạ chi phí"},{"word":"納期遅延","reading":"のうきちえん","meaning":"chậm giao hàng"},{"word":"圧縮","reading":"あっしゅく","meaning":"nén, giảm bớt"},{"word":"引き下げ","reading":"ひきさげ","meaning":"hạ xuống"},{"word":"遅延","reading":"ちえん","meaning":"chậm trễ"},{"word":"防止","reading":"ぼうし","meaning":"phòng ngừa"},{"word":"目的","reading":"もくてき","meaning":"mục đích"},{"word":"優先順位","reading":"ゆうせんじゅんい","meaning":"thứ tự ưu tiên"}]},{"id":"22","chapter":"9.資材・在庫管理","question":{"japanese":"棚卸に関する記述として最も不適切なものは、次のうちどれか。","vietnamese":"Trong các mô tả về kiểm kê hàng tồn, mô tả nào KHÔNG phù hợp nhất?","furigana":"棚卸[たなおろし]に関する[かんする]記述[きじゅつ]として最も[もっとも]不適切[ふてきせつ]なものは、次[つぎ]のうちどれか。"},"options":[{"key":"ア","japanese":"棚卸の目的の1つには、現品数と帳簿上の数量との照合がある。","vietnamese":"Một mục đích của kiểm kê là đối chiếu số lượng thực tế với số lượng trên sổ sách.","furigana":"棚卸[たなおろし]の目的[もくてき]の1つには、現品数[げんぴんすう]と帳簿上[ちょうぼじょう]の数量[すうりょう]との照合[しょうごう]がある。"},{"key":"イ","japanese":"定期棚卸は、入出庫作業中に現品数と帳簿上の数量に相当数の差異が発見された場合に行われる。","vietnamese":"Kiểm kê định kỳ được thực hiện khi phát hiện nhiều chênh lệch giữa số lượng thực tế và sổ sách trong quá trình nhập xuất kho.","furigana":"定期[ていき]棚卸[たなおろし]は、入[にゅう]出庫[しゅっこ]作業中[さぎょうちゅう]に現品数[げんぴんすう]と帳簿上[ちょうぼじょう]の数量[すうりょう]に相当数[そうとうすう]の差異[さい]が発見[はっけん]された場合[ばあい]に行わ[おこなわ]れる。"},{"key":"ウ","japanese":"在庫把握の精度の高い棚卸方法として、常時棚卸がある。","vietnamese":"Một phương pháp kiểm kê có độ chính xác nắm bắt tồn kho cao là kiểm kê thường xuyên.","furigana":"在庫[ざいこ]把握[はあく]の精度[せいど]の高い[たかい]棚卸[たなおろし]方法[ほうほう]として、常時[じょうじ]棚卸[たなおろし]がある。"},{"key":"エ","japanese":"棚卸資産の一般的な評価方法として、先入先出法や移動平均法がある。","vietnamese":"Các phương pháp đánh giá hàng tồn phổ biến gồm FIFO và bình quân gia quyền di động.","furigana":"棚卸[たなおろし]資産[しさん]の一般的[いっぱんてき]な評価[ひょうか]方法[ほうほう]として、先入先出法[さきいれさきだしほう]や移動[いどう]平均法[へいきんほう]がある。"}],"correct_answer":"イ","explanation":{"correct_reason":"Đề hỏi mô tả KHÔNG phù hợp. 定期棚卸 là kiểm kê định kỳ theo lịch (tháng, quý, năm), không phải kiểm kê đột xuất khi phát hiện chênh lệch. Kiểm kê khi có chênh lệch lớn là 臨時棚卸/随時棚卸.","incorrect_reasons":{"ア":"Sai vì đối chiếu thực tế với sổ sách là mục đích đúng.","イ":"Đây là đáp án đúng vì mô tả 定期棚卸 sai bản chất.","ウ":"Sai vì 常時棚卸 là phương pháp kiểm kê thường xuyên, độ chính xác cao.","エ":"Sai vì 先入先出法 và 移動平均法 là phương pháp đánh giá tồn kho phổ biến."}},"key_knowledge":["Kiểm kê hàng tồn (棚卸) là hoạt động đếm và xác nhận số lượng thực tế trong kho để đối chiếu với số dư trên sổ sách (帳簿残高), nhằm phát hiện sai lệch, hư hỏng và tính toán giá trị tài sản chính xác.","Kiểm kê định kỳ (定期棚卸) được thực hiện theo kế hoạch cố định vào các mốc thời gian quy định sẵn (như cuối tháng, cuối quý, cuối kỳ kế toán), thường phải dừng hoạt động nhập xuất kho để kiểm đếm đồng loạt.","Kiểm kê đột xuất (臨時棚卸 / 随時棚卸) chỉ diễn ra khi phát sinh tình huống bất thường, ví dụ như phát hiện chênh lệch lớn giữa thực tế và sổ sách trong quá trình làm việc, hoặc khi xảy ra sự cố mất mát, tai nạn.","Kiểm kê thường xuyên (常時棚卸) hay kiểm kê luân phiên (循環棚卸) là phương pháp chia nhỏ từng khu vực/chủng loại hàng để kiểm đếm liên tục hàng ngày mà không cần dừng kho, giúp độ chính xác quản lý tồn kho rất cao.","Cần phân biệt rõ kiểm kê trên sổ sách (帳簿棚卸 - chỉ tính toán dựa trên phiếu nhập xuất) và kiểm kê thực địa (実地棚卸 - trực tiếp đếm tận mắt tại hiện trường); độ chênh lệch giữa hai giá trị này gọi là chênh lệch kiểm kê (棚卸差異).","Phương pháp đánh giá tài sản tồn kho (棚卸資産の評価方法) phổ biến gồm có phương pháp Nhập trước - Xuất trước (先入先出法 - FIFO) và phương pháp Bình quân gia quyền di động (移動平均法).","Trong nhà máy sản xuất, mục tiêu cốt lõi của kiểm kê là ngăn ngừa rủi ro dừng chuyền do thiếu nguyên vật liệu ảo (欠品) và loại bỏ chi phí tồn trữ do phế phẩm hoặc hàng ứ đọng lâu ngày (不動在庫)."],"exam_traps":["Gán mục đích kiểm kê đột xuất cho 定期棚卸.","Nhầm 常時棚卸 với 定期棚卸.","Đánh tráo phương pháp đánh giá tồn kho."],"vocabulary":[{"word":"棚卸","reading":"たなおろし","meaning":"kiểm kê hàng tồn"},{"word":"現品数","reading":"げんぴんすう","meaning":"số lượng thực tế"},{"word":"帳簿上","reading":"ちょうぼじょう","meaning":"trên sổ sách"},{"word":"照合","reading":"しょうごう","meaning":"đối chiếu"},{"word":"定期棚卸","reading":"ていきたなおろし","meaning":"kiểm kê định kỳ"},{"word":"入出庫作業","reading":"にゅうしゅっこさぎょう","meaning":"công việc nhập xuất kho"},{"word":"差異","reading":"さい","meaning":"chênh lệch"},{"word":"常時棚卸","reading":"じょうじたなおろし","meaning":"kiểm kê thường xuyên"},{"word":"棚卸資産","reading":"たなおろししさん","meaning":"hàng tồn kho"},{"word":"評価方法","reading":"ひょうかほうほう","meaning":"phương pháp đánh giá"},{"word":"先入先出法","reading":"さきいれさきだしほう","meaning":"phương pháp FIFO"},{"word":"移動平均法","reading":"いどうへいきんほう","meaning":"phương pháp bình quân gia quyền di động"},{"word":"現品","reading":"げんぴん","meaning":"hàng thực tế"},{"word":"帳簿","reading":"ちょうぼ","meaning":"sổ sách"},{"word":"定期","reading":"ていき","meaning":"định kỳ"},{"word":"相当数","reading":"そうとうすう","meaning":"số lượng đáng kể"},{"word":"入出庫","reading":"にゅうしゅっこ","meaning":"nhập xuất kho"},{"word":"資産","reading":"しさん","meaning":"tài sản"},{"word":"常時","reading":"じょうじ","meaning":"thường xuyên"},{"word":"精度","reading":"せいど","meaning":"độ chính xác"}]},{"id":"23","chapter":"10.運搬・物流管理","question":{"japanese":"物流コストの管理上の分類とそれに含まれる費目の組合せとして最も不適切なものは、次のうちどれか。","vietnamese":"Tổ hợp nào KHÔNG phù hợp nhất giữa phân loại quản lý chi phí logistics và khoản mục chi phí thuộc phân loại đó?","furigana":"物流[ぶつりゅう]コストの管理上[かんりじょう]の分類[ぶんるい]とそれに含ま[ふくま]れる費目[ひもく]の組合せ[くみあわせ]として最も[もっとも]不適切[ふてきせつ]なものは、次[つぎ]のうちどれか。"},"options":[{"key":"ア","japanese":"変動固定別分類：固定物流費","vietnamese":"Phân loại theo biến phí/cố định: chi phí logistics cố định","furigana":"変動[へんどう]固定別[こていべつ]分類[ぶんるい]：固定[こてい]物流費[ぶつりゅうひ]"},{"key":"イ","japanese":"機能別分類：包装費","vietnamese":"Phân loại theo chức năng: chi phí đóng gói","furigana":"機能別[きのうべつ]分類[ぶんるい]：包装費[ほうそうひ]"},{"key":"ウ","japanese":"主体別分類：自家物流費","vietnamese":"Phân loại theo chủ thể: chi phí logistics tự thực hiện","furigana":"主体別[しゅたいべつ]分類[ぶんるい]：自家[じか]物流費[ぶつりゅうひ]"},{"key":"エ","japanese":"領域別分類：情報処理費","vietnamese":"Phân loại theo lĩnh vực: chi phí xử lý thông tin","furigana":"領域別[りょういきべつ]分類[ぶんるい]：情報処理費[じょうほうしょりひ]"}],"correct_answer":"エ","explanation":{"correct_reason":"Phân loại theo lĩnh vực (領域別) thường gồm chi phí vận chuyển, bảo quản, đóng gói, bốc xếp, quản lý. 情報処理費 thuộc phân loại theo chức năng hoặc theo nội dung chi phí, không thuộc 領域別. Vì vậy エ không phù hợp.","incorrect_reasons":{"ア":"Sai vì 固定物流費 thuộc phân loại biến phí/cố định là đúng.","イ":"Sai vì 包装費 thuộc phân loại theo chức năng là đúng.","ウ":"Sai vì 自家物流費 thuộc phân loại theo chủ thể là đúng.","エ":"Đây là đáp án đúng vì 情報処理費 không thuộc 領域別分類."}},"key_knowledge":["4 trục phân loại chi phí logistics cơ bản theo chuẩn JILS: Phân loại theo chủ thể/hình thức chi trả (主体別・支払形態別), theo chức năng (機能別), theo phạm vi/lĩnh vực (領域別), và theo tính chất biến đổi (変動固定別).","Phân loại theo chức năng (機能別分類): Dựa trên nghiệp vụ logistics thực hiện, bao gồm 6 khoản mục chính: chi phí vận chuyển (輸送費), lưu kho (保管費), bốc dỡ (荷役費), đóng gói bao bì (包装費), gia công lưu thông (流通加工費), và quản lý xử lý thông tin (物流管理費・情報処理費).","Phân loại theo lĩnh vực/phạm vi (領域別分類): Dựa trên các chặng trong chuỗi cung ứng hàng hóa, gồm 5 khâu: thu mua (調達物流費), nội bộ nhà máy (社内物流費), phân phối bán hàng (販売物流費), hoàn trả (返品物流費), và thải bỏ (廃棄物流費).","Phân loại theo chủ thể (主体別分類): Gồm chi phí logistics tự đảm nhận (自家物流費: tự dùng xe, kho bãi và nhân viên công ty để làm) và chi phí thuê ngoài (支払物流費: tiền cước trả cho công ty vận tải, đơn vị 3PL).","Phân loại theo tính chất biến đổi (変動固定別分類): Gồm biến phí (変動物流費: tăng giảm theo khối lượng vận chuyển/bốc xếp) và định phí (固定物流費: cố định như chi phí thuê kho hàng tháng, khấu hao phương tiện, lương nhân sự cơ bản).","Phân biệt dễ nhầm giữa 機能別 và 領域別: Chức năng (機能別) trả lời cho câu hỏi 'làm công việc gì?' (đóng gói, chở hàng, xử lý dữ liệu), trong khi lĩnh vực (領域別) trả lời cho câu hỏi 'ở giai đoạn nào của dòng hàng?' (nhập hàng, chuyển kho nội bộ, hay giao khách).","Vị trí của chi phí xử lý thông tin (情報処理費): Là chi phí vận hành hệ thống IT logistics (phần mềm WMS, EDI, thiết bị đọc mã vạch, máy tính), về bản chất hoàn toàn thuộc nhóm chi phí theo chức năng (機能別) hoặc chi phí quản lý, không phải là một lĩnh vực chuỗi cung ứng riêng lẻ.","Ứng dụng quản trị chi phí: Khi doanh nghiệp muốn cắt giảm chi phí kho vận, việc phân loại đa chiều giúp xác định đúng trọng tâm; ví dụ cần giảm chi phí khâu xuất bán sẽ rà soát 販売物流費 (領域別), sau đó bóc tách tiếp sang cước thuê xe 支払運賃 (主体別) hay phí xếp dỡ 荷役費 (機能別)."],"exam_traps":["Đưa 情報処理費 vào 領域別.","Nhầm 機能別 với 領域別.","Nhầm 主体別 với 機能別."],"vocabulary":[{"word":"物流コスト","reading":"ぶつりゅうコスト","meaning":"chi phí logistics"},{"word":"管理上","reading":"かんりじょう","meaning":"trên phương diện quản lý"},{"word":"分類","reading":"ぶんるい","meaning":"phân loại"},{"word":"費目","reading":"ひもく","meaning":"khoản mục chi phí"},{"word":"変動固定別","reading":"へんどうこていべつ","meaning":"phân theo biến phí/cố định"},{"word":"固定物流費","reading":"こていぶつりゅうひ","meaning":"chi phí logistics cố định"},{"word":"機能別","reading":"きのうべつ","meaning":"phân theo chức năng"},{"word":"包装費","reading":"ほうそうひ","meaning":"chi phí đóng gói"},{"word":"主体別","reading":"しゅたいべつ","meaning":"phân theo chủ thể"},{"word":"自家物流費","reading":"じかぶつりゅうひ","meaning":"chi phí logistics tự thực hiện"},{"word":"領域別","reading":"りょういきべつ","meaning":"phân theo lĩnh vực"},{"word":"情報処理費","reading":"じょうほうしょりひ","meaning":"chi phí xử lý thông tin"},{"word":"物流費","reading":"ぶつりゅうひ","meaning":"chi phí logistics"},{"word":"変動費","reading":"へんどうひ","meaning":"biến phí"},{"word":"固定費","reading":"こていひ","meaning":"định phí"},{"word":"機能","reading":"きのう","meaning":"chức năng"},{"word":"主体","reading":"しゅたい","meaning":"chủ thể"},{"word":"領域","reading":"りょういき","meaning":"lĩnh vực"},{"word":"情報処理","reading":"じょうほうしょり","meaning":"xử lý thông tin"},{"word":"包装","reading":"ほうそう","meaning":"đóng gói"},{"word":"自家","reading":"じか","meaning":"tự thực hiện (trong nhà)"}]},{"id":"24","chapter":"10.運搬・物流管理","question":{"japanese":"倉庫機能に関する記述として最も適切なものは、次のうちどれか。なお、DCは在庫型センター、TCは通過型センターである。","vietnamese":"Mô tả nào phù hợp nhất về chức năng kho? Biết DC là trung tâm có tồn kho, TC là trung tâm trung chuyển.","furigana":"倉庫[そうこ]機能[きのう]に関する[かんする]記述[きじゅつ]として最も[もっとも]適切[てきせつ]なものは、次[つぎ]のうちどれか。なお、DCは在庫[ざいこ]型[がた]センター、TCは通過[つうか]型[がた]センターである。"},"options":[{"key":"ア","japanese":"保管効率と入出庫効率は、一般的に二律背反の関係にある。","vietnamese":"Hiệu quả bảo quản và hiệu quả nhập xuất kho thường có quan hệ đánh đổi (trade-off).","furigana":"保管[ほかん]効率[こうりつ]と入[にゅう]出庫[しゅっこ]効率[こうりつ]は、一般的[いっぱんてき]に二律背反[にりつはいはん]の関係[かんけい]にある。"},{"key":"イ","japanese":"立体自動倉庫は、多階層保管により入出庫効率向上を追求している。","vietnamese":"Kho tự động nhiều tầng theo đuổi việc nâng cao hiệu quả nhập xuất nhờ bảo quản nhiều tầng.","furigana":"立体[りったい]自動[じどう]倉庫[そうこ]は、多[た]階層[かいそう]保管[ほかん]により入[にゅう]出庫[しゅっこ]効率[こうりつ]向上[こうじょう]を追求[ついきゅう]している。"},{"key":"ウ","japanese":"DCでは、保管効率よりも入出庫効率を重視する場合が多い。","vietnamese":"Ở DC, nhiều trường hợp coi trọng hiệu quả nhập xuất hơn hiệu quả bảo quản.","furigana":"DCでは、保管[ほかん]効率[こうりつ]よりも入[にゅう]出庫[しゅっこ]効率[こうりつ]を重視[じゅうし]する場合[ばあい]が多い[おおい]。"},{"key":"エ","japanese":"TCでは、仕分け作業効率よりも保管効率を重視する場合が多い。","vietnamese":"Ở TC, nhiều trường hợp coi trọng hiệu quả bảo quản hơn hiệu quả phân loại.","furigana":"TCでは、仕分け[しわけ]作業[さぎょう]効率[こうりつ]よりも保管[ほかん]効率[こうりつ]を重視[じゅうし]する場合[ばあい]が多い[おおい]。"}],"correct_answer":"ア","explanation":{"correct_reason":"Tăng mật độ bảo quản thường làm giảm tốc độ nhập xuất, còn ưu tiên nhập xuất nhanh thường phải giảm mật độ bảo quản. Vì vậy 保管効率 và 入出庫効率 có quan hệ đánh đổi.","incorrect_reasons":{"ア":"Đây là đáp án đúng.","イ":"Sai vì kho tự động nhiều tầng chủ yếu nâng cao mật độ bảo quản và tiết kiệm diện tích, không nhất thiết nâng cao tốc độ nhập xuất.","ウ":"Sai vì DC là kho có tồn kho, thường coi trọng hiệu quả bảo quản hơn.","エ":"Sai vì TC là trung tâm trung chuyển, coi trọng phân loại và nhập xuất nhanh hơn bảo quản."}},"key_knowledge":["Mối quan hệ đánh đổi trong kho hàng (二律背反 - Trade-off): Giữa hiệu quả bảo quản (保管効率 - tối đa hóa sức chứa) và hiệu quả nhập xuất kho (入出庫効率 - tốc độ bốc dỡ) luôn mâu thuẫn. Xếp hàng càng dày và cao để tăng sức chứa thì lối đi hẹp lại và thao tác lấy hàng càng chậm.","Trung tâm tồn kho DC (ディストリビューションセンター / 在庫型センター): Là kho lưu giữ hàng hóa thực tế để đảm bảo nguồn cung ứng ổn định; rất chú trọng đến hiệu quả bảo quản (保管効率) và kiểm soát tồn kho.","Trung tâm trung chuyển TC (トランスファーセンター / 通過型センター): Hàng nhập về từ các nhà cung cấp sẽ được phân loại (仕分け) và giao ngay đến cửa hàng hoặc người nhận mà không lưu kho lâu dài; đặt ưu tiên hàng đầu vào tốc độ và hiệu quả phân loại.","So sánh DC và TC: DC phát sinh chi phí lưu kho và tồn kho lớn nhưng chủ động đáp ứng đơn hàng lẻ nhanh; TC giảm thiểu tối đa chi phí tồn kho nhưng đòi hỏi tính đồng bộ và độ chính xác giao nhận thời gian thực cực cao.","Kho tự động nhiều tầng (立体自動倉庫): Tận dụng triệt để không gian theo chiều dọc bằng các giá kệ cao vút và cần trục xếp dỡ (スタッカークレーン); mục đích cốt lõi là tối đa hóa hiệu quả bảo quản (保管効率) trên một đơn vị diện tích mặt sàn.","Trung tâm phân phối gia công (PDC - プロセシング・ディストリビューションセンター): Là dạng kho kết hợp thêm công đoạn gia công lưu thông (流通加工) như cắt thịt cá, dán nhãn, đóng gói hộp quà trước khi xuất xưởng.","Ứng dụng phân tích ABC trong bố trí kho (倉庫レイアウト): Hàng nhóm A (tần suất xuất nhập cao) thường được xếp gần cửa ra vào và ở tầng dễ lấy để ưu tiên hiệu quả xuất nhập; hàng nhóm C (chậm luân chuyển) xếp sâu bên trong để tối ưu hiệu quả bảo quản."],"exam_traps":["Nhầm DC và TC.","Nói kho tự động chỉ nhằm tăng tốc nhập xuất.","Bỏ qua quan hệ đánh đổi giữa bảo quản và nhập xuất."],"vocabulary":[{"word":"倉庫機能","reading":"そうこきのう","meaning":"chức năng kho"},{"word":"在庫型センター","reading":"ざいこがたセンター","meaning":"trung tâm có tồn kho (DC)"},{"word":"通過型センター","reading":"つうかがたセンター","meaning":"trung tâm trung chuyển (TC)"},{"word":"保管効率","reading":"ほかんこうりつ","meaning":"hiệu quả bảo quản"},{"word":"入出庫効率","reading":"にゅうしゅっここうりつ","meaning":"hiệu quả nhập xuất kho"},{"word":"二律背反","reading":"にりつはいはん","meaning":"đánh đổi, mâu thuẫn"},{"word":"立体自動倉庫","reading":"りったいじどうそうこ","meaning":"kho tự động nhiều tầng"},{"word":"多階層保管","reading":"たかいそうほかん","meaning":"bảo quản nhiều tầng"},{"word":"仕分け作業","reading":"しわけさぎょう","meaning":"công việc phân loại"},{"word":"倉庫","reading":"そうこ","meaning":"kho"},{"word":"在庫型","reading":"ざいこがた","meaning":"kiểu có tồn kho (DC)"},{"word":"通過型","reading":"つうかがた","meaning":"kiểu trung chuyển (TC)"},{"word":"保管","reading":"ほかん","meaning":"bảo quản"},{"word":"入出庫","reading":"にゅうしゅっこ","meaning":"nhập xuất kho"},{"word":"立体","reading":"りったい","meaning":"không gian ba chiều, nhiều tầng"},{"word":"階層","reading":"かいそう","meaning":"tầng, lớp"},{"word":"仕分け","reading":"しわけ","meaning":"phân loại hàng"},{"word":"重視","reading":"じゅうし","meaning":"coi trọng"},{"word":"追求","reading":"ついきゅう","meaning":"theo đuổi"}]},{"id":"25","chapter":"10.運搬・物流管理","question":{"japanese":"運搬の機能や合理化に関する記述として最も不適切なものは、次のうちどれか。","vietnamese":"Trong các mô tả về chức năng và hợp lý hóa vận chuyển, mô tả nào KHÔNG phù hợp nhất?","furigana":"運搬[うんぱん]の機能[きのう]や合理化[ごうりか]に関する[かんする]記述[きじゅつ]として最も[もっとも]不適切[ふてきせつ]なものは、次[つぎ]のうちどれか。"},"options":[{"key":"ア","japanese":"運搬活性示数は、運搬する対象物が連続的に移動している状態を数値化したものである。","vietnamese":"Chỉ số hoạt tính vận chuyển là chỉ số hóa trạng thái đối tượng vận chuyển đang di chuyển liên tục.","furigana":"運搬[うんぱん]活性[かっせい]示数は、運搬[うんぱん]する対象物[たいしょうぶつ]が連続的[れんぞくてき]に移動[いどう]している状態[じょうたい]を数値化[すうちか]したものである。"},{"key":"イ","japanese":"運搬管理においては、顕在的な運搬や潜在的な運搬に対し、改善の取組が実施される。","vietnamese":"Trong quản lý vận chuyển, các nỗ lực cải tiến được thực hiện đối với vận chuyển hiện hữu và vận chuyển tiềm ẩn.","furigana":"運搬[うんぱん]管理[かんり]においては、顕在的[けんざいてき]な運搬[うんぱん]や潜在的[せんざいてき]な運搬[うんぱん]に対し[たいし]、改善[かいぜん]の取組[とりくみ]が実施[じっし]される。"},{"key":"ウ","japanese":"マテリアルハンドリングの原則には、活性荷物の原則、ユニットロードの原則、パレット化の原則、スペース活用の原則などがある。","vietnamese":"Nguyên tắc xử lý vật liệu gồm nguyên tắc hàng hóa hoạt tính, nguyên tắc unit load, nguyên tắc pallet hóa, nguyên tắc sử dụng không gian.","furigana":"マテリアルハンドリングの原則[げんそく]には、活性[かっせい]荷物[にもつ]の原則[げんそく]、ユニットロードの原則[げんそく]、パレット化[か]の原則[げんそく]、スペース活用[かつよう]の原則[げんそく]などがある。"},{"key":"エ","japanese":"運搬の合理化や改善は、その構成要素である運搬物の特性、運搬方法、作業量、運搬経路、稼働状況、運搬量、タイミング、物流情報などに対して行われる。","vietnamese":"Hợp lý hóa/cải tiến vận chuyển được thực hiện đối với các yếu tố cấu thành như đặc tính hàng, phương pháp vận chuyển, khối lượng công việc, tuyến đường, tình trạng hoạt động, lượng vận chuyển, thời điểm, thông tin logistics.","furigana":"運搬[うんぱん]の合理化[ごうりか]や改善[かいぜん]は、その構成[こうせい]要素[ようそ]である運搬物[うんぱんぶつ]の特性[とくせい]、運搬[うんぱん]方法[ほうほう]、作業量[さぎょうりょう]、運搬[うんぱん]経路[けいろ]、稼働[かどう]状況[じょうきょう]、運搬量[うんぱんりょう]、タイミング、物流[ぶつりゅう]情報[じょうほう]などに対して[たいして]行わ[おこなわ]れる。"}],"correct_answer":"ア","explanation":{"correct_reason":"運搬活性示数 (chỉ số hoạt tính vận chuyển) biểu thị mức độ sẵn sàng của hàng khi vận chuyển, từ trạng thái nằm rời rạc (0) đến trạng thái đang di chuyển (4). Không phải chỉ số hóa việc hàng đang di chuyển liên tục.","incorrect_reasons":{"ア":"Đây là đáp án đúng vì định nghĩa 運搬活性示数 bị mô tả sai.","イ":"Sai vì cải tiến cả vận chuyển hiện hữu và tiềm ẩn là đúng.","ウ":"Sai vì các nguyên tắc nêu ra đều thuộc マテリアルハンドリング.","エ":"Sai vì các yếu tố cấu thành vận chuyển được liệt kê đúng."}},"key_knowledge":["Chỉ số hoạt tính vận chuyển (運搬活性示数): Là chỉ số biểu thị mức độ sẵn sàng di chuyển của hàng hóa từ trạng thái tĩnh, được chia thành 5 cấp bậc từ 0 đến 4 (không phải là trạng thái hàng di chuyển liên tục).","Phân cấp chỉ số hoạt tính (運搬活性示数): Cấp 0 (đặt rời trên sàn), Cấp 1 (chứa trong hộp/thùng gom), Cấp 2 (đặt trên pallet/giá đỡ nâng), Cấp 3 (đặt sẵn trên xe kéo/băng chuyền), Cấp 4 (hàng đang chuyển động).","Mục tiêu của nguyên tắc hàng hoạt tính (活性荷物の原則): Hạn chế tối đa hàng ở trạng thái cấp 0 (để bừa bãi dưới sàn) và nâng dần lên cấp 2 hoặc cấp 3 để giảm bớt số lần thao tác xếp dỡ chuẩn bị.","Vận chuyển hiện hữu (顕在的な運搬) và Vận chuyển tiềm ẩn (潜在的な運搬): Vận chuyển hiện hữu là sự dịch chuyển cự ly thực tế giữa các vị trí; vận chuyển tiềm ẩn gồm thao tác nhặt lên, hạ xuống, xoay hướng, dỡ tải tại chỗ.","Xử lý vật liệu (マテリアルハンドリング - Material Handling): Là chuỗi hoạt động nâng hạ, bốc dỡ, di chuyển hàng hóa nội bộ trong nhà máy nhằm duy trì dòng chảy sản xuất nhịp nhàng.","Nguyên tắc Unit Load (ユニットロードの原則): Tập hợp nhiều chi tiết, linh kiện nhỏ lẻ thành một khối đơn vị tiêu chuẩn cố định (như xếp gọn trên 1 pallet) để vận chuyển hàng loạt bằng thiết bị cơ giới.","Nguyên tắc tận dụng không gian (スペース活用の原則): Ưu tiên sử dụng không gian 3 chiều bằng cách xếp chồng lên cao hoặc lắp đặt hệ thống giá đỡ cao tầng, tránh dàn trải chiếm diện tích mặt sàn.","Các yếu tố trọng tâm khi cải tiến vận chuyển: Gồm đặc tính vật phẩm (kích thước, khối lượng, độ dễ vỡ), phương pháp và thiết bị bốc dỡ, lộ trình vận chuyển (運搬経路), thời điểm và luồng thông tin đi kèm."],"exam_traps":["Mô tả 活性示数 chỉ là 'đang di chuyển liên tục'.","Nhầm 顕在的 và 潜在的 vận chuyển.","Đánh tráo các nguyên tắc xử lý vật liệu."],"vocabulary":[{"word":"運搬","reading":"うんぱん","meaning":"vận chuyển"},{"word":"合理化","reading":"ごうりか","meaning":"hợp lý hóa"},{"word":"運搬活性示数","reading":"うんぱんかっせいしすう","meaning":"chỉ số hoạt tính vận chuyển"},{"word":"連続的","reading":"れんぞくてき","meaning":"liên tục"},{"word":"顕在的","reading":"けんざいてき","meaning":"hiện hữu"},{"word":"潜在的","reading":"せんざいてき","meaning":"tiềm ẩn"},{"word":"マテリアルハンドリング","reading":"マテリアルハンドリング","meaning":"xử lý vật liệu"},{"word":"活性荷物","reading":"かっせいにもつ","meaning":"hàng hóa hoạt tính"},{"word":"ユニットロード","reading":"ユニットロード","meaning":"unit load"},{"word":"パレット化","reading":"パレットか","meaning":"pallet hóa"},{"word":"スペース活用","reading":"スペースかつよう","meaning":"sử dụng không gian"},{"word":"構成要素","reading":"こうせいようそ","meaning":"yếu tố cấu thành"},{"word":"稼働状況","reading":"かどうじょうきょう","meaning":"tình trạng hoạt động"},{"word":"活性","reading":"かっせい","meaning":"hoạt tính"},{"word":"示数","reading":"しすう","meaning":"chỉ số"},{"word":"原則","reading":"げんそく","meaning":"nguyên tắc"},{"word":"荷物","reading":"にもつ","meaning":"hàng hóa"},{"word":"活用","reading":"かつよう","meaning":"sử dụng hiệu quả"},{"word":"経路","reading":"けいろ","meaning":"tuyến đường"},{"word":"取組","reading":"とりくみ","meaning":"nỗ lực, biện pháp"},{"word":"搬送","reading":"はんそう","meaning":"vận chuyển"},{"word":"荷役","reading":"にやく","meaning":"bốc xếp hàng"}]},{"id":"26","chapter":"1.品質管理","question":{"japanese":"品質と品質特性に関する記述として最も不適切なものは、次のうちどれか。","vietnamese":"Trong các mô tả về chất lượng và đặc tính chất lượng, mô tả nào KHÔNG phù hợp nhất?","furigana":"品質[ひんしつ]と品質[ひんしつ]特性[とくせい]に関する[かんする]記述[きじゅつ]として最も[もっとも]不適切[ふてきせつ]なものは、次[つぎ]のうちどれか。"},"options":[{"key":"ア","japanese":"製造品質は、設計品質をねらいとして生産する製品の実際の品質であり、ねらいの品質とも呼ばれる。","vietnamese":"Chất lượng sản xuất là chất lượng thực tế của sản phẩm được sản xuất nhằm đạt chất lượng thiết kế, còn được gọi là chất lượng mục tiêu.","furigana":"製造[せいぞう]品質[ひんしつ]は、設計[せっけい]品質[ひんしつ]をねらいとして生産[せいさん]する製品[せいひん]の実際[じっさい]の品質[ひんしつ]であり、ねらいの品質[ひんしつ]とも呼ば[よば]れる。"},{"key":"イ","japanese":"真の特性とは、顧客が要求している品質特性のことで、代用特性は真の特性の代わりとなる特性である。","vietnamese":"Đặc tính thật là đặc tính chất lượng khách hàng yêu cầu; đặc tính thay thế là đặc tính dùng thay cho đặc tính thật.","furigana":"真[しん]の特性[とくせい]とは、顧客[こきゃく]が要求[ようきゅう]している品質[ひんしつ]特性[とくせい]のことで、代用[だいよう]特性[とくせい]は真[しん]の特性[とくせい]の代わり[かわり]となる特性[とくせい]である。"},{"key":"ウ","japanese":"製品やサービスの品質においては、社会的責任の重要性が高まってきており、製品のライフサイクル全体を通して社会的品質を保証する必要がある。","vietnamese":"Trong chất lượng sản phẩm/dịch vụ, trách nhiệm xã hội ngày càng quan trọng, cần đảm bảo chất lượng xã hội trong toàn bộ vòng đời sản phẩm.","furigana":"製品[せいひん]やサービスの品質[ひんしつ]においては、社会的[しゃかいてき]責任[せきにん]の重要性[じゅうようせい]が高まっ[たかまっ]てきており、製品[せいひん]のライフサイクル全体[ぜんたい]を通して[とおして]社会的[しゃかいてき]品質[ひんしつ]を保証[ほしょう]する必要[ひつよう]がある。"},{"key":"エ","japanese":"安全性は、品質特性の1つである。","vietnamese":"Độ an toàn là một trong các đặc tính chất lượng.","furigana":"安全性[あんぜんせい]は、品質[ひんしつ]特性[とくせい]の1つである。"}],"correct_answer":"ア","explanation":{"correct_reason":"製造品質 là chất lượng thực tế tạo ra trong sản xuất, còn ねらいの品質 (chất lượng mục tiêu) chính là 設計品質. Phương án ア gọi 製造品質 là ねらいの品質 nên sai.","incorrect_reasons":{"ア":"Đây là đáp án đúng vì 製造品質 không phải ねらいの品質.","イ":"Sai vì định nghĩa 真の特性 và 代用特性 đúng.","ウ":"Sai vì trách nhiệm xã hội và chất lượng xã hội là nội dung đúng.","エ":"Sai vì 安全性 đúng là một đặc tính chất lượng."}},"key_knowledge":["Phân biệt 設計品質 (Chất lượng thiết kế) và 製造品質 (Chất lượng sản xuất): 設計品質 còn được gọi là ねらいの品質 (chất lượng mục tiêu), là mức chất lượng được vạch ra trên bản vẽ nhằm đáp ứng nhu cầu khách hàng.","製造品質 (Chất lượng sản xuất) còn được gọi là できばえの品質 (chất lượng kết quả/tay nghề) hoặc 適合の品質 (chất lượng phù hợp), phản ánh mức độ sản phẩm thực tế làm ra tại xưởng tuân thủ đúng thiết kế.","真の特性 (Đặc tính thật) là những kỳ vọng trừu tượng trực tiếp từ góc nhìn của khách hàng (ví dụ: tủ lạnh chạy êm, xe chạy êm ái, dao cạo râu lướt mượt).","代用特性 (Đặc tính thay thế) là các đại lượng kỹ thuật cụ thể có thể đo lường và kiểm soát được tại chuyền sản xuất (ví dụ: độ ồn đo bằng dB, độ rung cơ học mm/s, độ sắc bén đo bằng lực cắt N) để gián tiếp thỏa mãn đặc tính thật.","Hệ thống các đặc tính chất lượng (品質特性) cơ bản bao gồm: 機能性 (tính năng), 信頼性 (độ tin cậy theo thời gian), 安全性 (độ an toàn), 経済性 (tính kinh tế/chi phí) và 操作性 (tính dễ sử dụng).","安全性 (Độ an toàn) là đặc tính chất lượng tiên quyết, đảm bảo sản phẩm không gây nguy hiểm cho tính mạng, sức khỏe của người tiêu dùng và không làm tổn hại môi trường trong quá trình sử dụng.","社会的品質 (Chất lượng xã hội) mở rộng phạm vi đánh giá từ việc chỉ phục vụ người mua sang việc có trách nhiệm với cộng đồng trong toàn bộ vòng đời sản phẩm (ライフサイクル全体), bao gồm tiết kiệm tài nguyên, giảm khí thải và khả năng tái chế (リサイクル)."],"exam_traps":["Đồng nhất 製造品質 với 設計品質/ねらいの品質.","Đảo 真の特性 và 代用特性.","Loại 安全性 khỏi đặc tính chất lượng."],"vocabulary":[{"word":"品質","reading":"ひんしつ","meaning":"chất lượng"},{"word":"品質特性","reading":"ひんしつとくせい","meaning":"đặc tính chất lượng"},{"word":"製造品質","reading":"せいぞうひんしつ","meaning":"chất lượng sản xuất"},{"word":"設計品質","reading":"せっけいひんしつ","meaning":"chất lượng thiết kế"},{"word":"ねらいの品質","reading":"ねらいのひんしつ","meaning":"chất lượng mục tiêu"},{"word":"真の特性","reading":"しんのとくせい","meaning":"đặc tính thật"},{"word":"代用特性","reading":"だいようとくせい","meaning":"đặc tính thay thế"},{"word":"社会的責任","reading":"しゃかいてきせきにん","meaning":"trách nhiệm xã hội"},{"word":"ライフサイクル","reading":"ライフサイクル","meaning":"vòng đời"},{"word":"社会的品質","reading":"しゃかいてきひんしつ","meaning":"chất lượng xã hội"},{"word":"安全性","reading":"あんぜんせい","meaning":"độ an toàn"},{"word":"特性","reading":"とくせい","meaning":"đặc tính"},{"word":"要望","reading":"ようぼう","meaning":"nguyện vọng, yêu cầu"},{"word":"保証","reading":"ほしょう","meaning":"đảm bảo"},{"word":"信頼性","reading":"しんらいせい","meaning":"độ tin cậy"},{"word":"経済性","reading":"けいざいせい","meaning":"tính kinh tế"},{"word":"機能性","reading":"きのうせい","meaning":"tính năng"},{"word":"顧客","reading":"こきゃく","meaning":"khách hàng"},{"word":"要求品質","reading":"ようきゅうひんしつ","meaning":"chất lượng yêu cầu"},{"word":"品質保証","reading":"ひんしつほしょう","meaning":"đảm bảo chất lượng"}]},{"id":"27","chapter":"1.品質管理","question":{"japanese":"グラフの種類と目的に関する記述として最も不適切なものは、次のうちどれか。","vietnamese":"Trong các mô tả về loại biểu đồ và mục đích, mô tả nào KHÔNG phù hợp nhất?","furigana":"グラフの種類[しゅるい]と目的[もくてき]に関する[かんする]記述[きじゅつ]として最も[もっとも]不適切[ふてきせつ]なものは、次[つぎ]のうちどれか。"},"options":[{"key":"ア","japanese":"帯グラフ：項目の帯を区切って項目の内訳を表したグラフ","vietnamese":"Biểu đồ dải: biểu đồ chia dải của hạng mục để thể hiện cơ cấu bên trong.","furigana":"帯[おび]グラフ：項目[こうもく]の帯[おび]を区切っ[くぎっ]て項目[こうもく]の内訳[うちわけ]を表し[あらわし]たグラフ"},{"key":"イ","japanese":"折れ線グラフ：時系列の推移を点と線で結んだグラフ","vietnamese":"Biểu đồ đường: nối các điểm để thể hiện xu hướng theo thời gian.","furigana":"折れ線[おれせん]グラフ：時系列[じけいれつ]の推移[すいい]を点[てん]と線[せん]で結ん[むすん]だグラフ"},{"key":"ウ","japanese":"層グラフ：時間の経過による変化とその項目内訳を積み重ねて表すグラフ","vietnamese":"Biểu đồ tầng: biểu đồ xếp chồng thể hiện thay đổi theo thời gian và cơ cấu hạng mục.","furigana":"層[そう]グラフ：時間[じかん]の経過[けいか]による変化[へんか]とその項目[こうもく]内訳[うちわけ]を積み重ね[つみかさね]て表す[あらわす]グラフ"},{"key":"エ","japanese":"円グラフ：放射線の軸上に項目ごとに値をプロットした点を線で結んで表したグラフ","vietnamese":"Biểu đồ tròn: biểu đồ vẽ giá trị từng hạng mục trên trục tỏa tia rồi nối các điểm bằng đường.","furigana":"円グラフ[えんぐらふ]：放射線[ほうしゃせん]の軸上[じくじょう]に項目[こうもく]ごとに値[ね]をプロットした点[てん]を線[せん]で結ん[むすん]で表し[あらわし]たグラフ"}],"correct_answer":"エ","explanation":{"correct_reason":"Mô tả エ thực chất là レーダーチャート (biểu đồ radar), không phải 円グラフ. 円グラフ thể hiện tỷ lệ cơ cấu bằng hình tròn chia lát.","incorrect_reasons":{"ア":"Sai vì 帯グラフ đúng là chia dải để thể hiện cơ cấu.","イ":"Sai vì 折れ線グラフ đúng là nối điểm thể hiện xu hướng thời gian.","ウ":"Sai vì 層グラフ đúng là xếp chồng thể hiện thay đổi và cơ cấu.","エ":"Đây là đáp án đúng vì mô tả là biểu đồ radar, không phải biểu đồ tròn."}},"key_knowledge":["Biểu đồ tròn (円グラフ): Dùng một hình tròn chia thành các hình quạt để biểu thị tỷ lệ cơ cấu (内訳・構成比) của một tổng thể tại một thời điểm nhất định; theo quy ước chuẩn, các lát cắt lớn nhất xếp từ vị trí 12 giờ theo chiều kim đồng hồ và mục 'khác' (その他) luôn nằm ở vị trí cuối cùng.","Biểu đồ radar (レーダーチャート): Có các trục xuất phát từ tâm tỏa ra xung quanh (放射線の軸) tương ứng với từng hạng mục, điểm số trên các trục được nối lại với nhau tạo thành đa giác; thường dùng trong nhà máy để đánh giá trực quan mức độ cân bằng đa tiêu chí như kỹ năng đa năng hóa của công nhân hoặc điểm số 5S.","Biểu đồ đường (折れ線グラフ): Thể hiện dữ liệu bằng cách nối các điểm bằng các đoạn thẳng, mục đích chính là theo dõi sự thay đổi và xu hướng biến động theo thời gian (時系列の推移); thường áp dụng để kiểm soát tỷ lệ lỗi sản phẩm (不良率) theo từng ngày hoặc từng tháng.","Biểu đồ dải (帯グラフ): Là một cột chữ nhật đại diện cho 100%, được chia thành các dải nhỏ để biểu diễn cơ cấu thành phần; thường xếp nhiều dải nằm ngang cạnh nhau để so sánh sự dịch chuyển tỷ trọng giữa các phân xưởng hoặc giữa các năm.","Biểu đồ tầng (層グラフ): Dạng biểu đồ tích lũy xếp chồng các chuỗi dữ liệu lên nhau theo trục thời gian; điểm nổi bật là giúp quan sát đồng thời cả sự biến động của tổng đại lượng (総合計) lẫn biến động tỷ trọng của từng yếu tố cấu thành bên trong.","Biểu đồ cột (棒グラフ): Dùng chiều cao hoặc độ dài của các thanh riêng biệt để so sánh độ lớn (大小関係) giữa các hạng mục độc lập; khác với biểu đồ đường tập trung vào xu thế thời gian, biểu đồ cột tập trung vào so sánh định lượng tĩnh giữa các đối tượng như sản lượng giữa các máy móc.","Phân biệt Biểu đồ cột (棒グラフ) và Biểu đồ phân bố (ヒストグラム): Biểu đồ cột dùng cho biến rời rạc phân loại (như doanh số theo mẫu mã), giữa các cột có khoảng cách; còn biểu đồ phân bố biểu thị tần số của biến liên tục (như kích thước gia công, trọng lượng) và các cột được vẽ sát liền kề nhau."],"exam_traps":["Mô tả biểu đồ radar nhưng gọi là 円グラフ.","Nhầm 帯グラフ với 層グラフ.","Nhầm mục đích biểu đồ đường với biểu đồ cột."],"vocabulary":[{"word":"グラフ","reading":"グラフ","meaning":"biểu đồ"},{"word":"帯グラフ","reading":"おびグラフ","meaning":"biểu đồ dải"},{"word":"項目","reading":"こうもく","meaning":"hạng mục"},{"word":"内訳","reading":"うちわけ","meaning":"cơ cấu, phân breakdown"},{"word":"折れ線グラフ","reading":"おれせんグラフ","meaning":"biểu đồ đường"},{"word":"時系列","reading":"じけいれつ","meaning":"chuỗi thời gian"},{"word":"推移","reading":"すいい","meaning":"diễn biến, xu hướng"},{"word":"層グラフ","reading":"そうグラフ","meaning":"biểu đồ tầng/xếp chồng"},{"word":"積み重ね","reading":"つみかさね","meaning":"xếp chồng"},{"word":"円グラフ","reading":"えんグラフ","meaning":"biểu đồ tròn"},{"word":"放射線","reading":"ほうしゃせん","meaning":"tia tỏa ra"},{"word":"プロット","reading":"プロット","meaning":"vẽ điểm"},{"word":"帯","reading":"おび","meaning":"dải"},{"word":"区切る","reading":"くぎる","meaning":"chia cắt, ngăn"},{"word":"折れ線","reading":"おれせん","meaning":"đường gãy khúc"},{"word":"層","reading":"そう","meaning":"tầng, lớp"},{"word":"円","reading":"えん","meaning":"hình tròn"},{"word":"放射","reading":"ほうしゃ","meaning":"tỏa ra"},{"word":"軸","reading":"じく","meaning":"trục"}]},{"id":"28","chapter":"1.品質管理","question":{"japanese":"検査に関する事項として最も不適切なものは、次のうちどれか。","vietnamese":"Trong các nội dung về kiểm tra, nội dung nào KHÔNG phù hợp nhất?","furigana":"検査[けんさ]に関する[かんする]事項[じこう]として最も[もっとも]不適切[ふてきせつ]なものは、次[つぎ]のうちどれか。"},"options":[{"key":"ア","japanese":"全数検査が適用されるケースとしては、製品が非常に高価な場合がある。","vietnamese":"Một trường hợp áp dụng kiểm tra toàn bộ là khi sản phẩm rất đắt tiền.","furigana":"全数[ぜんすう]検査[けんさ]が適用[てきよう]されるケースとしては、製品[せいひん]が非常[ひじょう]に高価[こうか]な場合[ばあい]がある。"},{"key":"イ","japanese":"検査を厳重に行うことで、品質の高いものが生産できる。","vietnamese":"Kiểm tra nghiêm ngặt sẽ giúp sản xuất được sản phẩm chất lượng cao.","furigana":"検査[けんさ]を厳重[げんじゅう]に行う[おこなう]ことで、品質[ひんしつ]の高い[たかい]ものが生産[せいさん]できる。"},{"key":"ウ","japanese":"自主検査は、自ら製造したものに責任を持ち、不適合品を後工程に流さないことを目指している。","vietnamese":"Tự kiểm tra nhằm có trách nhiệm với sản phẩm mình sản xuất và không để sản phẩm không phù hợp chảy sang công đoạn sau.","furigana":"自主[じしゅ]検査[けんさ]は、自ら[みずから]製造[せいぞう]したものに責任[せきにん]を持ち[もち]、不適合品[ふてきごうひん]を後工程[あとこうてい]に流さ[ながさ]ないことを目指し[めざし]ている。"},{"key":"エ","japanese":"合格すべきロットを不合格にする誤りは、生産者危険といわれる。","vietnamese":"Lỗi đánh giá lô đáng lẽ đạt thành không đạt được gọi là rủi ro nhà sản xuất.","furigana":"合格[ごうかく]すべきロットを不合格[ふごうかく]にする誤り[あやまり]は、生産者[せいさんしゃ]危険[きけん]といわれる。"}],"correct_answer":"イ","explanation":{"correct_reason":"Kiểm tra chỉ phát hiện và ngăn sản phẩm lỗi, không trực tiếp tạo ra chất lượng. Chất lượng cao phải được tạo ra trong thiết kế và quá trình sản xuất (quality by process). Kiểm tra nghiêm ngặt không thể biến quá trình kém thành chất lượng cao.","incorrect_reasons":{"ア":"Sai vì sản phẩm đắt tiền là trường hợp hợp lý để kiểm tra toàn bộ.","イ":"Đây là đáp án đúng vì kiểm tra không trực tiếp tạo ra chất lượng.","ウ":"Sai vì 自主検査 đúng là tự chịu trách nhiệm và ngăn hàng lỗi.","エ":"Sai vì 生産者危険 đúng là đánh giá lô đạt thành không đạt."}},"key_knowledge":["Bản chất của kiểm tra (検査 - Kensa): Kiểm tra chỉ đóng vai trò phân loại, sàng lọc sản phẩm đạt chuẩn (合格品) và không đạt chuẩn (不適合品), hoàn toàn không thể làm tăng thêm giá trị hay chất lượng vốn có của sản phẩm.","Nguyên lý tạo dựng chất lượng (品質は工程で作り込む): Chất lượng cao phải được hình thành từ khâu thiết kế và kiểm soát các yếu tố 4M trong dây chuyền sản xuất (工程管理), việc siết chặt kiểm tra đầu ra chỉ làm tăng chi phí chứ không giải quyết tận gốc nguyên nhân gây lỗi.","Kiểm tra toàn bộ (全数検査 - Zensū kensa): Áp dụng bắt buộc khi sản phẩm có ảnh hưởng nghiêm trọng đến tính mạng và an toàn (như túi khí, hệ thống phanh ô tô), sản phẩm cực kỳ đắt đỏ (高価), hoặc khi chi phí lọt lỗi ra ngoài lớn hơn rất nhiều so với chi phí kiểm tra.","Kiểm tra lấy mẫu (抜取検査 - Nukitori kensa): Phương pháp rút ngẫu nhiên một lượng mẫu nhất định từ lô hàng (ロット) để phán định chấp nhận hay loại bỏ cả lô; bắt buộc áp dụng đối với kiểm tra phá hủy (破壊検査, ví dụ: thử độ bền kéo, thử vị giác thực phẩm).","Tự kiểm tra (自主検査 - Jishu kensa): Thao tác viên tự kiểm tra sản phẩm do chính tay mình tạo ra trước khi chuyển đi, thể hiện tinh thần 'công đoạn sau là khách hàng' (後工程はお客様) nhằm ngăn chặn tuyệt đối hàng lỗi chuyển sang bước kế tiếp.","Rủi ro nhà sản xuất (生産者危険 - α risk / Type I error): Lỗi xác suất khi một lô hàng thực chất đạt chuẩn (合格ロット) nhưng do ngẫu nhiên lấy phải mẫu lỗi nên bị phán định oan là không đạt, gây tổn thất và lãng phí cho nhà sản xuất.","Rủi ro người tiêu dùng (消費者危険 - β risk / Type II error): Lỗi xác suất khi một lô hàng kém chất lượng (不合格ロット) lại vô tình vượt qua kiểm tra lấy mẫu để xuất bán cho khách hàng, dẫn đến nguy cơ khiếu nại (クレーム) và mất uy tín doanh nghiệp."],"exam_traps":["Nói kiểm tra nghiêm ngặt tạo ra chất lượng cao.","Đảo 生産者危険 và 消費者危険.","Nhầm 自主検査 với kiểm tra của bên thứ ba."],"vocabulary":[{"word":"検査","reading":"けんさ","meaning":"kiểm tra"},{"word":"全数検査","reading":"ぜんすうけんさ","meaning":"kiểm tra toàn bộ"},{"word":"高価","reading":"こうか","meaning":"đắt tiền"},{"word":"厳重","reading":"げんじゅう","meaning":"nghiêm ngặt"},{"word":"自主検査","reading":"じしゅけんさ","meaning":"tự kiểm tra"},{"word":"後工程","reading":"あとこうてい","meaning":"công đoạn sau"},{"word":"ロット","reading":"ロット","meaning":"lô"},{"word":"生産者危険","reading":"せいさんしゃきけん","meaning":"rủi ro nhà sản xuất"},{"word":"消費者危険","reading":"しょうひしゃきけん","meaning":"rủi ro người tiêu dùng"},{"word":"合格","reading":"ごうかく","meaning":"đạt"},{"word":"不合格","reading":"ふごうかく","meaning":"không đạt"},{"word":"抽出","reading":"ちゅうしゅつ","meaning":"lấy mẫu, trích ra"},{"word":"責任","reading":"せきにん","meaning":"trách nhiệm"},{"word":"抜取検査","reading":"ぬきとりけんさ","meaning":"kiểm tra lấy mẫu"},{"word":"サンプリング","reading":"サンプリング","meaning":"lấy mẫu"},{"word":"合格判定","reading":"ごうかくはんてい","meaning":"đánh giá đạt/không đạt"},{"word":"不良率","reading":"ふりょうりつ","meaning":"tỷ lệ lỗi"},{"word":"見逃し","reading":"みのがし","meaning":"bỏ sót"},{"word":"受入検査","reading":"うけいれけんさ","meaning":"kiểm tra đầu vào"},{"word":"出荷検査","reading":"しゅっかけんさ","meaning":"kiểm tra xuất hàng"}]},{"id":"29","chapter":"1.品質管理","question":{"japanese":"ISO9000シリーズに関する記述として最も不適切なものは、次のうちどれか。","vietnamese":"Trong các mô tả về ISO9000 series, mô tả nào KHÔNG phù hợp nhất?","furigana":"ISO9000シリーズに関する[かんする]記述[きじゅつ]として最も[もっとも]不適切[ふてきせつ]なものは、次[つぎ]のうちどれか。"},"options":[{"key":"ア","japanese":"ISO9000シリーズでは、品質に関するマネジメントは経営活動の一環であることが強調されている。","vietnamese":"ISO9000 series nhấn mạnh quản lý chất lượng là một phần của hoạt động kinh doanh.","furigana":"ISO9000シリーズでは、品質[ひんしつ]に関する[かんする]マネジメントは経営[けいえい]活動[かつどう]の一環[いっかん]であることが強調[きょうちょう]されている。"},{"key":"イ","japanese":"ISO9000シリーズは、JISに取り入れられている。","vietnamese":"ISO9000 series được đưa vào JIS.","furigana":"ISO9000シリーズは、JISに取り入れ[とりいれ]られている。"},{"key":"ウ","japanese":"ISO9000シリーズは、米国を中心に進められてきた。","vietnamese":"ISO9000 series được thúc đẩy chủ yếu ở Mỹ.","furigana":"ISO9000シリーズは、米国[べいこく]を中心[ちゅうしん]に進め[すすめ]られてきた。"},{"key":"エ","japanese":"ISO9000シリーズは、企業が構築した品質マネジメントシステムが規格に適合していれば、一定の品質が保証された製品が製造できるという考え方に立っている。","vietnamese":"ISO9000 series dựa trên quan điểm rằng nếu hệ thống quản lý chất lượng của doanh nghiệp phù hợp tiêu chuẩn thì có thể sản xuất sản phẩm được đảm bảo chất lượng nhất định.","furigana":"ISO9000シリーズは、企業[きぎょう]が構築[こうちく]した品質[ひんしつ]マネジメントシステムが規格[きかく]に適合[てきごう]していれば、一定[いってい]の品質[ひんしつ]が保証[ほしょう]された製品[せいひん]が製造[せいぞう]できるという考え方[かんがえかた]に立っ[たっ]ている。"}],"correct_answer":"ウ","explanation":{"correct_reason":"ISO9000 series do ISO (International Organization for Standardization) ban hành, có nguồn gốc và ảnh hưởng mạnh từ châu Âu (Anh), không phải do Mỹ dẫn đầu.","incorrect_reasons":{"ア":"Sai vì ISO9000 nhấn mạnh quản lý chất lượng là một phần của quản trị kinh doanh.","イ":"Sai vì ISO9000 được chấp nhận và chuyển thành JIS.","ウ":"Đây là đáp án đúng vì ISO9000 không do Mỹ dẫn đầu.","エ":"Sai vì quan điểm hệ thống QMS phù hợp tiêu chuẩn đảm bảo chất lượng ổn định là đúng."}},"key_knowledge":["Khái niệm hệ thống QMS: ISO9000 series là bộ tiêu chuẩn quốc tế về Hệ thống quản lý chất lượng (品質マネジメントシステム - QMS), tập trung vào cách thức quản lý quy trình để đảm bảo chất lượng ổn định.","Nguồn gốc phát triển: ISO9000 có nguồn gốc xuất phát từ châu Âu (đặc biệt là tiêu chuẩn BS 5750 của Anh) và do Tổ chức Tiêu chuẩn hóa Quốc tế (ISO) ban hành, không phải do Mỹ (米国) dẫn đầu.","Liên kết với tiêu chuẩn Nhật Bản (JIS): Tiêu chuẩn ISO9000 được dịch và tích hợp nguyên bản vào hệ thống tiêu chuẩn công nghiệp Nhật Bản thành JIS Q 9000 series (JISに取り入れられている).","Gắn liền với quản trị kinh doanh: Tiêu chuẩn nhấn mạnh quản lý chất lượng là một phần không thể tách rời của hoạt động điều hành doanh nghiệp (経営活動の一環), đòi hỏi vai trò lãnh đạo trực tiếp từ ban giám đốc (トップマネジメント).","Nguyên lý bảo đảm chất lượng: ISO9000 vận hành theo quan điểm nếu doanh nghiệp vận hành hệ thống đạt chuẩn thì sẽ có đủ năng lực tạo ra sản phẩm đạt chất lượng ổn định định kỳ, chứ không kiểm định từng sản phẩm đơn lẻ (製品規格).","Phân biệt ISO 9001 và ISO 14001: ISO 9001 chuyên về hệ thống quản lý chất lượng (品質マネジメント), trong khi ISO 14001 chuyên về hệ thống quản lý môi trường (環境マネジメントシステム - EMS).","Tư duy quá trình và PDCA: Hệ thống yêu cầu kiểm soát theo phương pháp tiếp cận quá trình (プロセスアプローチ) và thực hiện chu trình PDCA để cải tiến liên tục (継続的改善) nhằm nâng cao sự thỏa mãn của khách hàng (顧客満足).","Ứng dụng thực tế tại nhà máy: Chứng nhận ISO 9001 đóng vai trò như một giấy thông hành bảo đảm uy tín để các nhà máy tham gia vào chuỗi cung ứng toàn cầu hoặc nhận gia công cho các đối tác lớn."],"exam_traps":["Nói ISO9000 do Mỹ dẫn đầu.","Nói ISO9000 đảm bảo chất lượng từng sản phẩm tuyệt đối.","Nhầm ISO9000 với ISO14000."],"vocabulary":[{"word":"ISO9000シリーズ","reading":"ISO9000シリーズ","meaning":"bộ tiêu chuẩn ISO9000"},{"word":"品質に関するマネジメント","reading":"ひんしつにかんするマネジメント","meaning":"quản lý liên quan chất lượng"},{"word":"経営活動","reading":"けいえいかつどう","meaning":"hoạt động kinh doanh"},{"word":"一環","reading":"いっかん","meaning":"một phần"},{"word":"取り入れる","reading":"とりいれる","meaning":"tiếp nhận, đưa vào"},{"word":"米国","reading":"べいこく","meaning":"Mỹ"},{"word":"中心","reading":"ちゅうしん","meaning":"trung tâm"},{"word":"構築","reading":"こうちく","meaning":"xây dựng"},{"word":"品質マネジメントシステム","reading":"ひんしつマネジメントシステム","meaning":"hệ thống quản lý chất lượng"},{"word":"規格","reading":"きかく","meaning":"tiêu chuẩn"},{"word":"適合","reading":"てきごう","meaning":"phù hợp"},{"word":"保証","reading":"ほしょう","meaning":"đảm bảo"},{"word":"シリーズ","reading":"シリーズ","meaning":"bộ, chuỗi"},{"word":"欧州","reading":"おうしゅう","meaning":"châu Âu"},{"word":"認証","reading":"にんしょう","meaning":"chứng nhận"},{"word":"審査","reading":"しんさ","meaning":"thẩm tra, xét duyệt"},{"word":"品質保証","reading":"ひんしつほしょう","meaning":"đảm bảo chất lượng"},{"word":"国際","reading":"こくさい","meaning":"quốc tế"},{"word":"標準化","reading":"ひょうじゅんか","meaning":"tiêu chuẩn hóa"},{"word":"監査","reading":"かんさ","meaning":"đánh giá, kiểm toán"}]},{"id":"30","chapter":"2.原価管理","question":{"japanese":"下図のa〜dに入る用語の組合せとして適切なものは、次のうちどれか。\n（原価管理 → a → b［企画・開発・設計段階 / 具体的な手法：VEなど］, c［製造段階 / 具体的な手法：IEなど］； 原価統制 → 原価維持［具体的な手法：dなど］）","vietnamese":"Tổ hợp thuật ngữ nào phù hợp để điền vào a〜d trong sơ đồ?\n(Quản lý chi phí → a → b [giai đoạn kế hoạch/phát triển/thiết kế / phương pháp cụ thể: VE...], c [giai đoạn sản xuất / phương pháp cụ thể: IE...]; Kiểm soát chi phí → duy trì chi phí [phương pháp cụ thể: d...])","furigana":"下図[したず]のa〜dに入る[はいる]用語[ようご]の組合せ[くみあわせ]として適切[てきせつ]なものは、次[つぎ]のうちどれか。\n（原価[げんか]管理[かんり] → a → b［企画[きかく]・開発[かいはつ]・設計[せっけい]段階[だんかい] / 具体的[ぐたいてき]な手法[しゅほう]：VEなど］, c［製造[せいぞう]段階[だんかい] / 具体的[ぐたいてき]な手法[しゅほう]：IEなど］； 原価[げんか]統制[とうせい] → 原価[げんか]維持[いじ]［具体的[ぐたいてき]な手法[しゅほう]：dなど］）"},"options":[{"key":"ア","japanese":"a:原価低減 b:原価改善 c:原価企画 d:ABC/ABM","vietnamese":"a: giảm chi phí b: cải tiến chi phí c: kế hoạch chi phí d: ABC/ABM","furigana":"a:原価[げんか]低減[ていげん] b:原価[げんか]改善[かいぜん] c:原価[げんか]企画[きかく] d:ABC/ABM"},{"key":"イ","japanese":"a:原価低減 b:原価企画 c:原価改善 d:標準原価計算","vietnamese":"a: giảm chi phí b: kế hoạch chi phí c: cải tiến chi phí d: tính giá thành chuẩn","furigana":"a:原価[げんか]低減[ていげん] b:原価[げんか]企画[きかく] c:原価[げんか]改善[かいぜん] d:標準[ひょうじゅん]原価[げんか]計算[けいさん]"},{"key":"ウ","japanese":"a:原価改善 b:原価低減 c:原価企画 d:ABC/ABM","vietnamese":"a: cải tiến chi phí b: giảm chi phí c: kế hoạch chi phí d: ABC/ABM","furigana":"a:原価[げんか]改善[かいぜん] b:原価[げんか]低減[ていげん] c:原価[げんか]企画[きかく] d:ABC/ABM"},{"key":"エ","japanese":"a:原価企画 b:原価低減 c:原価改善 d:標準原価計算","vietnamese":"a: kế hoạch chi phí b: giảm chi phí c: cải tiến chi phí d: tính giá thành chuẩn","furigana":"a:原価[げんか]企画[きかく] b:原価[げんか]低減[ていげん] c:原価[げんか]改善[かいぜん] d:標準[ひょうじゅん]原価[げんか]計算[けいさん]"}],"correct_answer":"イ","explanation":{"correct_reason":"原価管理 gồm 原価低減, chia thành 原価企画 (giai đoạn kế hoạch/phát triển/thiết kế, dùng VE) và 原価改善 (giai đoạn sản xuất, dùng IE). 原価統制 gồm 原価維持, dùng 標準原価計算. Vì vậy a:原価低減, b:原価企画, c:原価改善, d:標準原価計算.","incorrect_reasons":{"ア":"Sai vì b và c bị đảo, d không phải ABC/ABM.","イ":"Đây là đáp án đúng.","ウ":"Sai vì a, b, c đều sai vị trí.","エ":"Sai vì a phải là 原価低減, không phải 原価企画."}},"key_knowledge":["Cấu trúc tổng thể của Quản lý chi phí (原価管理): Được chia làm hai nhánh lớn là Giảm chi phí (原価低減) nhằm hạ thấp mức chi phí mục tiêu, và Kiểm soát chi phí (原価統制) nhằm giữ cho chi phí thực tế không vượt mức cho phép.","Kế hoạch hóa chi phí (原価企画): Thực hiện ở giai đoạn thượng nguồn (kế hoạch, phát triển, thiết kế sản phẩm) trước khi đưa vào sản xuất hàng loạt; đây là giai đoạn quyết định đến khoảng 80% tổng chi phí của sản phẩm.","Công cụ VE (Value Engineering - Kỹ xảo giá trị): Là phương pháp cốt lõi dùng trong giai đoạn Kế hoạch hóa chi phí (原価企画), phân tích mối quan hệ giữa công năng sản phẩm và chi phí theo công thức V = F/C để đạt chi phí tối ưu ngay từ bản vẽ.","Cải tiến chi phí (原価改善): Thực hiện ở giai đoạn hạ nguồn (giai đoạn sản xuất thực tế tại hiện trường), nhằm liên tục cắt giảm hao phí phát sinh trong các thao tác và quy trình vận hành hàng ngày.","Công cụ IE (Industrial Engineering - Kỹ nghệ công nghiệp): Là phương pháp tiêu biểu dùng trong giai đoạn Cải tiến chi phí (原価改善), tập trung phân tích thao tác, đo lường thời gian chu kỳ và tối ưu hóa mặt bằng sản xuất để giảm lãng phí giờ công.","Duy trì chi phí (原価維持) và Kiểm soát chi phí (原価統制): Hoạt động nhằm ngăn chặn chi phí phát sinh thực tế vượt khỏi khuôn khổ tiêu chuẩn đã định trước của doanh nghiệp.","Tính giá thành chuẩn (標準原価計算): Phương pháp xác định chi phí tiêu chuẩn trước kỳ sản xuất, sau đó thu thập chi phí thực tế để phân tích sai lệch (差異分析) và tìm nguyên nhân khắc phục nếu có biến động bất lợi.","Phân biệt cặp khái niệm dễ nhầm: Nguyên tắc cốt lõi cần nhớ là Kế hoạch chi phí (原価企画) đi với 'thiết kế/VE', còn Cải tiến chi phí (原価改善) đi với 'chế tạo/IE'."],"exam_traps":["Đảo 原価企画 và 原価改善.","Đặt 標準原価計算 vào 原価低減.","Nhầm ABC/ABM với 標準原価計算."],"vocabulary":[{"word":"原価管理","reading":"げんかかんり","meaning":"quản lý chi phí"},{"word":"原価統制","reading":"げんかとうせい","meaning":"kiểm soát chi phí"},{"word":"原価低減","reading":"げんかていげん","meaning":"giảm chi phí"},{"word":"原価企画","reading":"げんかきかく","meaning":"kế hoạch chi phí"},{"word":"原価改善","reading":"げんかかいぜん","meaning":"cải tiến chi phí"},{"word":"原価維持","reading":"げんかいじ","meaning":"duy trì chi phí"},{"word":"企画","reading":"きかく","meaning":"kế hoạch, quy hoạch"},{"word":"開発","reading":"かいはつ","meaning":"phát triển"},{"word":"設計段階","reading":"せっけいだんかい","meaning":"giai đoạn thiết kế"},{"word":"製造段階","reading":"せいぞうだんかい","meaning":"giai đoạn sản xuất"},{"word":"標準原価計算","reading":"ひょうじゅんげんかけいさん","meaning":"tính giá thành chuẩn"},{"word":"ABC/ABM","reading":"ABC/ABM","meaning":"ABC/ABM"},{"word":"原価","reading":"げんか","meaning":"chi phí, giá thành"},{"word":"統制","reading":"とうせい","meaning":"kiểm soát"},{"word":"低減","reading":"ていげん","meaning":"giảm bớt"},{"word":"改善","reading":"かいぜん","meaning":"cải tiến"},{"word":"維持","reading":"いじ","meaning":"duy trì"},{"word":"VE","reading":"ブイイー","meaning":"VE (kỹ thuật giá trị)"},{"word":"IE","reading":"アイイー","meaning":"IE (kỹ thuật công nghiệp)"},{"word":"手法","reading":"しゅほう","meaning":"phương pháp"},{"word":"段階","reading":"だんかい","meaning":"giai đoạn"}]},{"id":"31","chapter":"2.原価管理","question":{"japanese":"製品開発における原価概念に関する記述として最も不適切なものは、次のうちどれか。","vietnamese":"Trong các mô tả về khái niệm chi phí trong phát triển sản phẩm, mô tả nào KHÔNG phù hợp nhất?","furigana":"製品[せいひん]開発[かいはつ]における原価[げんか]概念[がいねん]に関する[かんする]記述[きじゅつ]として最も[もっとも]不適切[ふてきせつ]なものは、次[つぎ]のうちどれか。"},"options":[{"key":"ア","japanese":"成行原価は、現状レベルの技術に基づいて設計した図面により、原価を積み上げたものである。","vietnamese":"Thành hành chi phí là chi phí được tích lũy dựa trên bản vẽ thiết kế theo trình độ kỹ thuật hiện tại.","furigana":"成行[なりゆき]原価[げんか]は、現状[げんじょう]レベルの技術[ぎじゅつ]に基づい[もとづい]て設計[せっけい]した図面[ずめん]により、原価[げんか]を積み上げ[つみあげ]たものである。"},{"key":"イ","japanese":"許容原価は、市場競争価格である予定価格から、経営者の求める目標利益を差し引いて求めた原価である。","vietnamese":"Chi phí cho phép là chi phí tính bằng giá kế hoạch (giá cạnh tranh thị trường) trừ lợi nhuận mục tiêu mà ban lãnh đạo yêu cầu.","furigana":"許容[きょよう]原価[げんか]は、市場[しじょう]競争[きょうそう]価格[かかく]である予定[よてい]価格[かかく]から、経営者[けいえいしゃ]の求める[もとめる]目標[もくひょう]利益[りえき]を差し引い[さしひい]て求め[もとめ]た原価[げんか]である。"},{"key":"ウ","japanese":"目標原価は、開発プロセスにおいてコストレビューをするために用いられる原価である。","vietnamese":"Chi phí mục tiêu là chi phí dùng để xem xét chi phí trong quá trình phát triển.","furigana":"目標[もくひょう]原価[げんか]は、開発[かいはつ]プロセスにおいてコストレビューをするために用い[もちい]られる原価[げんか]である。"},{"key":"エ","japanese":"実際原価は、設計技術者が、作成した図面に基づいて算出した原価である。","vietnamese":"Chi phí thực tế là chi phí mà kỹ sư thiết kế tính toán dựa trên bản vẽ đã tạo.","furigana":"実際[じっさい]原価[げんか]は、設計[せっけい]技術者[ぎじゅつしゃ]が、作成[さくせい]した図面[ずめん]に基づい[もとづい]て算出[さんしゅつ]した原価[げんか]である。"}],"correct_answer":"エ","explanation":{"correct_reason":"実際原価 là chi phí thực tế phát sinh trong sản xuất, dựa trên số liệu thực tế, không phải chi phí tính từ bản vẽ thiết kế. Chi phí tính từ bản vẽ là 成行原価/見積原価.","incorrect_reasons":{"ア":"Sai vì 成行原価 đúng là chi phí tích lũy theo bản vẽ và kỹ thuật hiện tại.","イ":"Sai vì 許容原価 đúng là giá bán dự kiến trừ lợi nhuận mục tiêu.","ウ":"Sai vì 目標原価 được dùng để review chi phí trong phát triển.","エ":"Đây là đáp án đúng vì 実際原価 là chi phí thực tế phát sinh, không tính từ bản vẽ."}},"key_knowledge":["成行原価 (Narikiyuki genka - Chi phí hiện trạng / Chi phí tự nhiên): Là tổng chi phí được tính dồn (積み上げ) từ bản vẽ thiết kế dựa trên trình độ kỹ thuật và quy trình sản xuất hiện hữu, chưa qua hoạt động cải tiến cắt giảm lãng phí.","許容原価 (Kyoyō genka - Chi phí cho phép): Là mức trần chi phí tối đa mà doanh nghiệp có thể chấp nhận để đảm bảo có lãi, xác định bằng công thức: Giá bán dự kiến theo thị trường (予定販売価格) − Lợi nhuận mục tiêu (目標利益).","目標原価 (Mokuhyō genka - Chi phí mục tiêu): Là mức chi phí đích cần đạt được thông qua nỗ lực cải tiến kỹ thuật và thiết kế (thường nằm giữa 許容原価 và 成行原価), được dùng làm chuẩn đối chiếu trong các đợt rà soát chi phí (コストレビュー).","実際原価 (Jissai genka - Chi phí thực tế): Là chi phí thực sự phát sinh và được ghi nhận sau khi tiến hành sản xuất sản phẩm thực tế, dựa trên khối lượng vật tư tiêu hao và số giờ công lao động thực tế.","Phân biệt 成行原価 và 実際原価: 成行原価 là chi phí giả định được kỹ sư thiết kế bóc tách từ bản vẽ trước khi sản xuất, còn 実際原価 là số liệu kế toán tổng hợp sau khi nhà xưởng đã vận hành gia công.","Quy trình quản lý chi phí mục tiêu (原価企画 - Target Costing): Sau khi xác định khoảng cách giữa 成行原価 (cao) và 許容原価 (thấp), nhóm phát triển áp dụng phương pháp VE (Value Engineering) để cắt giảm chi phí sao cho đạt được 目標原価.","Bản chất của Cost Review (コストレビュー): Là các cột mốc đánh giá chi phí ở từng giai đoạn (thiết kế ý tưởng, thiết kế cơ bản, thiết kế chi tiết, chế tạo thử) nhằm ngăn chặn việc đưa các bản vẽ vượt quá 目標原価 vào sản xuất hàng loạt.","So sánh với 見積原価 (Chi phí ước tính): 見積原価 là ước tính giá thành để báo giá cho khách hàng trước khi ký hợp đồng, cũng được kỹ sư lập dựa trên bản vẽ phác thảo nhưng mang mục đích thương mại thay vì kiểm soát phát triển nội bộ."],"exam_traps":["Đồng nhất 実際原価 với 成行原価.","Nhầm 許容原価 với 目標原価.","Nhầm chi phí tính từ bản vẽ với chi phí thực tế."],"vocabulary":[{"word":"製品開発","reading":"せいひんかいはつ","meaning":"phát triển sản phẩm"},{"word":"原価概念","reading":"げんかがいねん","meaning":"khái niệm chi phí"},{"word":"成行原価","reading":"なりゆきげんか","meaning":"chi phí thành hành"},{"word":"現状レベル","reading":"げんじょうレベル","meaning":"trình độ hiện tại"},{"word":"図面","reading":"ずめん","meaning":"bản vẽ"},{"word":"積み上げる","reading":"つみあげる","meaning":"tích lũy"},{"word":"許容原価","reading":"きょようげんか","meaning":"chi phí cho phép"},{"word":"予定価格","reading":"よていかかく","meaning":"giá kế hoạch"},{"word":"目標利益","reading":"もくひょうりえき","meaning":"lợi nhuận mục tiêu"},{"word":"目標原価","reading":"もくひょうげんか","meaning":"chi phí mục tiêu"},{"word":"コストレビュー","reading":"コストレビュー","meaning":"xem xét chi phí"},{"word":"実際原価","reading":"じっさいげんか","meaning":"chi phí thực tế"},{"word":"見積原価","reading":"みつもりげんか","meaning":"chi phí ước tính"},{"word":"差し引く","reading":"さしひく","meaning":"trừ đi"},{"word":"設計技術者","reading":"せっけいぎじゅつしゃ","meaning":"kỹ sư thiết kế"},{"word":"原価低減","reading":"げんかていげん","meaning":"giảm chi phí"},{"word":"見積り","reading":"みつもり","meaning":"ước tính"},{"word":"利益","reading":"りえき","meaning":"lợi nhuận"},{"word":"市場","reading":"しじょう","meaning":"thị trường"},{"word":"競争","reading":"きょうそう","meaning":"cạnh tranh"}]},{"id":"32","chapter":"2.原価管理","question":{"japanese":"標準原価計算の管理サイクルにおけるステップに関する記述として最も不適切なものは、次のうちどれか。なお、ステップは、ア→イ→ウ→エの順である。","vietnamese":"Trong các mô tả về các bước trong chu trình quản lý của tính giá thành chuẩn, mô tả nào KHÔNG phù hợp nhất? Biết các bước theo thứ tự ア→イ→ウ→エ.","furigana":"標準[ひょうじゅん]原価[げんか]計算[けいさん]の管理[かんり]サイクルにおけるステップに関する[かんする]記述[きじゅつ]として最も[もっとも]不適切[ふてきせつ]なものは、次[つぎ]のうちどれか。なお、ステップは、ア→イ→ウ→エの順[じゅん]である。"},"options":[{"key":"ア","japanese":"原価標準の設定","vietnamese":"Thiết lập tiêu chuẩn chi phí","furigana":"原価[げんか]標準[ひょうじゅん]の設定[せってい]"},{"key":"イ","japanese":"生産活動の実施と原価の見積り","vietnamese":"Thực hiện hoạt động sản xuất và ước tính chi phí","furigana":"生産[せいさん]活動[かつどう]の実施[じっし]と原価[げんか]の見積り[みつもり]"},{"key":"ウ","japanese":"標準原価と実際原価の差異分析・原因の追求","vietnamese":"Phân tích chênh lệch giữa chi phí chuẩn và thực tế, truy tìm nguyên nhân","furigana":"標準[ひょうじゅん]原価[げんか]と実際[じっさい]原価[げんか]の差異[さい]分析[ぶんせき]・原因[げんいん]の追求[ついきゅう]"},{"key":"エ","japanese":"原価標準の改定、改善案や是正措置の策定・実行","vietnamese":"Sửa đổi tiêu chuẩn chi phí, lập và thực hiện phương án cải tiến/biện pháp khắc phục","furigana":"原価[げんか]標準[ひょうじゅん]の改定[かいてい]、改善[かいぜん]案[あん]や是正[ぜせい]措置[そち]の策定[さくてい]・実行[じっこう]"}],"correct_answer":"イ","explanation":{"correct_reason":"Sau khi thiết lập 原価標準, bước tiếp theo là thực hiện sản xuất và TÍNH TOÁN/THU THẬP chi phí thực tế (原価の計算・把握), không phải 原価の見積り (ước tính). Ước tính là hoạt động ở giai đoạn trước/khác, không thuộc bước này.","incorrect_reasons":{"ア":"Sai vì 原価標準の設定 là bước đầu đúng.","イ":"Đây là đáp án đúng vì phải là 実際原価の計算・把握 chứ không phải 見積り.","ウ":"Sai vì phân tích chênh lệch và truy nguyên nhân là bước đúng.","エ":"Sai vì sửa tiêu chuẩn và thực hiện biện pháp là bước cuối đúng."}},"key_knowledge":["Chu trình quản lý chi phí chuẩn (標準原価計算の管理サイクル) vận hành theo đúng chu trình PDCA gồm 4 bước nối tiếp: Thiết lập chuẩn (Plan) → Thu thập chi phí thực tế (Do) → Phân tích chênh lệch (Check) → Thực hiện biện pháp khắc phục (Action).","Bước 1 - Thiết lập tiêu chuẩn chi phí (原価標準の設定): Xác định lượng nguyên vật liệu, đơn giá và số giờ công tiêu chuẩn (標準作業時間) để hoàn thành một đơn vị sản phẩm trong điều kiện sản xuất bình thường.","Bước 2 - Thực hiện sản xuất và tính toán chi phí thực tế (実際原価の算定・把握): Ghi nhận toàn bộ chi phí thực tế phát sinh (thời gian làm việc, lượng vật tư tiêu hao) sau khi sản xuất xong, hoàn toàn không phải là ước tính (見積り).","Phân biệt chi phí ước tính (見積原価) và chi phí thực tế (実際原価): Ước tính là con số dự đoán sơ bộ phục vụ báo giá hoặc lập kế hoạch từ trước, còn chi phí thực tế là con số phát sinh thật sự dùng để đo lường hiệu quả quản lý.","Bước 3 - Phân tích sai lệch chi phí (原価差異分析) và tìm nguyên nhân: So sánh giá thành chuẩn với giá thành thực tế để bóc tách thành sai lệch về giá (価格差異) và sai lệch về lượng/thời gian tiêu hao (数量差異・作業時間差異).","Phân loại nguyên nhân sai lệch: Cần truy tìm xem sai lệch do yếu tố nội bộ nhà máy (như tỷ lệ phế phẩm cao, thao tác công nhân chậm) hay do yếu tố bên ngoài (biến động giá nguyên vật liệu trên thị trường).","Bước 4 - Khắc phục và sửa đổi chuẩn (是正措置の実行・原価標準の改定): Triển khai các biện pháp loại bỏ lãng phí tại hiện trường xưởng sản xuất, đồng thời cập nhật lại định mức chuẩn nếu quy trình công nghệ hoặc mặt bằng giá cả thay đổi căn bản.","Ý nghĩa cốt lõi của tính giá thành chuẩn: Không chỉ dừng lại ở việc hạch toán sổ sách mà trọng tâm là kiểm soát chi phí (原価統制 - Cost Control) và thúc đẩy hoạt động cắt giảm chi phí (原価低減)."],"exam_traps":["Đánh tráo 見積り với 計算・把握.","Đảo thứ tự các bước.","Bỏ bước 差異分析."],"vocabulary":[{"word":"標準原価計算","reading":"ひょうじゅんげんかけいさん","meaning":"tính giá thành chuẩn"},{"word":"管理サイクル","reading":"かんりサイクル","meaning":"chu trình quản lý"},{"word":"ステップ","reading":"ステップ","meaning":"bước"},{"word":"原価標準","reading":"げんかひょうじゅん","meaning":"tiêu chuẩn chi phí"},{"word":"設定","reading":"せってい","meaning":"thiết lập"},{"word":"見積り","reading":"みつもり","meaning":"ước tính"},{"word":"差異分析","reading":"さいぶんせき","meaning":"phân tích chênh lệch"},{"word":"追及","reading":"ついきゅう","meaning":"truy tìm"},{"word":"改定","reading":"かいてい","meaning":"sửa đổi"},{"word":"是正措置","reading":"ぜせいそち","meaning":"biện pháp khắc phục"},{"word":"策定","reading":"さくてい","meaning":"lập kế hoạch"},{"word":"実際原価","reading":"じっさいげんか","meaning":"chi phí thực tế"},{"word":"追求","reading":"ついきゅう","meaning":"truy tìm"},{"word":"実行","reading":"じっこう","meaning":"thực hiện"},{"word":"把握","reading":"はあく","meaning":"nắm bắt"},{"word":"差異","reading":"さい","meaning":"chênh lệch"},{"word":"標準","reading":"ひょうじゅん","meaning":"tiêu chuẩn"},{"word":"実際","reading":"じっさい","meaning":"thực tế"},{"word":"原因","reading":"げんいん","meaning":"nguyên nhân"},{"word":"改善","reading":"かいぜん","meaning":"cải tiến"}]},{"id":"33","chapter":"2.原価管理","question":{"japanese":"目標原価の設定方法に関する記述として最も不適切なものは、次のうちどれか。","vietnamese":"Trong các mô tả về phương pháp thiết lập chi phí mục tiêu, mô tả nào KHÔNG phù hợp nhất?","furigana":"目標[もくひょう]原価[げんか]の設定[せってい]方法[ほうほう]に関する[かんする]記述[きじゅつ]として最も[もっとも]不適切[ふてきせつ]なものは、次[つぎ]のうちどれか。"},"options":[{"key":"ア","japanese":"積上げ法では、自社の技術レベル、生産能力などを勘案して、目標原価を設定する。","vietnamese":"Phương pháp tích lũy thiết lập chi phí mục tiêu có xét đến trình độ kỹ thuật, năng lực sản xuất của công ty.","furigana":"積上げ[つみあげ]法[ほう]では、自社[じしゃ]の技術[ぎじゅつ]レベル、生産[せいさん]能力[のうりょく]などを勘案[かんあん]して、目標[もくひょう]原価[げんか]を設定[せってい]する。"},{"key":"イ","japanese":"割付法では、市場における競合製品の売価などを参考にして、予定売価を決め、そこから一定利益を確保するために必要となる原価を目標原価とする。","vietnamese":"Phương pháp phân bổ tham khảo giá bán sản phẩm cạnh tranh trên thị trường, quyết định giá bán dự kiến, rồi coi chi phí cần để đảm bảo lợi nhuận nhất định là chi phí mục tiêu.","furigana":"割付法[わりつけほう]では、市場[しじょう]における競合[きょうごう]製品[せいひん]の売価[ばいか]などを参考[さんこう]にして、予定[よてい]売価[ばいか]を決め[きめ]、そこから一定[いってい]利益[りえき]を確保[かくほ]するために必要[ひつよう]となる原価[げんか]を目標[もくひょう]原価[げんか]とする。"},{"key":"ウ","japanese":"逆計算法では、製品に使用される材料消費量があらかじめ判明している場合、完成した製品の数から逆算して消費量を求め目標原価を決める。","vietnamese":"Phương pháp tính ngược: khi đã biết trước lượng nguyên liệu tiêu thụ dùng cho sản phẩm, tính ngược từ số sản phẩm hoàn thành để tìm lượng tiêu thụ và quyết định chi phí mục tiêu.","furigana":"逆[ぎゃく]計算法[けいさんほう]では、製品[せいひん]に使用[しよう]される材料[ざいりょう]消費量[しょうひりょう]があらかじめ判明[はんめい]している場合[ばあい]、完成[かんせい]した製品[せいひん]の数[かず]から逆算[ぎゃくさん]して消費量[しょうひりょう]を求め[もとめ]目標[もくひょう]原価[げんか]を決める[きめる]。"},{"key":"エ","japanese":"統合法では、積上げ法による現実的な原価と、割付法による理想的な原価を照らして実効性を検討し、目標となる原価を設定する。","vietnamese":"Phương pháp tích hợp đối chiếu chi phí thực tế từ phương pháp tích lũy và chi phí lý tưởng từ phương pháp phân bổ để xem xét tính khả thi, rồi thiết lập chi phí mục tiêu.","furigana":"統合法[とうごうほう]では、積上げ[つみあげ]法[ほう]による現実的[げんじつてき]な原価[げんか]と、割付法[わりつけほう]による理想的[りそうてき]な原価[げんか]を照らし[てらし]て実効性[じっこうせい]を検討[けんとう]し、目標[もくひょう]となる原価[げんか]を設定[せってい]する。"}],"correct_answer":"ウ","explanation":{"correct_reason":"逆計算法 (phương pháp tính ngược) là lấy giá bán/giá thị trường trừ lợi nhuận để tính ngược ra chi phí mục tiêu, không phải tính ngược lượng nguyên liệu tiêu thụ từ số sản phẩm hoàn thành.","incorrect_reasons":{"ア":"Sai vì 積上げ法 đúng là tích lũy theo trình độ kỹ thuật và năng lực sản xuất.","イ":"Sai vì 割付法 đúng là lấy giá bán dự kiến trừ lợi nhuận cần thiết.","ウ":"Đây là đáp án đúng vì mô tả 逆計算法 bị sai bản chất.","エ":"Sai vì 統合法 đúng là kết hợp 積上げ法 và 割付法."}},"key_knowledge":["Chi phí mục tiêu (目標原価 - Mokuhyou genka) là mức chi phí định mức được đặt ra trong giai đoạn phát triển và thiết kế sản phẩm mới, nhằm đảm bảo đạt được mục tiêu lợi nhuận khi tung ra thị trường.","Phương pháp tích lũy (積上げ法 - Tsumiage-hou): Tính toán từ dưới lên dựa trên năng lực sản xuất, trình độ kỹ thuật và định mức hao phí hiện tại của doanh nghiệp; phản ánh mức chi phí có tính hiện thực và khả thi cao trong thực tế.","Phương pháp phân bổ / khấu trừ (割付法 - Waritsuke-hou): Xuất phát từ thị trường bên ngoài bằng công thức: Giá bán dự kiến (予定売価) − Lợi nhuận mục tiêu (目標利益) = Chi phí mục tiêu. Đây là cách tiếp cận mang tính lý tưởng để cạnh tranh trên thị trường.","Phương pháp tính ngược (逆計算法 - Gyakukeisan-hou): Về bản chất trong thiết lập chi phí mục tiêu, đây là tên gọi khác hoặc biến thể của 割付法, tính ngược từ giá bán thị trường và biên lợi nhuận mong muốn về mức chi phí cho phép, hoàn toàn không phải tính toán lượng vật tư hao hụt.","Lưu ý phân biệt: Việc lấy số lượng thành phẩm nhân định mức để ra tổng lượng tiêu hao nguyên liệu thuộc về phương pháp tính lượng tiêu hao (消費量計算), không phải phương pháp thiết lập chi phí mục tiêu (目標原価設定).","Phương pháp tích hợp (統合法 - Tougou-hou): Kết hợp giữa phương pháp tích lũy (積上げ法 - góc nhìn nội bộ/hiện thực) và phương pháp phân bổ (割付法 - góc nhìn thị trường/lý tưởng) để cân đối, giải quyết chênh lệch và đưa ra mục tiêu vừa có tính cạnh tranh vừa có tính khả thi.","Mục tiêu cốt lõi của quản lý chi phí mục tiêu (原価企画 - Target Costing): Cắt giảm chi phí ngay từ khâu nghiên cứu phát triển (R&D) và thiết kế thông qua kỹ thuật giá trị (VE - Value Engineering), vì 80% chi phí sản phẩm đã bị khóa chặt ở khâu này trước khi bắt đầu sản xuất hàng loạt."],"exam_traps":["Mô tả 逆計算法 thành tính ngược lượng nguyên liệu.","Nhầm 割付法 với 積上げ法.","Nhầm 統合法 với 逆計算法."],"vocabulary":[{"word":"目標原価","reading":"もくひょうげんか","meaning":"chi phí mục tiêu"},{"word":"設定方法","reading":"せっていほうほう","meaning":"phương pháp thiết lập"},{"word":"積上げ法","reading":"つみあげほう","meaning":"phương pháp tích lũy"},{"word":"技術レベル","reading":"ぎじゅつレベル","meaning":"trình độ kỹ thuật"},{"word":"生産能力","reading":"せいさんのうりょく","meaning":"năng lực sản xuất"},{"word":"勘案","reading":"かんあん","meaning":"xem xét, tính đến"},{"word":"割付法","reading":"わりつけほう","meaning":"phương pháp phân bổ"},{"word":"競合製品","reading":"きょうごうせいひん","meaning":"sản phẩm cạnh tranh"},{"word":"予定売価","reading":"よていばいか","meaning":"giá bán dự kiến"},{"word":"逆計算法","reading":"ぎゃくけいさんほう","meaning":"phương pháp tính ngược"},{"word":"材料消費量","reading":"ざいりょうしょうひりょう","meaning":"lượng nguyên liệu tiêu thụ"},{"word":"統合法","reading":"とうごうほう","meaning":"phương pháp tích hợp"},{"word":"実効性","reading":"じっこうせい","meaning":"tính khả thi"},{"word":"消費量","reading":"しょうひりょう","meaning":"lượng tiêu thụ"},{"word":"現実的","reading":"げんじつてき","meaning":"mang tính thực tế"},{"word":"理想的","reading":"りそうてき","meaning":"mang tính lý tưởng"},{"word":"利益","reading":"りえき","meaning":"lợi nhuận"},{"word":"市場","reading":"しじょう","meaning":"thị trường"},{"word":"売価","reading":"ばいか","meaning":"giá bán"},{"word":"製品","reading":"せいひん","meaning":"sản phẩm"}]},{"id":"34","chapter":"3.納期管理","question":{"japanese":"納期管理の考え方に関する記述として最も不適切なものは、次のうちどれか。","vietnamese":"Trong các mô tả về quan điểm quản lý thời hạn giao hàng, mô tả nào KHÔNG phù hợp nhất?","furigana":"納期[のうき]管理[かんり]の考え方[かんがえかた]に関する[かんする]記述[きじゅつ]として最も[もっとも]不適切[ふてきせつ]なものは、次[つぎ]のうちどれか。"},"options":[{"key":"ア","japanese":"納期管理の目的は、決められた納期どおりに品物を顧客又は後工程に納入することである。","vietnamese":"Mục đích quản lý thời hạn giao hàng là giao hàng cho khách hoặc công đoạn sau đúng thời hạn đã định.","furigana":"納期[のうき]管理[かんり]の目的[もくてき]は、決め[きめ]られた納期[のうき]どおりに品物[しなもの]を顧客[こきゃく]又は[または]後工程[あとこうてい]に納入[のうにゅう]することである。"},{"key":"イ","japanese":"決められた納期どおりとは、早期納入を防ぐことも含まれる。","vietnamese":"Đúng thời hạn đã định bao gồm cả việc ngăn giao hàng sớm.","furigana":"決め[きめ]られた納期[のうき]どおりとは、早期[そうき]納入[のうにゅう]を防ぐ[ふせぐ]ことも含ま[ふくま]れる。"},{"key":"ウ","japanese":"納期を守ることにより、販売活動を有利に進めることができる。","vietnamese":"Giữ đúng thời hạn giao hàng giúp hoạt động bán hàng thuận lợi hơn.","furigana":"納期[のうき]を守る[まもる]ことにより、販売[はんばい]活動[かつどう]を有利[ゆうり]に進める[すすめる]ことができる。"},{"key":"エ","japanese":"個別受注生産の納期管理では、生産プロセス全体で一定の生産速度を維持することを重視した管理が最も重要である。","vietnamese":"Trong quản lý thời hạn giao hàng của sản xuất đơn chiếc theo đơn đặt hàng, quản lý coi trọng duy trì tốc độ sản xuất không đổi trên toàn quy trình là quan trọng nhất.","furigana":"個別[こべつ]受注[じゅちゅう]生産[せいさん]の納期[のうき]管理[かんり]では、生産[せいさん]プロセス全体[ぜんたい]で一定[いってい]の生産[せいさん]速度[そくど]を維持[いじ]することを重視[じゅうし]した管理[かんり]が最も[もっとも]重要[じゅうよう]である。"}],"correct_answer":"エ","explanation":{"correct_reason":"個別受注生産 có chủng loại và quy trình khác nhau, không thể duy trì tốc độ sản xuất không đổi trên toàn quy trình. Trọng tâm là quản lý tiến độ theo từng đơn hàng, đảm bảo từng mốc thời gian.","incorrect_reasons":{"ア":"Sai vì giao đúng hạn cho khách/công đoạn sau là mục đích đúng.","イ":"Sai vì kiểm soát cả giao sớm để tránh tồn kho và xáo trộn kế hoạch là đúng.","ウ":"Sai vì giữ đúng hạn giúp tăng lợi thế cạnh tranh trong bán hàng.","エ":"Đây là đáp án đúng vì sản xuất đơn chiếc theo đơn không dựa trên tốc độ không đổi."}},"key_knowledge":["Khái niệm quản lý thời hạn giao hàng (納期管理 - Nouki kanri): Là hoạt động nhằm đảm bảo sản xuất và giao sản phẩm đúng số lượng, đúng chất lượng vào đúng thời điểm đã cam kết với khách hàng bên ngoài hoặc công đoạn sau (後工程 - Ato koutei).","Khái niệm 'đúng hạn' (納期どおり): Không chỉ đơn thuần là ngăn chặn việc giao trễ (納期遅延), mà còn bắt buộc phải kiểm soát, ngăn chặn việc giao hàng quá sớm (早期納入).","Tác hại của việc giao hàng sớm (早期納入): Giao sớm khiến công đoạn sau hoặc khách hàng bị ứ đọng tồn kho chưa cần thiết, tốn diện tích lưu kho và vi phạm nguyên tắc sản xuất Just-In-Time (JIT).","Tác động đến hoạt động bán hàng: Giữ vững uy tín về thời hạn giao hàng là yếu tố cạnh tranh phi giá cả cực kỳ quan trọng, giúp bộ phận kinh doanh dễ đàm phán và duy trì quan hệ lâu dài với khách hàng.","Quản lý thời hạn trong sản xuất đơn chiếc theo đơn (個別受注生産 - Kobetsu juchuu seisan): Mỗi sản phẩm có quy cách và tiến trình riêng biệt, do đó trọng tâm quản lý là bám sát tiến độ từng đơn hàng theo mốc (日程計画 / マイルストーン), tuyệt đối không thể áp dụng duy trì tốc độ sản xuất không đổi trên toàn bộ quy trình.","Quản lý duy trì tốc độ sản xuất cố định: Phương pháp duy trì tốc độ đồng nhất (一定の生産速度) dựa vào nhịp sản xuất (タクトタイム - Takt time) chỉ áp dụng cho sản xuất lặp lại, sản xuất hàng khối lượng lớn dự báo (見込生産 / 繰返生産).","Biện pháp ứng phó nguy cơ chậm trễ: Cần trực quan hóa tiến độ hàng ngày (進捗管理の見える化) để phát hiện sớm sự chậm trễ, từ đó kịp thời tăng ca, điều chuyển nhân lực hoặc nhờ gia công ngoài (外注 - Gaichuu) nhằm bảo toàn ngày giao hàng."],"exam_traps":["Áp mô hình tốc độ đồng nhất của sản xuất liên tục vào 個別受注生産.","Bỏ qua khía cạnh ngăn giao sớm.","Nhầm 納期管理 với 工程管理."],"vocabulary":[{"word":"納期管理","reading":"のうきかんり","meaning":"quản lý thời hạn giao hàng"},{"word":"納期","reading":"のうき","meaning":"thời hạn giao hàng"},{"word":"納入","reading":"のうにゅう","meaning":"giao hàng, cung cấp"},{"word":"後工程","reading":"あとこうてい","meaning":"công đoạn sau"},{"word":"早期納入","reading":"そうきのうにゅう","meaning":"giao hàng sớm"},{"word":"販売活動","reading":"はんばいかつどう","meaning":"hoạt động bán hàng"},{"word":"個別受注生産","reading":"こべつじゅちゅうせいさん","meaning":"sản xuất đơn chiếc theo đơn đặt hàng"},{"word":"生産プロセス","reading":"せいさんプロセス","meaning":"quy trình sản xuất"},{"word":"生産速度","reading":"せいさんそくど","meaning":"tốc độ sản xuất"},{"word":"早期","reading":"そうき","meaning":"sớm"},{"word":"見込生産","reading":"みこみせいさん","meaning":"sản xuất dự báo (theo dự đoán)"},{"word":"一定","reading":"いってい","meaning":"nhất định, không đổi"},{"word":"速度","reading":"そくど","meaning":"tốc độ"},{"word":"最重要","reading":"さいじゅうよう","meaning":"quan trọng nhất"},{"word":"優先","reading":"ゆうせん","meaning":"ưu tiên"},{"word":"顧客","reading":"こきゃく","meaning":"khách hàng"},{"word":"品物","reading":"しなもの","meaning":"hàng hóa, sản phẩm"},{"word":"生産計画","reading":"せいさんけいかく","meaning":"kế hoạch sản xuất"},{"word":"工程","reading":"こうてい","meaning":"công đoạn"},{"word":"リードタイム","reading":"リードタイム","meaning":"thời gian dẫn (lead time)"}]},{"id":"35","chapter":"3.納期管理","question":{"japanese":"設計が完成したとしても、その設計に基づいて部品の調達や生産、加工、組立てを行っていくうちに、設計どおりの部品や製品ができてこない、製品の（ A ）が実現できないことがある。それは、設計図どおりの加工工程が難しくてできないとか、設計図どおりに組み立てることが物理的にできないなどという設計の不具合が原因で発生する場合である。\n設計の不具合を発生させる要因は、（B）、設計図面の表記間違い、原材料の選択間違いなどである。これらの要因は主として、設計者の設計作業に要因があるので、設計の不具合を回避する対策として、設計の（C）、設計を確認するための（D）、試作、検証などの対策が必要になる。\n＜用語＞ 1.検図 2.計算違い 3.機能 4.標準化","vietnamese":"Ngay cả khi thiết kế hoàn thành, trong quá trình mua linh kiện, sản xuất, gia công, lắp ráp theo thiết kế, có thể không tạo ra linh kiện/sản phẩm đúng thiết kế, tức không thực hiện được (A) của sản phẩm. Điều này xảy ra do lỗi thiết kế như gia công theo bản vẽ quá khó hoặc lắp ráp theo bản vẽ không khả thi về mặt vật lý.\nCác yếu tố gây lỗi thiết kế gồm (B), ghi sai trên bản vẽ, chọn sai nguyên liệu. Vì nguyên nhân chủ yếu nằm ở công việc thiết kế của kỹ sư, biện pháp tránh lỗi thiết kế cần (C) thiết kế, (D) để kiểm tra thiết kế, chế tạo thử, kiểm chứng.\n<Thuật ngữ> 1. kiểm tra bản vẽ 2. tính sai 3. chức năng 4. tiêu chuẩn hóa","furigana":"設計[せっけい]が完成[かんせい]したとしても、その設計[せっけい]に基づい[もとづい]て部品[ぶひん]の調達[ちょうたつ]や生産[せいさん]、加工[かこう]、組立て[くみたて]を行っ[おこなっ]ていくうちに、設計[せっけい]どおりの部品[ぶひん]や製品[せいひん]ができてこない、製品[せいひん]の（ A ）が実現[じつげん]できないことがある。それは、設計[せっけい]図[ず]どおりの加工[かこう]工程[こうてい]が難しく[むずかしく]てできないとか、設計[せっけい]図[ず]どおりに組み立てる[くみたてる]ことが物理的[ぶつりてき]にできないなどという設計[せっけい]の不具合[ふぐあい]が原因[げんいん]で発生[はっせい]する場合[ばあい]である。\n設計[せっけい]の不具合[ふぐあい]を発生[はっせい]させる要因[よういん]は、（B）、設計[せっけい]図面[ずめん]の表記[ひょうき]間違い[まちがい]、原材料[げんざいりょう]の選択[せんたく]間違い[まちがい]などである。これらの要因[よういん]は主として[しゅとして]、設計者[せっけいしゃ]の設計[せっけい]作業[さぎょう]に要因[よういん]があるので、設計[せっけい]の不具合[ふぐあい]を回避[かいひ]する対策[たいさく]として、設計[せっけい]の（C）、設計[せっけい]を確認[かくにん]するための（D）、試作[しさく]、検証[けんしょう]などの対策[たいさく]が必要[ひつよう]になる。\n＜用語[ようご]＞ 1.検[けん]図[ず] 2.計算[けいさん]違い[ちがい] 3.機能[きのう] 4.標準化[ひょうじゅんか]"},"options":[{"key":"ア","japanese":"A:4 B:2 C:3 D:1","vietnamese":"A:4 B:2 C:3 D:1","furigana":"A:4 B:2 C:3 D:1"},{"key":"イ","japanese":"A:3 B:2 C:1 D:4","vietnamese":"A:3 B:2 C:1 D:4","furigana":"A:3 B:2 C:1 D:4"},{"key":"ウ","japanese":"A:3 B:2 C:4 D:1","vietnamese":"A:3 B:2 C:4 D:1","furigana":"A:3 B:2 C:4 D:1"},{"key":"エ","japanese":"A:4 B:1 C:3 D:2","vietnamese":"A:4 B:1 C:3 D:2","furigana":"A:4 B:1 C:3 D:2"}],"correct_answer":"ウ","explanation":{"correct_reason":"A là 機能 (chức năng sản phẩm không đạt). B là 計算違い (tính sai). C là 標準化 (tiêu chuẩn hóa thiết kế). D là 検図 (kiểm tra bản vẽ). Tổ hợp đúng: A:3, B:2, C:4, D:1.","incorrect_reasons":{"ア":"Sai vì A phải là 機能 (3), C phải là 標準化 (4).","イ":"Sai vì C phải là 標準化 (4), D phải là 検図 (1).","ウ":"Đây là đáp án đúng.","エ":"Sai vì B phải là 計算違い, C và D bị đảo."}},"key_knowledge":["Lỗi thiết kế (設計の不具合) là tình trạng bản vẽ không thể gia công thực tế, không lắp ráp được hoặc sản phẩm làm ra không đạt được chức năng (機能) yêu cầu ban đầu.","Nguyên nhân gây ra lỗi thiết kế (設計の不具合の要因) chủ yếu do con người, bao gồm: tính toán sai (計算違い) về độ bền/kích thước, ghi sai kích thước trên bản vẽ (設計図面の表記間違い), và chọn sai nguyên vật liệu (原材料の選択間違い).","Tiêu chuẩn hóa thiết kế (設計の標準化) là giải pháp dùng lại các module, chi tiết hoặc quy tắc đã được kiểm chứng; giúp giảm thiểu việc phải tính toán từ đầu và hạn chế tối đa lỗi thiết kế.","Kiểm tra bản vẽ (検図 - Kenzu) là khâu đánh giá độc lập của người thứ hai (thường là cấp trên hoặc kỹ sư phụ trách) nhằm rà soát tính logic, kích thước, dung sai trước khi phát hành bản vẽ xuống xưởng.","Chế tạo thử và kiểm chứng (試作・検証) là bước làm mẫu thực tế để xác nhận tính khả thi khi lắp ráp và kiểm tra xem chức năng (機能) của sản phẩm có đáp ứng đúng yêu cầu hay không trước khi sản xuất hàng loạt.","Phân biệt (標準化) và (検図): Tiêu chuẩn hóa là biện pháp phòng ngừa từ gốc trong quá trình lập thiết kế, còn kiểm tra bản vẽ là rào chắn kiểm soát chất lượng đầu ra của bản vẽ.","Lỗi thiết kế nếu phát hiện muộn ở khâu gia công/lắp ráp sẽ tạo ra hiện tượng làm lại (手戻り - Temodori), gây lãng phí chi phí và trực tiếp dẫn đến chậm tiến độ giao hàng (納期遅れ)."],"exam_traps":["Đảo 機能 với 標準化.","Đảo 検図 với 標準化.","Thay 計算違い bằng 検図."],"vocabulary":[{"word":"設計の不具合","reading":"せっけいのふぐあい","meaning":"lỗi thiết kế"},{"word":"調達","reading":"ちょうたつ","meaning":"mua sắm"},{"word":"加工","reading":"かこう","meaning":"gia công"},{"word":"組立て","reading":"くみたて","meaning":"lắp ráp"},{"word":"機能","reading":"きのう","meaning":"chức năng"},{"word":"計算違い","reading":"けいさんちがい","meaning":"tính sai"},{"word":"表記間違い","reading":"ひょうきまちがい","meaning":"ghi sai"},{"word":"原材料","reading":"げんざいりょう","meaning":"nguyên liệu"},{"word":"標準化","reading":"ひょうじゅんか","meaning":"tiêu chuẩn hóa"},{"word":"検図","reading":"けんず","meaning":"kiểm tra bản vẽ"},{"word":"試作","reading":"しさく","meaning":"chế tạo thử"},{"word":"検証","reading":"けんしょう","meaning":"kiểm chứng"},{"word":"不具合","reading":"ふぐあい","meaning":"lỗi, sự cố, khiếm khuyết"},{"word":"物理的","reading":"ぶつりてき","meaning":"về mặt vật lý"},{"word":"表記","reading":"ひょうき","meaning":"ghi chép, ký hiệu"},{"word":"回避","reading":"かいひ","meaning":"tránh, phòng tránh"},{"word":"設計者","reading":"せっけいしゃ","meaning":"nhà thiết kế"},{"word":"部品","reading":"ぶひん","meaning":"linh kiện"},{"word":"生産","reading":"せいさん","meaning":"sản xuất"},{"word":"設計図","reading":"せっけいず","meaning":"bản vẽ thiết kế"}]},{"id":"36","chapter":"3.納期管理","question":{"japanese":"納期遅延や日程遅延を解決する手順として最も適切なものは、次のうちどれか。","vietnamese":"Trình tự nào phù hợp nhất để giải quyết chậm giao hàng và chậm tiến độ?","furigana":"納期[のうき]遅延[ちえん]や日程[にってい]遅延[ちえん]を解決[かいけつ]する手順[てじゅん]として最も[もっとも]適切[てきせつ]なものは、次[つぎ]のうちどれか。"},"options":[{"key":"ア","japanese":"計画と実績の差異分析→納期差異原因の追究→納期差異の分析→対策の立案・実施→再発防止対策","vietnamese":"Phân tích chênh lệch kế hoạch và thực tế → Truy tìm nguyên nhân chênh lệch giao hàng → Phân tích chênh lệch giao hàng → Lập và thực hiện biện pháp → Biện pháp phòng tái phát","furigana":"計画[けいかく]と実績[じっせき]の差異[さい]分析[ぶんせき]→納期[のうき]差異[さい]原因[げんいん]の追究[ついきゅう]→納期[のうき]差異[さい]の分析[ぶんせき]→対策[たいさく]の立案[りつあん]・実施[じっし]→再発[さいはつ]防止[ぼうし]対策[たいさく]"},{"key":"イ","japanese":"計画と実績の差異分析→納期差異の分析→納期差異原因の追究→対策の立案・実施→再発防止対策","vietnamese":"Phân tích chênh lệch kế hoạch và thực tế → Phân tích chênh lệch giao hàng → Truy tìm nguyên nhân chênh lệch → Lập và thực hiện biện pháp → Biện pháp phòng tái phát","furigana":"計画[けいかく]と実績[じっせき]の差異[さい]分析[ぶんせき]→納期[のうき]差異[さい]の分析[ぶんせき]→納期[のうき]差異[さい]原因[げんいん]の追究[ついきゅう]→対策[たいさく]の立案[りつあん]・実施[じっし]→再発[さいはつ]防止[ぼうし]対策[たいさく]"},{"key":"ウ","japanese":"納期差異の分析→計画と実績の差異分析→納期差異原因の追究→対策の立案・実施→再発防止対策","vietnamese":"Phân tích chênh lệch giao hàng → Phân tích chênh lệch kế hoạch và thực tế → Truy tìm nguyên nhân → Lập và thực hiện biện pháp → Biện pháp phòng tái phát","furigana":"納期[のうき]差異[さい]の分析[ぶんせき]→計画[けいかく]と実績[じっせき]の差異[さい]分析[ぶんせき]→納期[のうき]差異[さい]原因[げんいん]の追究[ついきゅう]→対策[たいさく]の立案[りつあん]・実施[じっし]→再発[さいはつ]防止[ぼうし]対策[たいさく]"},{"key":"エ","japanese":"納期差異の分析→計画と実績の差異分析→納期差異原因の追究→再発防止対策→対策の立案・実施","vietnamese":"Phân tích chênh lệch giao hàng → Phân tích chênh lệch kế hoạch và thực tế → Truy tìm nguyên nhân → Biện pháp phòng tái phát → Lập và thực hiện biện pháp","furigana":"納期[のうき]差異[さい]の分析[ぶんせき]→計画[けいかく]と実績[じっせき]の差異[さい]分析[ぶんせき]→納期[のうき]差異[さい]原因[げんいん]の追究[ついきゅう]→再発[さいはつ]防止[ぼうし]対策[たいさく]→対策[たいさく]の立案[りつあん]・実施[じっし]"}],"correct_answer":"イ","explanation":{"correct_reason":"Quy trình chuẩn: phân tích chênh lệch kế hoạch và thực tế → phân tích chênh lệch giao hàng (xác định mức chậm) → truy tìm nguyên nhân → lập và thực hiện biện pháp → phòng tái phát. Vì vậy イ đúng.","incorrect_reasons":{"ア":"Sai vì truy nguyên nhân phải sau khi phân tích chênh lệch, không phải trước.","イ":"Đây là đáp án đúng.","ウ":"Sai vì phải phân tích chênh lệch kế hoạch/thực tế trước.","エ":"Sai vì phòng tái phát phải sau khi thực hiện biện pháp."}},"key_knowledge":["Quy trình chuẩn 5 bước giải quyết trễ hạn (納期遅延・日程遅延解決の手順): 1. Phân tích chênh lệch kế hoạch - thực tế → 2. Phân tích chênh lệch kỳ hạn giao hàng → 3. Truy tìm nguyên nhân chênh lệch → 4. Lập và thực hiện biện pháp đối ứng → 5. Biện pháp phòng ngừa tái phát.","Bước 1 - Phân tích chênh lệch kế hoạch và thực tế (計画と実績の差異分析): Là bước nhận diện vấn đề ban đầu bằng cách đối chiếu tiến độ thực tế với kế hoạch sản xuất để phát hiện sớm các mắt xích đang bị đình trệ.","Bước 2 - Phân tích chênh lệch kỳ hạn giao hàng (納期差異の分析): Sau khi phát hiện có sai lệch, tiến hành đo lường cụ thể mức độ ảnh hưởng đến ngày giao hàng cuối cùng (trễ bao nhiêu giờ/ngày, ảnh hưởng đến khách hàng hay đơn hàng nào).","Phân biệt 'Phân tích chênh lệch' (差異分析) và 'Truy tìm nguyên nhân' (原因追究): Phân tích chênh lệch nhằm làm rõ 'hiện trạng sai lệch bao nhiêu và ở đâu', còn truy tìm nguyên nhân là đào sâu 'tại sao lại xảy ra hiện tượng đó' (như do máy hỏng, thiếu nguyên liệu hay lỗi thao tác).","Bước 3 - Truy tìm nguyên nhân chênh lệch (納期差異原因の追究): Sử dụng các phương pháp như 5 Why (なぜなぜ分析) để tìm ra nguyên nhân gốc rễ (真因), tránh việc chỉ nhìn vào biểu hiện bề mặt.","Bước 4 - Lập và thực hiện biện pháp (対策の立案・実施): Đây là biện pháp xử lý tình huống khẩn cấp (応急対策) nhằm khắc phục ngay số lượng chậm trễ cho lô hàng hiện tại, ví dụ như bố trí làm tăng ca (残業), huy động thêm nhân lực hoặc chuyển một phần sang gia công ngoài (外注).","Bước 5 - Biện pháp phòng ngừa tái phát (再発防止対策): Bước cuối cùng mang tính lâu dài (恒久対策), tập trung vào chuẩn hóa quy trình (標準化), bảo dưỡng thiết bị định kỳ hoặc điều chỉnh lại thời gian chuẩn (標準時間) để lỗi không tái diễn ở các đơn hàng sau.","Ứng dụng thực tế tại nhà máy: Khi một chuyền bị trễ 3 ngày (差異分析), quản đốc xác định do máy dập bị sự cố liên tục (原因追究), lập tức cho chuyền làm thêm thứ Bảy để kịp giao hàng (対策実施), sau đó thiết lập quy trình kiểm tra bảo trì máy mỗi sáng (再発防止対策)."],"exam_traps":["Đảo bước phân tích chênh lệch và truy nguyên nhân.","Đặt phòng tái phát trước khi thực hiện biện pháp.","Gộp phân tích chênh lệch kế hoạch/thực tế với phân tích chênh lệch giao hàng."],"vocabulary":[{"word":"納期遅延","reading":"のうきちえん","meaning":"chậm giao hàng"},{"word":"日程遅延","reading":"にっていちえん","meaning":"chậm tiến độ"},{"word":"手順","reading":"てじゅん","meaning":"trình tự"},{"word":"差異分析","reading":"さいぶんせき","meaning":"phân tích chênh lệch"},{"word":"実績","reading":"じっせき","meaning":"thực tế, kết quả"},{"word":"原因の追究","reading":"げんいんのついきゅう","meaning":"truy tìm nguyên nhân"},{"word":"対策の立案","reading":"たいさくのりつあん","meaning":"lập biện pháp"},{"word":"再発防止対策","reading":"さいはつぼうしたいさく","meaning":"biện pháp phòng tái phát"},{"word":"追究","reading":"ついきゅう","meaning":"truy tìm"},{"word":"原因","reading":"げんいん","meaning":"nguyên nhân"},{"word":"立案","reading":"りつあん","meaning":"lập kế hoạch, soạn thảo"},{"word":"再発防止","reading":"さいはつぼうし","meaning":"phòng tái phát"},{"word":"対策","reading":"たいさく","meaning":"biện pháp"},{"word":"分析","reading":"ぶんせき","meaning":"phân tích"},{"word":"計画","reading":"けいかく","meaning":"kế hoạch"},{"word":"納期","reading":"のうき","meaning":"thời hạn giao hàng"},{"word":"回復","reading":"かいふく","meaning":"phục hồi"},{"word":"改善","reading":"かいぜん","meaning":"cải tiến"},{"word":"工程","reading":"こうてい","meaning":"công đoạn"}]},{"id":"37","chapter":"4.安全衛生","question":{"japanese":"安全衛生管理体制の構築に関する記述として不適切なものは、次のうちどれか。","vietnamese":"Trong các mô tả về xây dựng hệ thống quản lý an toàn vệ sinh, mô tả nào KHÔNG phù hợp?","furigana":"安全[あんぜん]衛生[えいせい]管理[かんり]体制[たいせい]の構築[こうちく]に関する[かんする]記述[きじゅつ]として不適切[ふてきせつ]なものは、次[つぎ]のうちどれか。"},"options":[{"key":"ア","japanese":"安全衛生管理体制については、労働安全衛生法第3章に安全管理体制に関する規制が定められている。","vietnamese":"Về hệ thống quản lý an toàn vệ sinh, chương 3 của Luật An toàn Vệ sinh Lao động quy định các quy chế về hệ thống quản lý an toàn.","furigana":"安全[あんぜん]衛生[えいせい]管理[かんり]体制[たいせい]については、労働[ろうどう]安全[あんぜん]衛生法[えいせいほう]第[だい]3章[しょう]に安全[あんぜん]管理[かんり]体制[たいせい]に関する[かんする]規制[きせい]が定め[さだめ]られている。"},{"key":"イ","japanese":"総括安全衛生管理者は、製造業では300人以上の事業場に選任が必要である。","vietnamese":"Tổng quản lý an toàn vệ sinh phải được bổ nhiệm ở cơ sở sản xuất từ 300 người trở lên trong ngành sản xuất.","furigana":"総括[そうかつ]安全[あんぜん]衛生[えいせい]管理者[かんりしゃ]は、製造[せいぞう]業[ぎょう]では300人[にん]以上[いじょう]の事業[じぎょう]場[じょう]に選任[せんにん]が必要[ひつよう]である。"},{"key":"ウ","japanese":"産業医は、全業種で10人以上の労働者を使用する事業場に1名選任しなければならない。","vietnamese":"Bác sĩ công nghiệp phải được chọn 1 người ở cơ sở sử dụng từ 10 lao động trở lên trong mọi ngành nghề.","furigana":"産業[さんぎょう]医[い]は、全業種[ぜんぎょうしゅ]で10人[にん]以上[いじょう]の労働者[ろうどうしゃ]を使用[しよう]する事業[じぎょう]場[じょう]に1名[めい]選任[せんにん]しなければならない。"},{"key":"エ","japanese":"労働災害の被災程度の大きさとして強度率が用いられる。","vietnamese":"Độ lớn mức độ bị tai nạn lao động được đo bằng tỷ lệ cường độ.","furigana":"労働[ろうどう]災害[さいがい]の被災[ひさい]程度[ていど]の大き[おおき]さとして強度率[きょうどりつ]が用い[もちい]られる。"}],"correct_answer":"ウ","explanation":{"correct_reason":"産業医 phải được chọn ở cơ sở sử dụng từ 50 lao động trở lên (và một số trường hợp đặc biệt), không phải 10 người. Vì vậy ウ không phù hợp.","incorrect_reasons":{"ア":"Sai vì quy định nằm ở chương 3 Luật An toàn Vệ sinh Lao động là đúng.","イ":"Sai vì 総括安全衛生管理者 ở ngành sản xuất cần từ 300 người là đúng.","ウ":"Đây là đáp án đúng vì ngưỡng là 50 người, không phải 10 người.","エ":"Sai vì 強度率 đúng là chỉ số mức độ nghiêm trọng tai nạn."}},"key_knowledge":["Khung pháp lý: Luật An toàn Vệ sinh Lao động (労働安全衛生法) dành riêng Chương 3 để quy định chặt chẽ về hệ thống tổ chức quản lý an toàn vệ sinh (安全衛生管理体制) trong các doanh nghiệp.","Bác sĩ công nghiệp (産業医 - Sangyō-i): Bắt buộc phải bổ nhiệm tại tất cả các cơ sở sản xuất kinh doanh có từ 50 lao động thường xuyên trở lên (50人以上), không phân biệt ngành nghề.","Chuyên trách bác sĩ công nghiệp (専任産業医): Khi cơ sở có từ 1.000 lao động trở lên (hoặc từ 500 lao động làm việc trong môi trường độc hại nguy hiểm), doanh nghiệp phải chỉ định bác sĩ công nghiệp làm việc chuyên trách thay vì hợp đồng bán thời gian.","Người xúc tiến an toàn vệ sinh (安全衛生推進者 / 衛生推進者): Bắt buộc bổ nhiệm tại các cơ sở có quy mô vừa và nhỏ từ 10 đến dưới 50 người (10人以上50人未満), dễ bị nhầm với quy mô chỉ định bác sĩ công nghiệp.","Tổng quản lý an toàn vệ sinh (総括安全衛生管理者): Thường do Giám đốc nhà máy (工場長) đảm nhiệm; trong ngành chế tạo (製造業) bắt buộc phải bổ nhiệm khi cơ sở đạt quy mô từ 300 lao động trở lên.","Cán bộ quản lý an toàn và vệ sinh (安全管理者・衛生管理者): Cũng giống như bác sĩ công nghiệp, hai vị trí này bắt buộc phải thiết lập tại các cơ sở có từ 50 lao động trở lên.","Tỷ lệ cường độ tai nạn (強度率 - Kyōdoritsu): Đại lượng đo lường độ lớn/mức độ nghiêm trọng của tai nạn lao động, tính bằng số ngày công lao động bị mất (労働損失日数) trên 1.000 tổng giờ làm việc.","Tỷ lệ tần suất tai nạn (度数率 - Dosūritsu): Đại lượng đo tần suất phát sinh tai nạn, tính bằng số ca tử vong hoặc thương tật nghỉ việc trên 1.000.000 tổng giờ làm việc (cần phân biệt rõ với 強度率 đo độ nặng nhẹ)."],"exam_traps":["Đổi ngưỡng 産業医 từ 50 thành 10 người.","Nhầm 総括安全衛生管理者 với 安全衛生管理者.","Nhầm 強度率 với 度数率."],"vocabulary":[{"word":"安全衛生管理体制","reading":"あんぜんえいせいかんりたいせい","meaning":"hệ thống quản lý an toàn vệ sinh"},{"word":"労働安全衛生法","reading":"ろうどうあんぜんえいせいほう","meaning":"Luật An toàn Vệ sinh Lao động"},{"word":"第3章","reading":"だいさんしょう","meaning":"chương 3"},{"word":"規制","reading":"きせい","meaning":"quy chế, quy định"},{"word":"総括安全衛生管理者","reading":"そうかつあんぜんえいせいかんりしゃ","meaning":"tổng quản lý an toàn vệ sinh"},{"word":"事業場","reading":"じぎょうじょう","meaning":"cơ sở kinh doanh, nhà máy"},{"word":"産業医","reading":"さんぎょうい","meaning":"bác sĩ công nghiệp"},{"word":"労働者","reading":"ろうどうしゃ","meaning":"người lao động"},{"word":"労働災害","reading":"ろうどうさいがい","meaning":"tai nạn lao động"},{"word":"強度率","reading":"きょうどりつ","meaning":"tỷ lệ cường độ"},{"word":"度数率","reading":"どすうりつ","meaning":"tần suất tai nạn"},{"word":"体制","reading":"たいせい","meaning":"hệ thống, cơ chế"},{"word":"総括","reading":"そうかつ","meaning":"tổng hợp, tổng quát"},{"word":"管理者","reading":"かんりしゃ","meaning":"người quản lý"},{"word":"選任","reading":"せんにん","meaning":"bổ nhiệm, chọn cử"},{"word":"被災","reading":"ひさい","meaning":"bị tai nạn, chịu thiệt hại"},{"word":"安全","reading":"あんぜん","meaning":"an toàn"},{"word":"衛生","reading":"えいせい","meaning":"vệ sinh"},{"word":"健康","reading":"けんこう","meaning":"sức khỏe"},{"word":"点検","reading":"てんけん","meaning":"kiểm tra"}]},{"id":"38","chapter":"4.安全衛生","question":{"japanese":"労働安全衛生法令で定められた特別教育を受けていれば従事できる業務に関する記述として最も適切なものは、次のうちどれか。","vietnamese":"Mô tả nào phù hợp nhất về công việc có thể đảm nhận nếu đã được đào tạo đặc biệt theo quy định của pháp luật an toàn vệ sinh lao động?","furigana":"労働[ろうどう]安全[あんぜん]衛生[えいせい]法令[ほうれい]で定め[さだめ]られた特別[とくべつ]教育[きょういく]を受け[うけ]ていれば従事[じゅうじ]できる業務[ぎょうむ]に関する[かんする]記述[きじゅつ]として最も[もっとも]適切[てきせつ]なものは、次[つぎ]のうちどれか。"},"options":[{"key":"ア","japanese":"つり上げ荷重が5トン以上のクレーンによる玉掛け業務","vietnamese":"Công việc móc hàng (玉掛け) bằng cần cẩu có tải trọng nâng từ 5 tấn trở lên","furigana":"つり上げ[あげ]荷重[かじゅう]が5トン以上[いじょう]のクレーンによる玉掛け[たまがけ]業務[ぎょうむ]"},{"key":"イ","japanese":"小型ボイラーを除くボイラー取扱業務","vietnamese":"Công việc vận hành nồi hơi trừ nồi hơi cỡ nhỏ","furigana":"小型[こがた]ボイラーを除く[のぞく]ボイラー取扱[とりあつかい]業務[ぎょうむ]"},{"key":"ウ","japanese":"つり上げ荷重が10トン以上のクレーンの運転業務","vietnamese":"Công việc vận hành cần cẩu có tải trọng nâng từ 10 tấn trở lên","furigana":"つり上げ[あげ]荷重[かじゅう]が10トン以上[いじょう]のクレーンの運転[うんてん]業務[ぎょうむ]"},{"key":"エ","japanese":"最大荷重1トン未満のフォークリフトの運転業務","vietnamese":"Công việc vận hành xe nâng có tải trọng tối đa dưới 1 tấn","furigana":"最大[さいだい]荷重[かじゅう]1トン未満[みまん]のフォークリフトの運転[うんてん]業務[ぎょうむ]"}],"correct_answer":"エ","explanation":{"correct_reason":"Xe nâng (フォークリフト) có tải trọng tối đa dưới 1 tấn chỉ cần 特別教育 (đào tạo đặc biệt), không cần giấy phép/技能講習. Từ 1 tấn trở lên mới cần 技能講習.","incorrect_reasons":{"ア":"Sai vì 玉掛け với cần cẩu từ 1 tấn trở lên cần 技能講習, không chỉ 特別教育.","イ":"Sai vì vận hành nồi hơi (trừ nồi hơi nhỏ) cần 技能講習/免許.","ウ":"Sai vì vận hành cần cẩu từ 5 tấn trở lên cần 技能講習.","エ":"Đây là đáp án đúng vì xe nâng dưới 1 tấn chỉ cần 特別教育."}},"key_knowledge":["Phân cấp năng lực làm việc nguy hiểm theo Luật An toàn Vệ sinh Lao động (労働安全衛生法) gồm 3 cấp độ từ cao xuống thấp: Giấy phép (免許) > Khóa huấn luyện kỹ năng (技能講習) > Đào tạo đặc biệt (特別教育).","Đào tạo đặc biệt (特別教育) là khóa đào tạo ngắn hạn do người sử dụng lao động tự tổ chức hoặc gửi đi học đối với các công việc có tính chất nguy hiểm ở mức độ vừa phải theo luật định.","Quy định đối với xe nâng (フォークリフト): Tải trọng tối đa dưới 1 tấn (最大荷重1トン未満) chỉ cần hoàn thành đào tạo đặc biệt (特別教育); từ 1 tấn trở lên (1トン以上) bắt buộc phải có chứng chỉ huấn luyện kỹ năng (技能講習).","Quy định đối với thao tác móc cáp treo hàng (玉掛け): Áp dụng cho cần cẩu có tải trọng nâng dưới 1 tấn thì chỉ cần đào tạo đặc biệt (特別教育); từ 1 tấn trở lên bắt buộc phải qua khóa huấn luyện kỹ năng (技能講習).","Quy định đối với vận hành cần cẩu (クレーン運転): Tải trọng nâng dưới 5 tấn thường chỉ cần đào tạo đặc biệt (特別教育) hoặc huấn luyện kỹ năng loại nhỏ; từ 5 tấn trở lên bắt buộc phải có giấy phép vận hành cần cẩu (クレーン運転士免許).","Quy định đối với vận hành nồi hơi (ボイラー取扱): Nồi hơi thông thường (không phải loại nhỏ) bắt buộc phải có bằng kỹ sư nồi hơi (ボイラー技士免許); chỉ nồi hơi cực nhỏ hoặc lò hơi quy mô quy định mới dùng hình thức đào tạo thấp hơn.","Ứng dụng thực tế trong xưởng sản xuất: Người quản lý hiện trường phải kiểm tra kỹ bằng cấp và thẻ chứng nhận đào tạo của công nhân trước khi giao việc vận hành thiết bị nâng hạ để tránh vi phạm pháp luật nghiêm trọng."],"exam_traps":["Đổi ngưỡng tấn của xe nâng/cần cẩu.","Nhầm 特別教育 với 技能講習.","Áp 特別教育 cho nồi hơi."],"vocabulary":[{"word":"労働安全衛生法令","reading":"ろうどうあんぜんえいせいほうれい","meaning":"pháp lệnh an toàn vệ sinh lao động"},{"word":"特別教育","reading":"とくべつきょういく","meaning":"đào tạo đặc biệt"},{"word":"従事","reading":"じゅうじ","meaning":"đảm nhận công việc"},{"word":"技能講習","reading":"ぎのうこうしゅう","meaning":"khóa đào tạo kỹ năng"},{"word":"つり上げ荷重","reading":"つりあげかじゅう","meaning":"tải trọng nâng"},{"word":"クレーン","reading":"クレーン","meaning":"cần cẩu"},{"word":"玉掛け","reading":"たまがけ","meaning":"móc hàng, buộc hàng"},{"word":"小型ボイラー","reading":"こがたボイラー","meaning":"nồi hơi cỡ nhỏ"},{"word":"ボイラー取扱業務","reading":"ボイラーとりあつかいぎょうむ","meaning":"công việc vận hành nồi hơi"},{"word":"最大荷重","reading":"さいだいかじゅう","meaning":"tải trọng tối đa"},{"word":"フォークリフト","reading":"フォークリフト","meaning":"xe nâng"},{"word":"運転業務","reading":"うんてんぎょうむ","meaning":"công việc vận hành"},{"word":"取扱業務","reading":"とりあつかいぎょうむ","meaning":"công việc vận hành, xử lý"},{"word":"免許","reading":"めんきょ","meaning":"giấy phép"},{"word":"法令","reading":"ほうれい","meaning":"pháp lệnh"},{"word":"資格","reading":"しかく","meaning":"tư cách, chứng chỉ"},{"word":"技能","reading":"ぎのう","meaning":"kỹ năng"},{"word":"講習","reading":"こうしゅう","meaning":"khóa đào tạo"},{"word":"安全","reading":"あんぜん","meaning":"an toàn"},{"word":"危険","reading":"きけん","meaning":"nguy hiểm"},{"word":"資格者","reading":"しかくしゃ","meaning":"người có chứng chỉ"}]},{"id":"39","chapter":"5.環境管理","question":{"japanese":"土壌の有害物質に関する法規制として最も不適切なものは、次のうちどれか。","vietnamese":"Trong các quy định pháp luật về chất độc hại trong đất, quy định nào KHÔNG phù hợp nhất?","furigana":"土壌[どじょう]の有害[ゆうがい]物質[ぶっしつ]に関する[かんする]法規[ほうき]制[せい]として最も[もっとも]不適切[ふてきせつ]なものは、次[つぎ]のうちどれか。"},"options":[{"key":"ア","japanese":"水質汚濁防止法に基づく、工場・事業場からの排水規制や有害物質を含む水の地下浸透禁止","vietnamese":"Quy định về nước thải từ nhà máy/cơ sở và cấm thấm xuống đất của nước chứa chất độc hại theo Luật Phòng chống ô nhiễm nước.","furigana":"水質[すいしつ]汚濁[おだく]防止法[ぼうしほう]に基づく[もとづく]、工場[こうじょう]・事業[じぎょう]場[じょう]からの排水[はいすい]規制[きせい]や有害[ゆうがい]物質[ぶっしつ]を含む[ふくむ]水[みず]の地下[ちか]浸透[しんとう]禁止[きんし]"},{"key":"イ","japanese":"大気汚染防止法に基づく、工場・事業場からの一般粉じんの排出規制","vietnamese":"Quy định về thải bụi thông thường từ nhà máy/cơ sở theo Luật Phòng chống ô nhiễm không khí.","furigana":"大気[たいき]汚染[おせん]防止法[ぼうしほう]に基づく[もとづく]、工場[こうじょう]・事業[じぎょう]場[じょう]からの一般[いっぱん]粉じん[ふんじん]の排出[はいしゅつ]規制[きせい]"},{"key":"ウ","japanese":"廃棄物の処理及び清掃に関する法律による有害廃棄物の埋め立て方法の規制","vietnamese":"Quy định về phương pháp chôn lấp chất thải độc hại theo Luật Xử lý chất thải và vệ sinh.","furigana":"廃棄物[はいきぶつ]の処理[しょり]及び[および]清掃[せいそう]に関する[かんする]法律[ほうりつ]による有害[ゆうがい]廃棄物[はいきぶつ]の埋め立て[うめたて]方法[ほうほう]の規制[きせい]"},{"key":"エ","japanese":"土壌汚染対策法に基づく、有害物質使用特定施設が廃止された土地などの土壌汚染調査の義務","vietnamese":"Nghĩa vụ điều tra ô nhiễm đất tại khu đất có cơ sở sử dụng chất độc hại bị bãi bỏ theo Luật Đối sách ô nhiễm đất.","furigana":"土壌[どじょう]汚染[おせん]対策法[たいさくほう]に基づく[もとづく]、有害[ゆうがい]物質[ぶっしつ]使用[しよう]特定[とくてい]施設[しせつ]が廃止[はいし]された土地[とち]などの土壌[どじょう]汚染[おせん]調査[ちょうさ]の義務[ぎむ]"}],"correct_answer":"イ","explanation":{"correct_reason":"Đề hỏi quy định về chất độc hại trong ĐẤT. 一般粉じん (bụi thông thường) theo Luật Phòng chống ô nhiễm không khí là quy định về không khí, không phải về chất độc hại trong đất. Vì vậy イ không phù hợp với chủ đề.","incorrect_reasons":{"ア":"Sai vì cấm thấm nước độc hại xuống đất liên quan trực tiếp đến đất.","イ":"Đây là đáp án đúng vì đây là quy định về không khí, không thuộc chủ đề đất.","ウ":"Sai vì quy định chôn lấp chất thải độc hại liên quan đến đất.","エ":"Sai vì điều tra ô nhiễm đất theo Luật Đối sách ô nhiễm đất là đúng chủ đề."}},"key_knowledge":["Luật Đối sách ô nhiễm đất (土壌汚染対策法): Quy định nghĩa vụ điều tra ô nhiễm đất (土壌汚染調査) khi doanh nghiệp bãi bỏ cơ sở sản xuất có sử dụng chất độc hại đặc định (有害物質使用特定施設) hoặc khi cải tạo đất diện tích lớn từ 3.000m² trở lên.","Luật Phòng chống ô nhiễm nước (水質汚濁防止法) liên quan đến đất: Ngoài quy định nước thải ra sông ngòi, luật nghiêm cấm hành vi để nước chứa chất độc hại ngấm xuống lòng đất (地下浸透禁止) nhằm bảo vệ đất và tầng nước ngầm.","Luật Xử lý chất thải (廃棄物処理法) liên quan đến đất: Kiểm soát chặt chẽ phương pháp chôn lấp (埋め立て) rác thải công nghiệp độc hại (chẳng hạn yêu cầu bãi chôn lấp cách ly chuyên dụng - 遮断型処分場) để hóa chất không thẩm thấu vào lòng đất.","Luật Phòng chống ô nhiễm không khí (大気汚染防止法): Tập trung kiểm soát phát thải khí độc, khói (ばい煙), bụi thông thường (一般粉じん) và hợp chất hữu cơ bay hơi (VOC); đối tượng bảo vệ là môi trường không khí chứ không phải là đất.","Mối liên hệ giữa các luật môi trường: Ô nhiễm đất (土壌汚染) là hậu quả gián tiếp từ việc xả thải nước ngầm độc hại hoặc chôn rác sai quy định, vì vậy cả Luật Nước và Luật Rác thải đều có điều khoản ngăn ngừa độc hại cho đất.","Các chất độc hại điển hình trong đất: Bao gồm kim loại nặng (chì - 鉛, cadimi - カドミウム, asen - ヒ素), dung môi hữu cơ dễ bay hơi gốc Clo (trichloroethylene...) tích tụ lâu năm gây độc khi con người uống nước ngầm hoặc tiếp xúc trực tiếp.","Ứng dụng trong nhà máy sản xuất: Trước khi mua, bán hoặc đóng cửa phân xưởng sản xuất có dùng hóa chất, doanh nghiệp bắt buộc phải tra cứu lịch sử khu đất và thực hiện đánh giá môi trường (Environmental Site Assessment) theo đúng quy định."],"exam_traps":["Đưa quy định về không khí vào chủ đề đất.","Nhầm 水質汚濁防止法 với 土壌汚染対策法.","Nhầm 一般粉じん với 特定粉じん (chất gây ung thư như amiăng)."],"vocabulary":[{"word":"土壌","reading":"どじょう","meaning":"đất"},{"word":"有害物質","reading":"ゆうがいぶっしつ","meaning":"chất độc hại"},{"word":"法規制","reading":"ほうきせい","meaning":"quy định pháp luật"},{"word":"水質汚濁防止法","reading":"すいしつおだくぼうしほう","meaning":"Luật Phòng chống ô nhiễm nước"},{"word":"排水規制","reading":"はいすいきせい","meaning":"quy định nước thải"},{"word":"地下浸透","reading":"ちかしんとう","meaning":"thấm xuống đất"},{"word":"大気汚染防止法","reading":"たいきおせんぼうしほう","meaning":"Luật Phòng chống ô nhiễm không khí"},{"word":"一般粉じん","reading":"いっぱんふんじん","meaning":"bụi thông thường"},{"word":"排出規制","reading":"はいしゅつきせい","meaning":"quy định thải ra"},{"word":"廃棄物の処理及び清掃に関する法律","reading":"はいきぶつのしょりおよびせいそうにかんするほうりつ","meaning":"Luật Xử lý chất thải và vệ sinh"},{"word":"埋め立て","reading":"うめたて","meaning":"chôn lấp"},{"word":"土壌汚染対策法","reading":"どじょうおせんたいさくほう","meaning":"Luật Đối sách ô nhiễm đất"},{"word":"有害物質使用特定施設","reading":"ゆうがいぶっしつしようとくていしせつ","meaning":"cơ sở đặc định sử dụng chất độc hại"},{"word":"排水","reading":"はいすい","meaning":"nước thải"},{"word":"粉じん","reading":"ふんじん","meaning":"bụi"},{"word":"排出","reading":"はいしゅつ","meaning":"thải ra"},{"word":"廃棄物","reading":"はいきぶつ","meaning":"chất thải"},{"word":"規制","reading":"きせい","meaning":"quy định, chế tài"},{"word":"義務","reading":"ぎむ","meaning":"nghĩa vụ"}]},{"id":"40","chapter":"5.環境管理","question":{"japanese":"PDCAサイクルの各項目とISO14001:2015環境マネジメントシステムの要求事項の対応として最も不適切なものは、次のうちどれか。\n＜PDCA＞ ＜ISO14001要求事項＞\nア、Plan 計画\nイ. Do 支援及び運用\nウ、Check パフォーマンス評価\nエ Act 実施","vietnamese":"Tổ hợp nào KHÔNG phù hợp nhất giữa các mục của chu trình PDCA và yêu cầu của hệ thống quản lý môi trường ISO14001:2015?\n<PDCA> <Yêu cầu ISO14001>\nア. Plan – Kế hoạch\nイ. Do – Hỗ trợ và vận hành\nウ. Check – Đánh giá hiệu suất\nエ. Act – Thực hiện","furigana":"PDCAサイクルの各項目[かくこうもく]とISO14001:2015環境[かんきょう]マネジメントシステムの要求[ようきゅう]事項[じこう]の対応[たいおう]として最も[もっとも]不適切[ふてきせつ]なものは、次[つぎ]のうちどれか。\n＜PDCA＞ ＜ISO14001要求[ようきゅう]事項[じこう]＞\nア、Plan 計画[けいかく]\nイ. Do 支援[しえん]及び[および]運用[うんよう]\nウ、Check パフォーマンス評価[ひょうか]\nエ Act 実施[じっし]"},"options":[{"key":"ア","japanese":"Plan 計画","vietnamese":"Plan – Kế hoạch","furigana":"Plan 計画[けいかく]"},{"key":"イ","japanese":"Do 支援及び運用","vietnamese":"Do – Hỗ trợ và vận hành","furigana":"Do 支援[しえん]及び[および]運用[うんよう]"},{"key":"ウ","japanese":"Check パフォーマンス評価","vietnamese":"Check – Đánh giá hiệu suất","furigana":"Check パフォーマンス評価[ひょうか]"},{"key":"エ","japanese":"Act 実施","vietnamese":"Act – Thực hiện","furigana":"Act 実施[じっし]"}],"correct_answer":"エ","explanation":{"correct_reason":"Trong ISO14001:2015, Act (改善) tương ứng với 改善 (cải tiến), không phải 実施 (thực hiện). 実施 (行动) thuộc Do. Vì vậy エ không phù hợp.","incorrect_reasons":{"ア":"Sai vì Plan tương ứng 計画 là đúng.","イ":"Sai vì Do tương ứng 支援及び運用 là đúng.","ウ":"Sai vì Check tương ứng パフォーマンス評価 là đúng.","エ":"Đây là đáp án đúng vì Act phải là 改善 (cải tiến), không phải 実施."}},"key_knowledge":["Hệ thống quản lý môi trường (環境マネジメントシステム - EMS) theo tiêu chuẩn ISO 14001:2015 áp dụng cấu trúc bậc cao (HLS) và vận hành hoàn toàn dựa trên chu trình PDCA.","Giai đoạn Plan (Kế hoạch): Tương ứng với Điều khoản 6 - Lập kế hoạch (計画), bao gồm việc xác định khía cạnh môi trường (環境側面), rủi ro, cơ hội và thiết lập các mục tiêu môi trường cụ thể cho nhà máy.","Giai đoạn Do (Thực hiện/Vận hành): Tương ứng với Điều khoản 7 - Hỗ trợ (支援) và Điều khoản 8 - Vận hành (運用), bao gồm phân bổ nguồn lực, đào tạo nhận thức, quản lý thông tin văn bản và kiểm soát các tác nghiệp sản xuất thực tế.","Giai đoạn Check (Kiểm tra): Tương ứng với Điều khoản 9 - Đánh giá kết quả hoạt động (パフォーマンス評価), bao gồm việc giám sát, đo lường các chỉ số môi trường, đánh giá nội bộ (内部監査) và họp xem xét của lãnh đạo (マネジメントレビュー).","Giai đoạn Act (Cải tiến/Xử lý): Tương ứng với Điều khoản 10 - Cải tiến (改善), tập trung vào xử lý sự không phù hợp (不適合), thực hiện hành động khắc phục và thúc đẩy cải tiến liên tục (継続的改善).","Phân biệt 'Thực hiện' (実施) và 'Cải tiến' (改善): Hoạt động thực hiện/triển khai công việc hàng ngày (実施・運用) thuộc về Do; trong khi Act mang ý nghĩa hành động sửa chữa, khắc phục sai lệch và nâng cấp quy trình (改善).","Vai trò trung tâm của Lãnh đạo (リーダーシップ): Điều khoản 5 - Lãnh đạo nằm ở vị trí trung tâm, giữ vai trò cam kết chính sách môi trường và dẫn dắt toàn bộ chu trình PDCA vận hành trơn tru.","Ứng dụng thực tế tại nhà máy: Phân loại rác thải độc hại tại xưởng là khâu Vận hành (Do), đo lường chỉ số nước thải hàng tháng là Đánh giá (Check), và tìm nguyên nhân để xử lý triệt để khi chỉ số vượt ngưỡng cho phép chính là Cải tiến (Act)."],"exam_traps":["Gán Act cho 実施 thay vì 改善.","Nhầm Check với 監査.","Đảo Do và Act."],"vocabulary":[{"word":"PDCAサイクル","reading":"PDCAサイクル","meaning":"chu trình PDCA"},{"word":"項目","reading":"こうもく","meaning":"mục, hạng mục"},{"word":"要求事項","reading":"ようきゅうじこう","meaning":"yêu cầu"},{"word":"環境マネジメントシステム","reading":"かんきょうマネジメントシステム","meaning":"hệ thống quản lý môi trường"},{"word":"計画","reading":"けいかく","meaning":"kế hoạch"},{"word":"支援","reading":"しえん","meaning":"hỗ trợ"},{"word":"運用","reading":"うんよう","meaning":"vận hành"},{"word":"パフォーマンス評価","reading":"パフォーマンスひょうか","meaning":"đánh giá hiệu suất"},{"word":"実施","reading":"じっし","meaning":"thực hiện"},{"word":"改善","reading":"かいぜん","meaning":"cải tiến"},{"word":"対応","reading":"たいおう","meaning":"tương ứng, đối ứng"},{"word":"継続的","reading":"けいぞくてき","meaning":"mang tính liên tục"},{"word":"PDCA","reading":"ピーディーシーエー","meaning":"chu trình PDCA"},{"word":"方針","reading":"ほうしん","meaning":"chính sách, phương châm"},{"word":"目標","reading":"もくひょう","meaning":"mục tiêu"},{"word":"環境","reading":"かんきょう","meaning":"môi trường"},{"word":"順序","reading":"じゅんじょ","meaning":"thứ tự"},{"word":"継続的改善","reading":"けいぞくてきかいぜん","meaning":"cải tiến liên tục"}]}];
